window.QUIZ_DB = {"chapters":[{"id":"l2-data-preprocessing","title":"L2. data preprocessing","summary":["Tiền xử lý dữ liệu (Data Pre-processing) là giai đoạn nền tảng chiếm đến gần 80% ngân sách thời gian trong vòng đời phát triển của một dự án Khoa học dữ liệu và Học máy (với 19% cho thu thập và 60% cho làm sạch, tổ chức dữ liệu). Trong thực tế, dữ liệu thu thập từ các nguồn giao dịch, cảm biến hay trang web thường ở dạng thô, chịu ảnh hưởng nghiêm trọng bởi nhiễu, giá trị thiếu (missing values) và sự không nhất quán (inconsistency). Trong khi đó, các thuật toán học máy chỉ có thể tiếp nhận và vận hành hiệu quả trên các cấu trúc dữ liệu số hóa dạng vectơ hoặc ma trận. Do đó, việc chuyển đổi dữ liệu thô thành tập dữ liệu có chất lượng đạt các tiêu chuẩn về Tính đầy đủ (Completeness), Tính trung thực (Integrity), Tính đồng nhất (Homogeneity) và Tính cấu trúc (Structure) là điều kiện tiên quyết quyết định sự thành bại của hệ thống.","Quy trình tiền xử lý dữ liệu bao gồm chuỗi các kỹ thuật liên hoàn từ Thu thập, Làm sạch, Tích hợp đến Biến đổi và Rút gọn dữ liệu. Ở bước làm sạch, các chiến lược xử lý giá trị thiếu (từ bỏ qua bản ghi, điền giá trị trung bình/trung vị theo lớp, đến dự đoán bằng mô hình xác suất) kết hợp cùng các kỹ thuật làm mịn dữ liệu nhiễu (Binning, Hồi quy, Phân cụm) giúp khắc phục hiện tượng lệch phân phối do điểm ngoại lệ (outliers) gây ra. Giai đoạn biến đổi dữ liệu thực hiện chuẩn hóa thuộc tính (Min-Max Normalization, Z-score Standardization) nhằm triệt tiêu sự lấn át của các thuộc tính có miền giá trị lớn trong các thuật toán tính khoảng cách hình học, đồng thời tiến hành rời rạc hóa (Discretization) và mã hóa One-Hot để biến đổi các đặc trưng định danh thành dạng biểu diễn số phù hợp.","Ở mức độ kỹ thuật nâng cao, đối với dữ liệu phi cấu trúc như văn bản (Text Data), quy trình tiền xử lý thiết lập pipeline chuyển đổi chuyên biệt từ Phân đoạn từ (Tokenization), Lọc từ dừng (Stopwords Filtering), Xây dựng từ điển đến Mã hóa vectơ số thực thông qua kỹ thuật TF-IDF. Song song với đó, các chiến lược Rút gọn dữ liệu (Data Reduction) thông qua Lựa chọn thuộc tính (Feature Selection) và Giảm số chiều không gian (PCA, ICA) giúp nén kích thước dữ liệu nhưng vẫn giữ nguyên ngữ nghĩa cốt lõi (core semantics). Sự kết hợp chặt chẽ giữa các kỹ thuật tiền xử lý này tuân thủ nghiêm ngặt nguyên lý \"Garbage in, Garbage out\", bảo đảm mô hình học máy duy trì khả năng tổng quát hóa tối ưu và tránh được các cạm bẫy do nhiễu hệ thống gây ra."],"topics":[{"id":1,"title":"Ngân sách Thời gian & Động cơ Tiền xử lý","summary":["Thống kê thực nghiệm trong ngành Khoa học Dữ liệu chỉ ra rằng các kỹ sư phải dành tới 60% tổng thời gian cho việc làm sạch, tổ chức dữ liệu và 19% thời gian cho việc thu thập, trong khi thời gian cho việc huấn luyện mô hình hay tinh chỉnh thuật toán chỉ chiếm dưới 15%. Dữ liệu thực tế phát sinh từ các hệ thống phân tán thường gặp phải tình trạng thiếu hụt thuộc tính, chứa nhiều dữ liệu rác hoặc sai lệch đơn vị đo lường.","Động cơ cốt lõi của tiền xử lý là thu hẹp khoảng cách giữa dạng biểu diễn tự nhiên của dữ liệu thô (văn bản, hình ảnh, âm thanh) và đầu vào bắt buộc của các thuật toán học máy (ma trận, vectơ số thực). Một tập dữ liệu được chuẩn hóa và trích xuất đặc trưng phù hợp không chỉ giúp lưu trữ và truy vấn thuận tiện mà còn quyết định trực tiếp đến độ chính xác và khả năng hội tụ của mô hình."],"questions":[{"id":1,"text":"Trong ngân sách thời gian thực tế của một dự án Khoa học dữ liệu và Học máy, sự phân bổ thời gian cho các công đoạn được thống kê ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Công đoạn làm sạch và tổ chức dữ liệu chiếm tỷ trọng lớn nhất với khoảng 60% tổng thời gian dự án."},{"k":"B","t":"Công đoạn thu thập dữ liệu chiếm khoảng 19% tổng thời gian triển khai hệ thống."},{"k":"C","t":"Công đoạn huấn luyện mô hình và tinh chỉnh thuật toán chiếm hơn 80% tổng thời gian dự án."},{"k":"D","t":"Công đoạn dán nhãn dữ liệu thủ công luôn chiếm cố định đúng 50% thời gian ở mọi dự án học máy."}],"answer":["A","B"]},{"id":2,"text":"Động cơ kỹ thuật cốt lõi của việc tiến hành tiền xử lý dữ liệu trước khi đưa vào các thuật toán học máy là gì?","multiple":false,"options":[{"k":"A","t":"Tự động gia tăng số lượng thuộc tính đầu vào lên gấp 10 lần để đảm bảo tính tổng quát hóa."},{"k":"B","t":"Chuyển đổi dữ liệu thô thành dạng số cấu trúc (ma trận, vectơ) phù hợp với các thuật toán học máy."},{"k":"C","t":"Triệt tiêu hoàn toàn các tập dữ liệu có số chiều vượt quá 5 thuộc tính trước khi lưu trữ."},{"k":"D","t":"Bắt buộc loại bỏ toàn bộ các mẫu dữ liệu có chứa giá trị số thực âm trong tập huấn luyện."}],"answer":["B"]}]},{"id":2,"title":"Quy trình Khám phá Tri thức & Vòng đời ML","summary":["Vòng đời phát triển một hệ thống học máy (ML Lifecycle) tuân theo quy trình chuẩn từ Hiểu bài toán (Business understanding), Xác định yêu cầu dữ liệu (Data requirements), Thu thập (Data collection), Hiểu dữ liệu (Data understanding), Tiền xử lý (Data preparation) đến Mô hình hóa (Modeling), Đánh giá (Evaluation) và Triển khai (Deployment). Mỗi giai đoạn đều có mối liên kết phản hồi ngược để điều chỉnh các bước trước đó khi phát hiện sai sót.","Vị trí của tiền xử lý dữ liệu đóng vai trò là chiếc cầu nối kỹ thuật giữa dữ liệu thô thu thập được và các thuật toán học máy. Nếu dữ liệu tiền xử lý bị lệch hoặc mất mát thông tin cốt lõi, giai đoạn mô hình hóa chắc chắn sẽ thất bại theo nguyên lý \"Garbage in, Garbage out\", bất kể thuật toán học máy được chọn có phức tạp hay hiện đại đến đâu."],"questions":[{"id":3,"text":"Trong quy trình phát triển hệ thống học máy (ML Lifecycle), vai trò và mối quan hệ của bước Thu thập và Tiền xử lý dữ liệu được thể hiện ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tiền xử lý dữ liệu là cầu nối kỹ thuật chuyển đổi dữ liệu thô thành tập dữ liệu D sẵn sàng cho bước Modeling."},{"k":"B","t":"Bước Evaluation hoàn toàn độc lập và không thể phản hồi ngược lại để chỉnh sửa bước Data preparation."},{"k":"C","t":"Kết quả của bước Data understanding cung cấp tri thức quan trọng về độ trống và tính chất dữ liệu cho bước tiền xử lý."},{"k":"D","t":"Quá trình thu thập dữ liệu chỉ được phép thực hiện đúng một lần và không bao giờ được thay đổi yêu cầu."}],"answer":["A","C"]},{"id":4,"text":"Hệ quả trực tiếp đối với mô hình học máy khi dữ liệu đầu vào không được làm sạch cẩn thận tuân theo nguyên lý kỹ thuật nào?","multiple":false,"options":[{"k":"A","t":"Mô hình tự động tối ưu hóa các tham số để loại bỏ nhiễu mà không ảnh hưởng tới kết quả."},{"k":"B","t":"Thuật toán học máy sẽ tự động tạo ra thêm các thuộc tính mới để bù đắp thông tin bị thiếu."},{"k":"C","t":"Kết quả khai phá và dự báo bị sai lệch nghiêm trọng theo nguyên lý \"Garbage in, Garbage out\"."},{"k":"D","t":"Độ chính xác của mô hình trên tập kiểm thử sẽ tự động tăng lên nhờ các giá trị ngoại lệ."}],"answer":["C"]}]},{"id":3,"title":"Tiêu chí Chất lượng Dữ liệu Thô","summary":["Một tập dữ liệu thô đạt chất lượng cao phục vụ cho bài toán học máy phải thỏa mãn 4 tiêu chuẩn kỹ thuật nền tảng: Tính đầy đủ (Completeness - mỗi mẫu phải chứa đủ các thuộc tính yêu cầu), Tính trung thực (Integrity - dữ liệu phản ánh chính xác thực tế từ nguồn tin cậy), Tính đồng nhất (Homogeneity - nhất quán về lược đồ và đơn vị đo) và Tính cấu trúc (Structure - có khả năng số hóa).","Trong thực tế thu thập, dữ liệu rất dễ vướng phải nhiễu hệ thống có chủ đích (intentional systematic noise), điển hình như việc người dùng điền ngày 01/01 làm ngày sinh mặc định để tránh tiết lộ thông tin cá nhân. Việc nhận diện và loại bỏ các dạng nhiễu hệ thống này yêu cầu các kỹ thuật kiểm tra tính nhất quán nâng cao trước khi đưa dữ liệu vào pipeline huấn luyện."],"questions":[{"id":5,"text":"Bốn tiêu chí kỹ thuật nền tảng để đánh giá chất lượng của một tập dữ liệu thô bao gồm những thuộc tính nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tính đầy đủ (Completeness) đảm bảo mỗi mẫu thu thập đều chứa đủ các thuộc tính yêu cầu."},{"k":"B","t":"Tính đồng nhất (Homogeneity) yêu cầu các nguồn dữ liệu phải duy trì sự nhất quán về lược đồ và định dạng."},{"k":"C","t":"Tính đóng đóng vai trò bắt buộc tất cả các trường dữ liệu phải được mã hóa dưới dạng chuỗi văn bản."},{"k":"D","t":"Tính vô hạn đòi hỏi tập dữ liệu huấn luyện phải chứa toàn bộ các đối tượng trong thực tế."}],"answer":["A","B"]},{"id":6,"text":"Hiện tượng \"nhiễu hệ thống có chủ đích\" (intentional systematic noise) trong dữ liệu thô thường xuất hiện dưới dạng nào?","multiple":false,"options":[{"k":"A","t":"Việc đa số người dùng chọn ngày 01/01 làm ngày sinh mặc định để bảo vệ thông tin cá nhân."},{"k":"B","t":"Lỗi ngẫu nhiên do đường truyền mạng bị ngắt kết nối đột ngột trong khi thu thập dữ liệu."},{"k":"C","t":"Việc cảm biến phần cứng bị hỏng và tạo ra các giá trị đo bằng 0 ở một vài thời điểm ngẫu nhiên."},{"k":"D","t":"Sự biến động giá cổ phiếu do ảnh hưởng từ các sự kiện kinh tế không lường trước."}],"answer":["A"]}]},{"id":4,"title":"Phương pháp Thu thập Dữ liệu & Lấy mẫu","summary":["Giai đoạn thu thập dữ liệu (Data collection) áp dụng nguyên lý Lấy mẫu (Sampling) nhằm rút ra một tập hợp nhỏ đại diện cho toàn bộ quần thể dữ liệu lớn. Tập mẫu thu được bắt buộc phải đảm bảo Tính đa dạng (Variety) và Không thiên lệch (Unbiased) để phản ánh trung thực phân phối thực tế của bài toán.","Ba kỹ thuật thu thập dữ liệu phổ biến bao gồm: Crowdsourcing (tiến hành khảo sát, dán nhãn cộng đồng), Logging (ghi lại nhật ký lịch sử tương tác của người dùng trên hệ thống) và Scraping/Crawling (tự động tìm kiếm, tải xuống và bóc tách dữ liệu công khai từ các trang web). Lựa chọn kỹ thuật thu thập phải cân bằng giữa chi phí thực hiện và độ trung thực của tập dữ liệu mục tiêu."],"questions":[{"id":7,"text":"Trong giai đoạn thu thập dữ liệu, nguyên lý Lấy mẫu (Sampling) đòi hỏi tập dữ liệu thu được phải thỏa mãn các yêu cầu gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tập mẫu phải có kích thước nhỏ gọn nhưng mang tính đại diện cao (representative) cho toàn bộ quần thể."},{"k":"B","t":"Tập mẫu thu được bắt buộc phải chứa đúng 100% số lượng mẫu quan sát của toàn bộ quần thể thực tế."},{"k":"C","t":"Tập mẫu phải có độ đa dạng (Variety) và tránh bị thiên lệch (Unbiased) để phản ánh đúng thực tế."},{"k":"D","t":"Việc lấy mẫu phải được thực hiện bằng cách chỉ chọn các đối tượng dữ liệu dễ truy cập nhất."}],"answer":["A","C"]},{"id":8,"text":"Sự khác biệt cốt lõi giữa hai kỹ thuật thu thập dữ liệu Logging và Scraping là gì?","multiple":false,"options":[{"k":"A","t":"Logging chỉ áp dụng cho dữ liệu hình ảnh, còn Scraping chỉ áp dụng cho dữ liệu bảng số liệu."},{"k":"B","t":"Logging ghi lại lịch sử sự kiện/tương tác trên hệ thống nội bộ, còn Scraping bóc tách dữ liệu từ web công khai."},{"k":"C","t":"Scraping đòi hỏi phải dán nhãn thủ công từng mẫu, còn Logging tự động tạo ra mô hình phân loại."},{"k":"D","t":"Logging hoàn toàn không tốn tài nguyên lưu trữ, còn Scraping bắt buộc phải dùng phần cứng cảm biến."}],"answer":["B"]}]},{"id":5,"title":"Kỹ thuật Cào Dữ liệu Web","summary":["Cào dữ liệu web (Web Scraping & Crawling) là phương pháp tự động hóa quá trình truy cập các địa chỉ URL, tải về nội dung mã nguồn HTML/XML và bóc tách các trường thông tin cần thiết. Đối với dữ liệu tin tức hoặc bài viết, hệ thống thường sử dụng các luồng RSS feed để lấy danh sách liên kết bài viết mới nhất trước khi trích xuất nội dung chi tiết.","Các công cụ phần mềm như BeautifulSoup, Scrapy hay Selenium được sử dụng linh hoạt tùy thuộc vào độ phức tạp của trang web mục tiêu (trang web tĩnh hoặc trang web động sử dụng JavaScript). Dữ liệu sau khi bóc tách được chuyển đổi và lưu trữ dưới các định dạng cấu trúc chuẩn như JSON hoặc XML kèm theo các nhãn phân loại phục vụ cho các bài toán xử lý ngôn ngữ tự nhiên."],"questions":[{"id":9,"text":"Quy trình cào tin tức tự động từ các trang báo điện tử thông qua RSS feed bao gồm các bước kỹ thuật nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Quét luồng RSS feed để lấy danh sách các đường liên kết (URL) bài viết mới nhất."},{"k":"B","t":"Trích xuất nội dung HTML của bài viết, bóc tách văn bản và lưu trữ dưới dạng cấu trúc JSON/XML."},{"k":"C","t":"Tự động thay đổi nội dung bài gốc trên trang báo điện tử sau khi hoàn tất quá trình cào dữ liệu."},{"k":"D","t":"Chuyển đổi mã nguồn HTML trực tiếp thành các tệp âm thanh WAV để huấn luyện mạng nơ-ron."}],"answer":["A","B"]},{"id":10,"text":"Khi thực hiện cào dữ liệu trên các trang web động có cấu trúc phức tạp sử dụng JavaScript, công cụ nào sau đây tỏ ra phù hợp nhất?","multiple":false,"options":[{"k":"A","t":"BeautifulSoup thuần túy kết hợp với thư viện urllib cơ bản."},{"k":"B","t":"Selenium hoặc Scrapy có khả năng giả lập tương tác trình duyệt và chờ tải trang động."},{"k":"C","t":"Thuật toán K-means tích hợp trực tiếp trong cơ sở dữ liệu SQL."},{"k":"D","t":"Công cụ chuẩn hóa dữ liệu Z-score chạy trên môi trường không kết nối mạng."}],"answer":["B"]}]},{"id":6,"title":"Làm sạch Dữ liệu & Xử lý Giá trị Thiếu","summary":["Làm sạch dữ liệu (Data Cleaning) tập trung giải quyết hiện tượng thiếu giá trị (missing values) phát sinh do lỗi kỹ thuật thu thập hoặc người dùng từ chối cung cấp. Khi một bản ghi bị thiếu nhãn mục tiêu hoặc thiếu quá nhiều thuộc tính quan trọng, chiến lược tối ưu nhất là loại bỏ hoàn toàn bản ghi đó khỏi tập phân tích.","Đối với các trường thuộc tính bị thiếu thông thường, các phương pháp điền giá trị (imputation) được áp dụng bao gồm: điền thủ công, sử dụng hằng số toàn cục, điền bằng giá trị trung bình/trung vị của thuộc tính, điền bằng giá trị trung bình theo từng lớp nhãn (class-based mean), hoặc dự đoán giá trị khả dĩ nhất bằng các mô hình hồi quy và suy diễn Bayesian."],"questions":[{"id":11,"text":"Khi gặp phải hiện tượng giá trị bị thiếu (missing value) trong tập dữ liệu huấn luyện, các chiến lược xử lý chuẩn bao gồm những cách nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bỏ qua bản ghi nếu nhãn phân loại bị thiếu hoặc bản ghi chứa quá nhiều thuộc tính bị trống."},{"k":"B","t":"Tự động điền các giá trị ngẫu nhiên bất kỳ vào tất cả các vị trí trống mà không cần điều kiện."},{"k":"C","t":"Bắt buộc hủy bỏ toàn bộ tập dữ liệu và tiến hành thu thập lại từ đầu nếu có 1 giá trị bị thiếu."},{"k":"D","t":"Điền giá trị thiếu bằng trung vị của thuộc tính hoặc giá trị trung bình theo từng lớp nhãn."}],"answer":["A","D"]},{"id":12,"text":"Phương pháp điền giá trị thiếu nâng cao nào sau đây giúp nâng cao độ chính xác bằng cách sử dụng mối liên hệ giữa các thuộc tính?","multiple":false,"options":[{"k":"A","t":"Sử dụng một hằng số toàn cục duy nhất đại diện cho từ \"Unknown\" trên tất cả các cột."},{"k":"B","t":"Bỏ qua tất cả các cột có chứa dù chỉ một giá trị bị thiếu trong tập dữ liệu."},{"k":"C","t":"Xây dựng mô hình dự đoán (Hồi quy hoặc Suy diễn Bayesian) để tính giá trị khả dĩ nhất cho vị trí thiếu."},{"k":"D","t":"Gán giá trị 0 cho tất cả các trường dữ liệu có kiểu dữ liệu chuỗi ký tự."}],"answer":["C"]}]},{"id":7,"title":"Làm mịn Dữ liệu Nhiễu & Xử lý Điểm Ngoại lệ","summary":["Nhiễu dữ liệu (noise) và các điểm ngoại lệ (outliers) là các giá trị biến động ngẫu nhiên hoặc sai lệch nghiêm trọng so với phân phối chung, gây ảnh hưởng tiêu cực đến quá trình huấn luyện mô hình. Kỹ thuật Phân khoảng (Binning) tiến hành sắp xếp dữ liệu và chia thành các khoảng equal-width (độ rộng bằng nhau) hoặc equal-depth (số lượng mẫu bằng nhau), sau đó làm mịn bằng giá trị trung bình hoặc ranh giới khoảng.","Bên cạnh phân khoảng, hai phương pháp nâng cao để loại bỏ nhiễu là Hồi quy (Regression) và Phân cụm (Clustering). Mô hình hồi quy khớp một đường thẳng đại diện và thay thế các điểm có phần dư sai số quá lớn, trong khi phân cụm gom nhóm các dữ liệu tương đồng và tự động loại bỏ các điểm dữ liệu cô lập nằm ngoài tất cả các cụm chính."],"questions":[{"id":13,"text":"Kỹ thuật Phân khoảng (Binning) thực hiện làm mịn dữ liệu nhiễu dựa trên các cơ chế chia khoảng nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chia khoảng có độ rộng bằng nhau (Equal-width partitioning) trên miền giá trị thuộc tính."},{"k":"B","t":"Chia khoảng sao cho mỗi khoảng chứa số lượng mẫu bằng nhau (Equal-depth partitioning)."},{"k":"C","t":"Chia khoảng bằng cách nhân đôi giá trị của các điểm dữ liệu nhiễu để tạo sự cân bằng."},{"k":"D","t":"Bắt buộc chia dữ liệu thành đúng 2 khoảng duy nhất đại diện cho số âm và số dương."}],"answer":["A","B"]},{"id":14,"text":"Sự khác biệt về mặt kỹ thuật giữa phương pháp phân khoảng Equal-depth và Equal-width là gì?","multiple":false,"options":[{"k":"A","t":"Equal-depth chia khoảng có độ rộng bằng nhau, còn Equal-width chia số mẫu bằng nhau."},{"k":"B","t":"Equal-depth chia mỗi khoảng chứa số mẫu gần bằng nhau, còn Equal-width chia khoảng giá trị có khoảng cách bằng nhau."},{"k":"C","t":"Equal-depth chỉ áp dụng cho chuỗi văn bản, còn Equal-width chỉ áp dụng cho tệp hình ảnh."},{"k":"D","t":"Equal-depth bắt buộc loại bỏ điểm ngoại lệ, còn Equal-width giữ nguyên tất cả dữ liệu nhiễu."}],"answer":["B"]}]},{"id":8,"title":"Tích hợp Dữ liệu & Giải quyết Sự Xung đột","summary":["Tích hợp dữ liệu (Data Integration) là quá trình hợp nhất dữ liệu từ nhiều nguồn không nhất quán (CSDL quan hệ, bảng tính Excel, tệp JSON, luồng API) thành một kho dữ liệu đồng nhất. Quá trình này giúp loại bỏ sự dư thừa thông tin và tăng cường tính đầy đủ cho tập dữ liệu phân tích.","Thách thức kỹ thuật lớn nhất trong tích hợp dữ liệu là định danh thực thể (Entity Identification Problem) và giải quyết xung đột cấu trúc/giá trị. Các trường dữ liệu biểu diễn cùng một khái niệm nhưng khác tên gọi, hoặc khác biệt về đơn vị đo lường (ví dụ: khoảng cách tính bằng km và mile) phải được ánh xạ và chuẩn hóa về một lược đồ (schema) thống nhất."],"questions":[{"id":15,"text":"Quá trình Tích hợp dữ liệu (Data Integration) hướng tới các mục tiêu kỹ thuật cốt lõi nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hợp nhất dữ liệu từ nhiều nguồn không nhất quán thành một kho dữ liệu đồng nhất."},{"k":"B","t":"Giúp giảm thiểu sự dư thừa dữ liệu và loại bỏ sự xung đột lược đồ giữa các nguồn."},{"k":"C","t":"Nhân bản tất cả các bảng dữ liệu lên 3 lần để đảm bảo không bị mất mát thông tin."},{"k":"D","t":"Bắt buộc chuyển đổi tất cả dữ liệu bảng số liệu thành các tệp hình ảnh dạng PNG."}],"answer":["A","B"]},{"id":16,"text":"Thách thức kỹ thuật \"Định danh thực thể\" (Entity Identification Problem) trong tích hợp dữ liệu phát sinh khi nào?","multiple":false,"options":[{"k":"A","t":"Khi hai trường dữ liệu ở hai nguồn khác nhau biểu diễn cùng một đối tượng thực tế nhưng khác tên gọi."},{"k":"B","t":"Khi ma trận tích dữ liệu A^T * A bị suy biến và không thể tính được nghịch đảo."},{"k":"C","t":"Khi thuật toán K-means chọn sai số lượng cụm k ban đầu trong không gian Euclid."},{"k":"D","t":"Khi câu lệnh truy vấn SQL không thể kết nối tới máy chủ dữ liệu do lỗi mạng."}],"answer":["A"]}]},{"id":9,"title":"Biến đổi Dữ liệu & Chuẩn hóa Thuộc tính","summary":["Biến đổi dữ liệu (Data Transformation) thực hiện chia tỷ lệ các thuộc tính số thực về một phạm vi thu nhỏ xác định. Hai phương pháp chuẩn hóa kinh điển là Chuẩn hóa Min-Max (đưa giá trị về khoảng hoặc [-1, 1]) và Chuẩn hóa Z-score (chuyển đổi dữ liệu về phân bố có trung bình bằng 0 và độ lệch chuẩn bằng 1 theo công thức z = (x - mean) / std).","Ý nghĩa kỹ thuật bắt buộc của chuẩn hóa thuộc tính là ngăn chặn hiện tượng các thuộc tính có miền giá trị lớn (như Thu nhập: hàng chục triệu) lấn áp hoàn toàn các thuộc tính có miền giá trị nhỏ (như Tuổi: hàng chục, Độ dày: số thập phân) trong phép tính khoảng cách Euclid. Điều này đảm bảo tính đóng góp bình đẳng của mọi đặc trưng trong các thuật toán KNN, K-means hay Gradient Descent."],"questions":[{"id":17,"text":"Hai phương pháp chuẩn hóa dữ liệu Min-Max và Z-score được phát biểu thông qua các công thức toán học nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chuẩn hóa Min-Max biến đổi giá trị x về khoảng theo công thức: (x - min) / (max - min)."},{"k":"B","t":"Chuẩn hóa Z-score chuyển đổi dữ liệu về phân bố có mean=0, std=1 theo công thức: z = (x - mean) / std."},{"k":"C","t":"Chuẩn hóa Min-Max tính bằng cách lấy giá trị x chia trực tiếp cho tổng số mẫu M trong tập học."},{"k":"D","t":"Chuẩn hóa Z-score bắt buộc tất cả các giá trị sau chuẩn hóa phải nằm trong khoảng từ -1 đến 0."}],"answer":["A","B"]},{"id":18,"text":"Lý do kỹ thuật quan trọng nhất bắt buộc phải thực hiện chuẩn hóa thuộc tính (Feature Scaling) trong các thuật toán tính khoảng cách (như KNN, K-means) là gì?","multiple":false,"options":[{"k":"A","t":"Để loại bỏ hoàn toàn các thuộc tính có kiểu dữ liệu là số thực liên tục ra khỏi mô hình."},{"k":"B","t":"Để giảm kích thước lưu trữ của tập dữ liệu trên đĩa cứng xuống mức tối thiểu."},{"k":"C","t":"Để đảm bảo thuật toán cây quyết định không bị rơi vào hiện tượng quá khớp."},{"k":"D","t":"Ngăn chặn các thuộc tính có miền giá trị lớn lấn áp các thuộc tính có miền giá trị nhỏ trong khoảng cách Euclid."}],"answer":["D"]}]},{"id":10,"title":"Rời rạc hóa & Mã hóa Thuộc tính","summary":["Rời rạc hóa thuộc tính (Feature Discretization) tiến hành chuyển đổi các thuộc tính số thực liên tục thành các khoảng giá trị rời rạc hoặc nhãn khái niệm (ví dụ: thuộc tính Tuổi được nhóm thành Thanh niên, Trung niên, Cao tuổi). Kỹ thuật này giúp mô hình giảm bớt sự nhạy cảm với nhiễu nhỏ và tăng tốc độ xử lý ở các thuật toán dạng cây quyết định.","Đối với các thuộc tính định danh rời rạc không có thứ tự, kỹ thuật Mã hóa One-Hot (One-Hot Encoding) chuyển đổi từng giá trị danh mục thành một vectơ nhị phân (chỉ chứa duy nhất một số 1 và các số 0). Phép biến đổi này giúp mô hình số hóa hoàn toàn thông tin định danh mà không làm phát sinh mối quan hệ thứ tự giả tạo giữa các nhãn."],"questions":[{"id":19,"text":"Đặc điểm kỹ thuật của hai phương pháp Rời rạc hóa (Discretization) và Mã hóa One-Hot (One-Hot Encoding) bao gồm những gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Rời rạc hóa chuyển đổi thuộc tính số thực liên tục thành các khoảng giá trị rời rạc hoặc nhãn khái niệm."},{"k":"B","t":"Mã hóa One-Hot chuyển đổi một thuộc tính định danh K giá trị thành vectơ nhị phân K chiều chứa duy nhất một số 1."},{"k":"C","t":"Mã hóa One-Hot nhân tất cả các giá trị định danh với một hằng số ngẫu nhiên để tạo chuỗi số thực."},{"k":"D","t":"Rời rạc hóa bắt buộc làm tăng số lượng mẫu dữ liệu huấn luyện lên gấp K lần."}],"answer":["A","B"]},{"id":20,"text":"Việc tạo ra \"hệ thống khái niệm\" (concept hierarchy generation) trong biến đổi dữ liệu được áp dụng như thế nào?","multiple":false,"options":[{"k":"A","t":"Chuyển đổi các giá trị số thực thành các vectơ phân bố xác suất trong mạng nơ-ron."},{"k":"B","t":"Tổng quát hóa các giá trị dữ liệu mức thấp (như tên đường) lên các khái niệm mức cao hơn (thành phố, quốc gia)."},{"k":"C","t":"Loại bỏ tất cả các từ dừng ra khỏi văn bản trước khi thực hiện phân đoạn từ."},{"k":"D","t":"Ép các thuộc tính khoảng cách phải tuân theo chuẩn định dạng dữ liệu hình ảnh."}],"answer":["B"]}]},{"id":11,"title":"Rút gọn Dữ liệu & Giảm Số chiều","summary":["Rút gọn dữ liệu (Data Reduction) hướng tới việc thu nhỏ kích thước của tập dữ liệu nhưng vẫn duy trì trọn vẹn ngữ nghĩa cốt lõi (core semantics). Quá trình này giúp giảm đáng kể chi phí bộ nhớ và tăng tốc độ huấn luyện mô hình trên các tập dữ liệu lớn.","Các chiến lược rút gọn bao gồm: Lựa chọn thuộc tính (Feature Selection - loại bỏ các thuộc tính dư thừa hoặc không liên quan), Giảm số chiều (Dimensionality Reduction - sử dụng các thuật toán như PCA, ICA để biến đổi không gian sang số chiều nhỏ hơn) và Tổng hợp dữ liệu (Aggregation - tóm tắt dữ liệu mức thấp lên mức khái niệm cao hơn)."],"questions":[{"id":21,"text":"Hai chiến lược rút gọn dữ liệu chính là Lựa chọn thuộc tính (Feature Selection) và Giảm số chiều (Dimensionality Reduction) khác nhau ở điểm nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Feature Selection loại bỏ các thuộc tính dư thừa/không quan trọng và giữ lại một tập con các thuộc tính gốc."},{"k":"B","t":"Dimensionality Reduction (như PCA) biến đổi dữ liệu gốc sang một không gian mới có số chiều nhỏ hơn."},{"k":"C","t":"Feature Selection bắt buộc tạo ra các thuộc tính mới bằng các hàm phi tuyến phức tạp."},{"k":"D","t":"Dimensionality Reduction không làm thay đổi số lượng thuộc tính đầu vào của không gian gốc."}],"answer":["A","B"]},{"id":22,"text":"Ý nghĩa kỹ thuật của việc thực hiện rút gọn dữ liệu (Data Reduction) trước khi huấn luyện mô hình là gì?","multiple":false,"options":[{"k":"A","t":"Làm tăng tối đa dung lượng đĩa cứng cần thiết để lưu trữ kho dữ liệu."},{"k":"B","t":"Rút gọn kích thước dữ liệu nhưng vẫn duy trì trọn vẹn ngữ nghĩa cốt lõi, giúp tăng tốc độ huấn luyện."},{"k":"C","t":"Bắt buộc mô hình học máy phải chuyển từ học có giám sát sang học không giám sát."},{"k":"D","t":"Triệt tiêu hoàn toàn hệ số bias w0 ra khỏi tất cả các phương trình hồi quy tuyến tính."}],"answer":["B"]}]},{"id":12,"title":"Biểu diễn Dữ liệu Văn bản & Mô hình Vectơ Không gian","summary":["Xử lý dữ liệu văn bản thô (Unstructured Text) yêu cầu thiết lập một quy trình tiền xử lý phức tạp để đưa chuỗi ký tự tự nhiên về dạng vectơ đại số số thực. Bước đầu tiên là Phân đoạn từ (Tokenization) để tách văn bản thành danh sách các từ đơn lẻ hoặc từ ghép có nghĩa.","Sau bước phân đoạn, hệ thống tiến hành loại bỏ các Từ dừng (Stopwords - các từ xuất hiện phổ biến nhưng mang ít giá trị nội dung như \"và\", \"nhưng\", \"là\") và xây dựng Từ điển tập hợp tất cả các từ duy nhất. Mỗi văn bản sau đó được biểu diễn bằng một vectơ số thực trong không gian vectơ đa chiều với số chiều đúng bằng kích thước của từ điển."],"questions":[{"id":23,"text":"Trong quy trình tiền xử lý dữ liệu văn bản thô, hai bước Phân đoạn từ (Tokenization) và Lọc từ dừng (Stopwords filtering) có vai trò gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tokenization thực hiện tách chuỗi văn bản thô thành danh sách các từ đơn lẻ hoặc từ ghép có nghĩa."},{"k":"B","t":"Stopwords filtering loại bỏ các từ xuất hiện phổ biến nhưng mang ít giá trị ngữ nghĩa (như \"và\", \"là\", \"nhưng\")."},{"k":"C","t":"Tokenization tự động dịch toàn bộ văn bản từ tiếng Việt sang tiếng Anh trước khi mã hóa."},{"k":"D","t":"Stopwords filtering giữ lại duy nhất các từ nối và xóa bỏ toàn bộ danh từ, động từ trong văn bản."}],"answer":["A","B"]},{"id":24,"text":"Tại sao bước xây dựng \"Từ điển\" (Dictionary) lại là trung gian bắt buộc trong mô hình biểu diễn vectơ không gian cho văn bản?","multiple":false,"options":[{"k":"A","t":"Để lưu trữ lại tất cả các lỗi chính tả xuất hiện trong tập văn bản huấn luyện."},{"k":"B","t":"Để tính toán khoảng cách Euclid trực tiếp giữa hai tập tệp văn bản thô."},{"k":"C","t":"Để xác định chỉ số chiều cố định và ánh xạ từng từ đơn lẻ thành một vị trí tọa độ trong vectơ."},{"k":"D","t":"Để đảm bảo tất cả các văn bản đều có độ dài chuỗi ký tự bằng nhau."}],"answer":["C"]}]},{"id":13,"title":"Kỹ thuật Mã hóa TF-IDF trong NLP","summary":["Kỹ thuật mã hóa TF-IDF (Term Frequency - Inverse Document Frequency) là phương pháp gán trọng số cho từng từ trong văn bản vượt trội hơn hẳn so với việc đếm tần suất đơn thuần. Tần suất từ TF(t, d) đo lường số lần từ t xuất hiện trong văn bản d, thể hiện mức độ quan trọng cục bộ của từ đối với văn bản đó.","Đại lượng nghịch đảo tần suất văn bản IDF(t) được tính bằng logarit của tổng số văn bản chia cho số văn bản có chứa từ t, giúp giảm trọng số của các từ xuất hiện tràn lan ở mọi văn bản và gia tăng trọng số cho các từ đặc trưng hiếm gặp. Tích TF * IDF tạo ra một biểu diễn vectơ thưa có khả năng phản ánh chính xác đặc trưng ngữ nghĩa của văn bản phục vụ cho các bài toán phân loại hay gom cụm tin tức.","B. Bài tập tham khảo"],"questions":[{"id":25,"text":"Công thức gán trọng số TF-IDF cho một từ t trong văn bản d thuộc tập văn bản D được phát biểu ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"TF(t, d) đo lường tần suất xuất hiện của từ t trong văn bản d."},{"k":"B","t":"IDF(t) đo lường độ hiếm của từ t trên toàn bộ tập văn bản D thông qua hàm logarit."},{"k":"C","t":"Trọng số TF-IDF được tính bằng tổng của hai đại lượng: TF(t, d) + IDF(t)."},{"k":"D","t":"Tích TF * IDF gán trọng số cao cho các từ xuất hiện thường xuyên trong d nhưng hiếm gặp trong toàn bộ D."}],"answer":["A","B"]},{"id":26,"text":"Điểm vượt trội của kỹ thuật mã hóa TF-IDF so với phương pháp đếm tần suất từ đơn thuần (Bag-of-Words) là gì?","multiple":false,"options":[{"k":"A","t":"Giảm trọng số của các từ xuất hiện phổ biến ở mọi văn bản và gia tăng trọng số cho các từ mang đặc trưng cao."},{"k":"B","t":"Làm cho vectơ đại diện của văn bản luôn có độ dài cố định đúng bằng 10 phần tử."},{"k":"C","t":"Tự động sửa chữa các lỗi ngữ pháp và cú pháp xuất hiện trong văn bản thô."},{"k":"D","t":"Loại bỏ hoàn toàn sự phụ thuộc vào ma trận từ điển trong quá trình số hóa văn bản."}],"answer":["A"]}]}]},{"id":"l3-linear-regression","title":"L3 linear regression","summary":["Mô hình Hồi quy Tuyến tính (Linear Regression) là phương pháp nền tảng trong học máy có giám sát nhằm giải quyết bài toán dự báo giá trị đầu ra số thực liên tục y từ các thuộc tính đầu vào x. Dưới góc nhìn toán học, mô hình đặt ra giả thuyết rằng hàm mục tiêu ẩn y* có thể được xấp xỉ hiệu quả bởi một siêu phẳng f(x; w) = w0 + w1*x1 + ... + wn*xn = w^T * x, trong đó w là vectơ trọng số cần học và w0 là thành phần bias. Để đánh giá chất lượng của hàm dự báo, mô hình sử dụng hàm mất mát bình phương (Square Loss) và tổng phần dư bình phương RSS(f) = Σ (yi - f(xi; w))^2 trên tập huấn luyện D gồm M mẫu. Mục tiêu tối ưu là tìm bộ trọng số w* sao cho sai số thực nghiệm được tối thiểu hóa, tạo cơ sở cho việc suy diễn và dự báo trên các quan sát dữ liệu mới trong tương lai.","Thuật toán huấn luyện OLS (Ordinary Least Squares - Bình phương Tối thiểu) thực hiện tối ưu hóa hàm RSS bằng cách lấy đạo hàm theo vectơ trọng số w và cho bằng 0, thu được công thức nghiệm dạng đóng (Normal Equation) w* = (A^T * A)^(-1) * A^T * y với A là ma trận dữ liệu cỡ M x (n+1). Mặc dù OLS mang lại giải pháp đại số trực tiếp và không tốn chi phí lặp, phương pháp này gặp rào cản kỹ thuật nghiêm trọng khi ma trận A^T * A bị suy biến (det = 0) do hiện tượng đa cộng tuyến giữa các thuộc tính, hoặc khi số chiều n quá lớn khiến phép tính nghịch đảo ma trận tốn kém chi phí tính toán O(n^3). Bên cạnh đó, việc OLS tập trung hoàn toàn vào tối đa độ chính xác trên tập học khiến mô hình dễ bị quá khớp (overfitting) và kém khả năng tổng quát hóa trên tập dữ liệu thực tế.","Để khắc phục hạn chế của OLS, kỹ thuật Hiệu chỉnh (Regularization) được áp dụng bằng cách bổ sung đại lượng phạt g(w) vào hàm mục tiêu với hệ số Cán cân λ > 0: min [RSS(f) + λ * g(w)]. Theo phân tích phân rã Bias-Variance trade-off, đại lượng phạt giúp thu hẹp không gian tìm kiếm trọng số, kiểm soát độ phức tạp của mô hình để cân bằng giữa độ lệch Bias và phương sai Variance. Hồi quy Ridge sử dụng chuẩn L2 g(w) = ||w||2^2 giúp ma trận (A^T * A + λ * I) luôn khả nghịch và thu nhỏ độ lớn trọng số; trong khi Hồi quy LASSO sử dụng chuẩn L1 g(w) = ||w||1 giúp tạo ra nghiệm thưa (sparsity) bằng cách triệt tiêu các trọng số không quan trọng về đúng 0. Sự kết hợp giữa tối thiểu hóa sai số và hiệu chỉnh trọng số chính là bản chất kỹ thuật giúp các mô hình hồi quy tuyến tính đạt được hiệu năng tổng quát hóa tối ưu."],"topics":[{"id":1,"title":"Bài toán Hồi quy Tuyến tính","summary":["Bài toán hồi quy (Regression Problem) là một nhánh cốt lõi của học máy có giám sát, nơi mô hình cần học một hàm ánh xạ f từ không gian thuộc tính n chiều vào miền số thực liên tục Y. Khác với bài toán phân loại có nhãn đầu ra rời rạc, hồi quy hướng tới việc dự báo các chỉ số định lượng như giá nhà, doanh thu hay nhiệt độ từ tập dữ liệu huấn luyện D = {(x1, y1), ..., (xM, yM)}. Mỗi mẫu dữ liệu xi được biểu diễn bởi vectơ n thuộc tính xi = (xi1, xi2, ..., xin)^T.","Về mặt giả thuyết, Hồi quy Tuyến tính giả định hàm chưa biết y* có thể được xấp xỉ tốt bởi một biểu thức tuyến tính f(x; w) = w0 + w1*x1 + ... + wn*xn. Trong đó, w = (w0, w1, ..., wn)^T là vectơ trọng số tham số hóa không gian các siêu phẳng, với w0 đại diện cho hệ số tự do (bias). Việc học mô hình tuyến tính về bản chất chính là quá trình tìm kiếm vectơ trọng số w* tối ưu trong không gian Rn+1 để mô hình hóa mối quan hệ giữa các biến đầu vào và đầu ra."],"questions":[{"id":1,"text":"Trong bài toán Hồi quy Tuyến tính (Linear Regression), dạng biểu thức của giả thuyết mô hình f(x; w) và bản chất của các tham số được phát biểu như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Mô hình giả định hàm đầu ra được biểu diễn dạng f(x; w) = w0 + w1*x1 + ... + wn*xn = w^T * x."},{"k":"B","t":"Giá trị đầu ra y của bài toán hồi quy bắt buộc phải nhận các giá trị nhãn rời rạc thuộc tập {-1, +1}."},{"k":"C","t":"Vectơ trọng số w = (w0, w1, ..., wn)^T xác định duy nhất một siêu phẳng trong không gian thuộc tính."},{"k":"D","t":"Hệ số bias w0 đại diện cho độ dốc của đường ranh giới phân tách và bắt buộc phải có giá trị dương."}],"answer":["A","C"]},{"id":2,"text":"Thành phần bias w0 trong phương trình hồi quy tuyến tính f(x; w) = w0 + w1*x1 + ... + wn*xn đóng vai trò kỹ thuật gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Cho phép siêu phẳng dịch chuyển tự do trong không gian mà không bị gò ép bắt buộc đi qua gốc tọa độ."},{"k":"B","t":"Mở rộng họ hàm tuyến tính giúp mô hình khớp dữ liệu tốt hơn so với họ hàm thuần túy đi qua gốc tọa độ."},{"k":"C","t":"Tự động triệt tiêu tất cả các thuộc tính xi có giá trị âm về đúng bằng 0 trong quá trình học."},{"k":"D","t":"Đảm bảo ma trận dữ liệu A luôn khả nghịch trong mọi điều kiện phân bố của tập huấn luyện."}],"answer":["A","B"]}]},{"id":2,"title":"Hàm Mất mát & Lỗi Thực nghiệm","summary":["Để đo lường chất lượng dự báo của mô hình trên từng mẫu dữ liệu, các hàm mất mát (Loss function) được sử dụng để định lượng mức độ chênh lệch giữa giá trị thực tế y và giá trị dự báo f(x). Trong hồi quy, hàm mất mát phổ biến nhất là Lỗi bình phương (Square Loss) r(f, x) = (y - f(x))^2. Ngoài ra, các dạng mất mát khác như Lỗi tuyệt đối L1, Hinge Loss hay Cross-entropy Loss cũng được ứng dụng tùy theo đặc thụ bài toán.","Mục tiêu lý tưởng của học máy là tối thiểu hóa Lỗi trung bình kỳ vọng E[r(f, x)] trên toàn bộ không gian phân bố dữ liệu. Tuy nhiên, do chỉ tiếp cận được tập dữ liệu huấn luyện hữu hạn D, thuật toán học phải sử dụng Lỗi thực nghiệm L(f, D) = (1/M) * RSS(f) để xấp xỉ lỗi kỳ vọng, trong đó RSS(f) = Σ (yi - f(xi; w))^2 là tổng phần dư bình phương. Khoảng chênh lệch giữa lỗi thực nghiệm và lỗi kỳ vọng chính là Lỗi tổng quát hóa (Generalization Error), phản ánh khả năng dự báo chính xác của mô hình trên dữ liệu mới."],"questions":[{"id":3,"text":"Việc đánh giá chất lượng của hàm hồi quy dựa trên các độ đo mất mát (Loss function) được thực hiện như thế nào trong lý thuyết học máy? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hàm mất mát Lỗi bình phương (Square Loss) được tính bằng công thức r(f, x) = (y - f(x))^2."},{"k":"B","t":"Lỗi thực nghiệm L(f, D) = (1/M) * RSS(f) là đại lượng xấp xỉ có thể tính toán được của Lỗi kỳ vọng E[r(f, x)]."},{"k":"C","t":"Lỗi tổng quát hóa đo lường mức độ chênh lệch giữa các giá trị thuộc tính đầu vào xi và biến đầu ra yi."},{"k":"D","t":"Mục tiêu tối thượng của bài toán học là tối đa hóa giá trị Lỗi kỳ vọng E[r(f, x)] trên toàn bộ không gian mẫu."}],"answer":["A","B"]},{"id":4,"text":"Tổng phần dư bình phương (Residual Sum of Squares - RSS) trên tập huấn luyện D = {(xi, yi)} với M mẫu được định nghĩa bằng công thức toán học nào?","multiple":false,"options":[{"k":"A","t":"RSS(f) = Σ |yi - f(xi; w)| với i chạy từ 1 đến M"},{"k":"B","t":"RSS(f) = max{0, 1 - yi * f(xi; w)} với i chạy từ 1 đến M"},{"k":"C","t":"RSS(f) = Σ (yi - w0 - w1*xi1 - ... - wn*xin)^2 với i chạy từ 1 đến M"},{"k":"D","t":"RSS(f) = Σ (yi * log(f(xi; w))) với i chạy từ 1 đến M"}],"answer":["C"]}]},{"id":3,"title":"Phương pháp Bình phương Tối thiểu (OLS)","summary":["Phương pháp Bình phương Tối thiểu (Ordinary Least Squares - OLS) là giải thuật học kinh điển cho hồi quy tuyến tính, hoạt động dựa trên nguyên lý tìm vectơ trọng số w* sao cho tổng phần dư bình phương RSS(f) trên tập huấn luyện đạt giá trị nhỏ nhất. Do hàm mục tiêu RSS(f) là một hàm bậc hai lồi theo w, điểm cực tiểu toàn cục thu được tại vị trí vectơ độ dốc Gradient bằng 0: ∂RSS/∂w = 0.","Giải hệ phương trình đạo hàm bằng 0 dẫn đến phương trình chuẩn (Normal Equation) có công thức nghiệm dạng đóng: w* = (A^T * A)^(-1) * A^T * y. Trong đó, A là ma trận dữ liệu cỡ M x (n+1) chứa hàng đầu tiên bằng 1 cho thành phần bias, và y là vectơ cột chứa M giá trị đầu ra thực tế. Phương pháp OLS cho phép tính toán trực tiếp bộ trọng số tối ưu chỉ qua các phép toán đại số tuyến tính mà không cần chạy các vòng lặp xấp xỉ."],"questions":[{"id":5,"text":"Thuật toán Bình phương Tối thiểu (Ordinary Least Squares - OLS) tìm kiếm bộ trọng số tối ưu w* dựa trên nguyên lý giải tích nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bài toán đưa về việc tìm w* để tối thiểu hóa hàm tổng phần dư bình phương RSS(f) trên tập học D."},{"k":"B","t":"Vectơ trọng số w* được xác định bằng cách giải phương trình vectơ độ dốc ∂RSS/∂w = 0."},{"k":"C","t":"Công thức nghiệm dạng đóng của OLS có dạng w* = (A^T * A)^(-1) * A^T * y với ma trận dữ liệu A."},{"k":"D","t":"OLS bắt buộc phải áp dụng các vòng lặp Gradient Descent nhiều bước để hội tụ về nghiệm tối ưu."}],"answer":["A","B"]},{"id":6,"text":"Xét công thức nghiệm dạng đóng w* = (A^T * A)^(-1) * A^T * y của phương pháp OLS, cấu trúc của ma trận dữ liệu A cỡ M x (n+1) được quy định như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hàng thứ i của ma trận A có dạng Ai = (xi1, xi2, ..., xin) và hoàn toàn bỏ qua thành phần bias."},{"k":"B","t":"Vectơ cột y có kích thước M x 1 chứa các giá trị đầu ra thực tế của M mẫu dữ liệu trong tập học."},{"k":"C","t":"Hàng thứ i của ma trận A được bổ sung phần tử 1 ở đầu: Ai = (1, xi1, xi2, ..., xin)."},{"k":"D","t":"Ma trận A bắt buộc phải là một ma trận vuông kích thước (n+1) x (n+1) để tính được ma trận chuyển vị A^T."}],"answer":["B","C"]}]},{"id":4,"title":"Hạn chế của OLS & Vấn đề Đa cộng tuyến","summary":["Mặc dù OLS có cấu trúc toán học tường minh, phương pháp này đối mặt với rào cản kỹ thuật lớn khi ma trận A^T * A không khả nghịch (suy biến, det = 0). Tình trạng này thường xảy ra khi tập dữ liệu xuất hiện hiện tượng Đa cộng tuyến (Multicollinearity) – tức là tồn tại sự phụ thuộc tuyến tính giữa hai hoặc nhiều cột thuộc tính trong ma trận A, hoặc khi số lượng thuộc tính n vượt quá số lượng mẫu huấn luyện M.","Bên cạnh vấn đề suy biến ma trận, OLS đòi hỏi chi phí tính toán phép nghịch đảo ma trận rất lớn cỡ O(n^3), khiến mô hình bị tắc nghẽn khi xử lý dữ liệu số chiều cao. Quan trọng hơn, OLS tập trung tối đa vào việc ép dòng lỗi thực nghiệm trên tập học về 0 mà không có cơ chế kiểm soát độ lớn trọng số, dẫn đến hiện tượng mô hình nhạy cảm cực độ với nhiễu và dễ rơi vào trạng thái quá khớp."],"questions":[{"id":7,"text":"Phương pháp OLS không thể tìm được nghiệm công thức đóng w* = (A^T * A)^(-1) * A^T * y trong những tình huống kỹ thuật nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Ma trận tích A^T * A rơi vào trạng thái suy biến (singular matrix) với định thức det(A^T * A) = 0."},{"k":"B","t":"Số lượng mẫu huấn luyện M lớn hơn rất nhiều so với số lượng thuộc tính đặc trưng n."},{"k":"C","t":"Tồn tại sự phụ thuộc tuyến tính (Đa cộng tuyến) giữa các cột thuộc tính trong ma trận dữ liệu A."},{"k":"D","t":"Giá trị đầu ra y trong tập huấn luyện nhận các giá trị số thực âm."}],"answer":["A","C"]},{"id":8,"text":"Nhược điểm về chi phí tính toán và khả năng tổng quát hóa của thuật toán OLS được thể hiện ở điểm nào?","multiple":false,"options":[{"k":"A","t":"Phép tính nghịch đảo ma trận (A^T * A)^(-1) tốn chi phí O(n^3), trở nên bất khả thi khi số chiều n rất lớn và dễ quá khớp."},{"k":"B","t":"OLS luôn luôn bị hiện tượng kém khớp do hàm mục tiêu RSS quá đơn giản không khớp được dữ liệu huấn luyện."},{"k":"C","t":"OLS làm cho tất cả các hệ số trọng số w bị triệt tiêu hoàn toàn về 0 khi tập dữ liệu có nhiễu."},{"k":"D","t":"OLS yêu cầu phải lưu trữ lại toàn bộ bộ nhớ cache của các bước lặp gradient trong quá trình dự báo."}],"answer":["A"]}]},{"id":5,"title":"Quá khớp & Kém khớp trong Hồi quy","summary":["Trong quá trình huấn luyện mô hình hồi quy, hai hiện tượng bất lợi thường gặp là Quá khớp (Overfitting) và Kém khớp (Underfitting). Kém khớp xảy ra khi mô hình quá đơn giản (như dùng đường thẳng cho dữ liệu có cấu trúc cong phức tạp), dẫn đến việc mô hình mắc sai số lớn ngay trên cả tập huấn luyện lẫn tập kiểm thử.","Ngược lại, Quá khớp diễn ra khi mô hình tuyến tính học quá mức cả các điểm nhiễu ngẫu nhiên trong tập D, tạo ra vectơ trọng số w có giá trị rất lớn. Khi đó, mô hình đạt độ chính xác hoàn hảo trên tập học nhưng sai số dự báo lại bùng nổ khi gặp các mẫu dữ liệu mới ngoài tập D. Việc nhận diện và cân bằng giữa quá khớp và kém khớp là điều kiện tiên quyết để xây dựng hệ thống hồi quy thực tế."],"questions":[{"id":9,"text":"Nhận định nào sau đây phản ánh đúng bản chất của hai hiện tượng Quá khớp (Overfitting) và Kém khớp (Underfitting) trong mô hình hồi quy? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Kém khớp xảy ra khi mô hình tuyến tính quá đơn giản so với hàm thực tế y*, dẫn đến sai số lớn trên tập học."},{"k":"B","t":"Quá khớp xảy ra khi mô hình đạt độ chính xác cao trên tập học D nhưng phán đoán kém trên dữ liệu kiểm thử."},{"k":"C","t":"Quá khớp làm cho tất cả các hệ số trọng số w của mô hình thu nhỏ về sát giá trị bằng 0."},{"k":"D","t":"Kém khớp chỉ xuất hiện khi ma trận dữ liệu A bị suy biến và không tính được phép nghịch đảo."}],"answer":["A","B"]},{"id":10,"text":"Lỗi tổng quát hóa (Generalization Error) của mô hình hồi quy f được định nghĩa là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Là khoảng sai khác giữa Lỗi trung bình kỳ vọng E[r(f, x)] và Lỗi thực nghiệm L(f, D)."},{"k":"B","t":"Là độ đo phản ánh khả năng dự báo chính xác của mô hình trên các mẫu dữ liệu tương lai ngoài tập học."},{"k":"C","t":"Mô hình có khả năng tổng quát hóa càng cao thì độ chênh lệch |E[r(f, x)] - L(f, D)| càng nhỏ."},{"k":"D","t":"Là tổng khoảng cách Euclid giữa ma trận dữ liệu A và ma trận nghịch đảo (A^T * A)^(-1)."}],"answer":["A","B"]}]},{"id":6,"title":"Phân tích Phân rã Bias-Variance","summary":["Phân tích phân rã Bias-Variance là khung lý thuyết toán học giúp mổ xẻ tổng sai số dự báo của một mô hình học máy thành ba thành phần độc lập: Total Error = Bias^2 + Variance + Noise (σ^2). Trong đó, Noise σ^2 là nhiễu nội tại không thể triệt tiêu của dữ liệu; Bias đo lường độ lệch giữa phán đoán trung bình của mô hình và đáp án thực tế; còn Variance đo lường mức độ dao động của phán đoán khi huấn luyện trên các tập dữ liệu khác nhau.","Mối quan hệ đánh đổi Bias-Variance trade-off chỉ ra rằng các mô hình đơn giản thường có Bias cao nhưng Variance thấp (dễ kém khớp), trong khi các mô hình phức tạp lại có Bias thấp nhưng Variance rất cao (dễ quá khớp). Mục tiêu tối ưu của một thuật toán học là phải đồng thời giữ cho cả Bias và Variance ở mức nhỏ thích hợp, tạo ra đường cong sai số tổng thể đạt giá trị cực tiểu trên tập dữ liệu kiểm chứng."],"questions":[{"id":11,"text":"Trong phân tích phân rã sai số Bias-Variance Trade-off (Total Error = Bias^2 + Variance + σ^2), ý nghĩa của các thành phần được phát biểu như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bias đại diện cho độ lệch giữa phán đoán trung bình của mô hình và đáp án chuẩn y*."},{"k":"B","t":"Variance đại diện cho sự biến động của phán đoán mô hình khi huấn luyện trên các tập dữ liệu D khác nhau."},{"k":"C","t":"Đại lượng σ^2 đại diện cho nhiễu nội tại của dữ liệu và có thể triệt tiêu hoàn toàn nếu tăng số mẫu M."},{"k":"D","t":"Mô hình có độ phức tạp cao thường có Bias rất lớn và Variance tiệm cận về 0."}],"answer":["A","B"]},{"id":12,"text":"Mối quan hệ đánh đổi Bias-Variance Trade-off gợi ý chiến lược gì để tối ưu hóa mô hình hồi quy?","multiple":false,"options":[{"k":"A","t":"Cần loại bỏ hoàn bộ các thuộc tính đầu vào để kéo sai số Variance về bằng 0."},{"k":"B","t":"Bắt buộc phải tăng tối đa độ phức tạp của mô hình để giảm sai số Bias về bằng 0."},{"k":"C","t":"Tìm điểm cân bằng phù hợp sao cho cả Bias và Variance đều duy trì ở mức nhỏ thích hợp."},{"k":"D","t":"Thay thế hàm mất mát Lỗi bình phương bằng hàm mất mát Cross-entropy trong mọi bài toán hồi quy."}],"answer":["C"]}]},{"id":7,"title":"Nguyên lý Hiệu chỉnh (Regularization)","summary":["Hiệu chỉnh (Regularization) là kỹ thuật quan trọng trong học máy nhằm giải quyết hiện tượng quá khớp bằng cách đưa thêm một thành phần phạt độ phức tạp g(w) vào hàm mục tiêu: Lreg(w) = L(f, D) + λ * g(w). Hệ số phạt λ ≥ 0 đóng vai trò điều khiển mức độ đánh đổi giữa việc khớp dữ liệu huấn luyện và việc giữ cho mô hình đơn giản theo nguyên lý Con dao cạo Occam (Occam's razor).","Về bản chất hình học, đại lượng phạt λ * g(w) thu hẹp không gian tìm kiếm trọng số từ không gian W ban đầu về một vùng không gian con W' nhỏ hơn (w thuộc W' sao cho g(w) ≤ t). Khi λ tăng lên, vùng tìm kiếm W' bị co hẹp lại, làm giảm sự tự do của các trọng số và dập tắt ảnh hưởng của các thuộc tính nhiễu. Dưới góc nhìn xác suất, hiệu chỉnh tương đương với việc áp dụng ước lượng cực đại hậu nghiệm MAP (Maximum A Posteriori) với phân bố tiên nghiệm xác định cho bộ trọng số."],"questions":[{"id":13,"text":"Nguyên lý chung của kỹ thuật Hiệu chỉnh (Regularization) trong việc ngăn ngừa hiện tượng quá khớp là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bổ sung một thành phần phạt độ phức tạp g(w) vào hàm mục tiêu: Lreg = L(f, D) + λ * g(w)."},{"k":"B","t":"Hệ số phạt λ > 0 giúp cân bằng giữa độ chính xác trên tập học và khả năng tổng quát hóa."},{"k":"C","t":"Kỹ thuật hiệu chỉnh làm tăng số chiều của không gian tham số W lên gấp hai lần."},{"k":"D","t":"Việc ép đại lượng g(w) nhỏ tương đương với việc thu hẹp không gian tìm kiếm trọng số W về vùng con W'."}],"answer":["A","B"]},{"id":14,"text":"Dưới góc nhìn toán học, việc áp dụng đại lượng phạt g(w) với hệ số λ trong hiệu chỉnh tuân theo nguyên lý nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Thu hẹp vùng tìm kiếm trọng số giúp giảm bớt nguy cơ quá khớp theo nguyên lý Con dao cạo Occam."},{"k":"B","t":"Hệ số λ càng lớn thì mức phạt càng mạnh và mô hình học được có xu hướng càng đơn giản."},{"k":"C","t":"Chọn λ quá nhỏ sẽ khiến mô hình phạt quá nặng và dễ gây ra hiện tượng kém khớp."},{"k":"D","t":"Kỹ thuật hiệu chỉnh loại bỏ hoàn toàn thành phần nhiễu σ^2 ra khỏi bài toán phân rã Bias-Variance."}],"answer":["A","B"]}]},{"id":8,"title":"Hồi quy Ridge & Chuẩn L2","summary":["Hồi quy Ridge (Ridge Regression) là phương pháp hiệu chỉnh tuyến tính sử dụng chuẩn L2 của vectơ trọng số làm thành phần phạt độ phức tạp: min [RSS(f) + λ * ||w||2^2], trong đó ||w||2^2 = w0^2 + w1^2 + ... + wn^2. Bài toán tối ưu hóa này tương đương với việc tối thiểu hóa RSS(f) dưới ràng buộc giới hạn tổng bình phương trọng số Σ wj^2 ≤ t.","Tác động của thành phần phạt chuẩn L2 là thu nhỏ (shrinkage) liên tục độ lớn của tất cả các hệ số trọng số w về sát giá trị 0 khi λ tăng lên, nhưng không làm trọng số nào bị triệt tiêu hoàn toàn bằng 0. Bằng cách ép các trọng số duy trì ở giá trị nhỏ, Hồi quy Ridge dập tắt sự dao động cực đoan của mô hình, làm giảm mạnh phương sai Variance và cải thiện khả năng tổng quát hóa trên tập dữ liệu mới."],"questions":[{"id":15,"text":"Hồi quy Ridge (Ridge Regression) xây dựng bài toán tối ưu hóa dựa trên hàm mục tiêu và ràng buộc chuẩn nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bài toán Ridge tối thiểu hóa hàm mục tiêu RSS(f) + λ * ||w||2^2 sử dụng chuẩn L2 của trọng số."},{"k":"B","t":"Hồi quy Ridge loại bỏ hoàn toàn thành phần RSS(f) và chỉ tập trung tối tiểu hóa ||w||2^2."},{"k":"C","t":"Bài toán tương đương với tối thiểu hóa RSS(f) dưới ràng buộc bất đẳng thức Σ wj^2 ≤ t."},{"k":"D","t":"Hồi quy Ridge bắt buộc tất cả các hệ số trọng số wj phải nhận giá trị số thực lớn hơn 1."}],"answer":["A","C"]},{"id":16,"text":"Tác động kỹ thuật chính của thành phần phạt chuẩn L2 (λ * ||w||2^2) lên các hệ số trọng số trong Hồi quy Ridge là gì?","multiple":false,"options":[{"k":"A","t":"Kéo trực tiếp một số hệ số trọng số wj về đúng bằng 0 để làm thưa mô hình."},{"k":"B","t":"Thu nhỏ liên tục độ lớn của các hệ số trọng số wj về gần 0 nhưng không bằng 0."},{"k":"C","t":"Tự động nhân đôi giá trị của các hệ số trọng số tương ứng với thuộc tính nhiễu."},{"k":"D","t":"Đảm bảo cho hàm mục tiêu Ridge trở thành hàm không lồi có nhiều điểm cực tiểu cục bộ."}],"answer":["B"]}]},{"id":9,"title":"Giải pháp Khả nghịch của Hồi quy Ridge","summary":["Một ưu điểm kỹ thuật đột phá của Hồi quy Ridge là khả năng giải quyết triệt để sự cố suy biến ma trận của OLS. Bằng cách tính đạo hàm của hàm mục tiêu Ridge và cho bằng 0, ta thu được công thức nghiệm dạng đóng: w* = (A^T * A + λ * I_(n+1))^(-1) * A^T * y, trong đó I_(n+1) là ma trận đơn vị cỡ (n+1) x (n+1).","Do λ > 0 và ma trận I_(n+1) là ma trận đường chéo dương, ma trận (A^T * A + λ * I) luôn luôn xác định dương và chắc chắn khả nghịch (det > 0), ngay cả khi các thuộc tính trong A bị đa cộng tuyến hoàn toàn. Trong triển khai thực tế, thành phần bias w0 thường được tách khỏi đại lượng phạt L2 để tránh làm hệ số hồi quy bị ảnh hưởng bởi sự thay đổi quy mô miền giá trị của biến đầu ra y."],"questions":[{"id":17,"text":"Công thức nghiệm dạng đóng của Hồi quy Ridge w* = (A^T * A + λ * I_(n+1))^(-1) * A^T * y mang lại lợi thế vượt trội nào so với OLS? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Do λ > 0 và ma trận đơn vị I dương, ma trận (A^T * A + λ * I) luôn khả nghịch trong mọi trường hợp."},{"k":"B","t":"Công thức Ridge giúp triệt tiêu hoàn toàn chi phí tính toán nghịch đảo ma trận về O(1)."},{"k":"C","t":"Ridge giải quyết triệt để sự cố suy biến ma trận do hiện tượng đa cộng tuyến gây ra cho OLS."},{"k":"D","t":"Công thức Ridge tự động loại bỏ thành phần bias w0 ra khỏi biểu thức phán đoán cho mẫu mới."}],"answer":["A","C"]},{"id":18,"text":"Tại sao trong triển khai thực tế của Hồi quy Ridge, người ta thường loại bỏ trọng số bias w0 ra khỏi thành phần phạt chuẩn L2?","multiple":false,"options":[{"k":"A","t":"Để tránh việc độ lớn quy mô của biến đầu ra y gây ảnh hưởng tiêu cực lên các thuộc tính đầu vào x."},{"k":"B","t":"Vì trọng số bias w0 luôn luôn bằng 0 trong mọi mô hình hồi quy tuyến tính."},{"k":"C","t":"Để đảm bảo ma trận (A^T * A + λ * I) duy trì tính chất đối xứng qua đường chéo chính."},{"k":"D","t":"Vì chuẩn L2 không tính toán được giá trị bình phương cho các số thực có dấu âm."}],"answer":["A"]}]},{"id":10,"title":"Hồi quy LASSO & Chuẩn L1","summary":["Hồi quy LASSO (Least Absolute Shrinkage and Selection Operator) thay thế chuẩn L2 bằng chuẩn L1 của vectơ trọng số làm thành phần hiệu chỉnh: min [RSS(f) + λ * ||w||1], trong đó ||w||1 = |w0| + |w1| + ... + |wn|. Bài toán tương đương với việc tối thiểu hóa RSS(f) dưới ràng buộc hình học tổng giá trị tuyệt đối Σ |wj| ≤ t.","Về mặt giải thuật, do hàm mục tiêu chứa chuẩn L1 chứa các điểm gập góc không khả vi tại vị trí 0, Hồi quy LASSO không có nghiệm công thức đóng dạng ma trận như OLS hay Ridge. Việc tìm nghiệm tối ưu của LASSO đòi hỏi các thuật toán tối ưu hóa lồi phức tạp hơn như Tối ưu Gradient tọa độ (Coordinate Descent) hoặc thuật toán LARS (Least Angle Regression)."],"questions":[{"id":19,"text":"Hồi quy LASSO (Least Absolute Shrinkage and Selection Operator) định nghĩa bài toán tối ưu hóa bằng cách nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tối thiểu hóa hàm mục tiêu RSS(f) + λ * ||w||1 sử dụng chuẩn L1 của vectơ trọng số w."},{"k":"B","t":"Tương đương với bài toán tối thiểu hóa RSS(f) dưới ràng buộc bất đẳng thức Σ |wj| ≤ t."},{"k":"C","t":"LASSO sử dụng hàm mất mát Hinge Loss thay thế hoàn toàn cho tổng phần dư bình phương RSS."},{"k":"D","t":"Công thức nghiệm của LASSO có dạng đóng ma trận w* = (A^T * A - λ * I)^(-1) * A^T * y."}],"answer":["A","B"]},{"id":20,"text":"Tại sao thuật toán huấn luyện Hồi quy LASSO lại phức tạp hơn so với Hồi quy Ridge và không có công thức nghiệm ma trận dạng đóng?","multiple":false,"options":[{"k":"A","t":"Do thành phần phạt chuẩn L1 (||w||1 = Σ |wj|) chứa các điểm gập góc không khả vi tại giá trị 0."},{"k":"B","t":"Do hàm mục tiêu LASSO là hàm phi tuyến bậc cao có nhiều điểm yên ngựa không hội tụ."},{"k":"C","t":"Do LASSO bắt buộc phải tính toán qua không gian đặc trưng phi tuyến chiều vô hạn."},{"k":"D","t":"Do ma trận dữ liệu A trong LASSO bị biến đổi thành ma trận thưa không thể nhân ma trận."}],"answer":["A"]}]},{"id":11,"title":"Bản chất Nghiệm thưa & Chọn lọc Thuộc tính","summary":["Điểm vượt trội và độc đáo nhất của Hồi quy LASSO là khả năng tạo ra Nghiệm thưa (Sparse Solution) – tức là kéo trực tiếp nhiều thành phần trọng số wj về đúng bằng 0 khi λ đủ lớn. Hình học của vùng ràng buộc chuẩn L1 có dạng hình thoi (diamond) với các đỉnh nhọn nằm ngay trên các trục tọa độ. Khi các đường đồng mức elip của hàm RSS tiếp xúc với vùng ràng buộc, điểm tiếp xúc thường rơi đúng vào các đỉnh nhọn, làm cho trọng số tương ứng bị triệt tiêu về 0.","Nhờ tính chất nghiệm thưa, LASSO thực hiện đồng thời hai nhiệm vụ: thu nhỏ trọng số (shrinkage) và lựa chọn thuộc tính tự động (feature selection). Mô hình tự động loại bỏ các thuộc tính dư thừa hoặc không quan trọng ra khỏi phương trình hồi quy, giúp tạo ra một mô hình đơn giản, dễ giải thích ý nghĩa vật lý và nâng cao hiệu năng dự báo trên các tập dữ liệu số chiều cao."],"questions":[{"id":21,"text":"Đặc tính \"Nhiệm thưa\" (Sparse Solution) của Hồi quy LASSO mang lại ý nghĩa kỹ thuật quan trọng nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Kéo trực tiếp nhiều thành phần trọng số wj về đúng bằng 0 khi hệ số phạt λ đủ lớn."},{"k":"B","t":"Thực hiện đồng thời việc thu nhỏ trọng số (shrinkage) và lựa chọn thuộc tính (feature selection)."},{"k":"C","t":"Bắt buộc tất cả các mẫu dữ liệu huấn luyện phải nằm đúng trên đường siêu phẳng lề."},{"k":"D","t":"Làm tăng số lượng thuộc tính đầu vào trong phương trình hồi quy lên gấp hai lần."}],"answer":["A","B"]},{"id":22,"text":"Dưới góc nhìn hình học, tại sao chuẩn L1 trong LASSO lại tạo ra nghiệm thưa trong khi chuẩn L2 trong Ridge thì không?","multiple":false,"options":[{"k":"A","t":"Miền ràng buộc L1 có dạng hình tròn trơn, còn miền ràng buộc L2 có các đỉnh nhọn nằm trên trục tọa độ."},{"k":"B","t":"Miền ràng buộc L1 có dạng hình thoi với các đỉnh nhọn nằm trên trục tọa độ, dễ tiếp xúc với đường RSS tại điểm có wj = 0."},{"k":"C","t":"Các đường đồng mức của hàm RSS trong chuẩn L1 luôn luôn là các đường thẳng song song với trục tọa độ."},{"k":"D","t":"Chuẩn L2 gò ép các elip RSS phải cắt miền ràng buộc tại duy nhất một điểm có tất cả các trọng số bằng 0."}],"answer":["B"]}]},{"id":12,"title":"So sánh OLS, Ridge và LASSO","summary":["Khi so sánh trên cùng một tập dữ liệu thực tế (như tập dữ liệu ung thư tiền liệt tuyến 67 mẫu huấn luyện và 30 mẫu kiểm thử), cả ba phương pháp OLS, Ridge và LASSO đều đưa ra các bộ trọng số khác nhau. OLS sử dụng toàn bộ các thuộc tính và dễ bị ảnh hưởng bởi nhiễu, dẫn đến lỗi trên tập kiểm thử (Test RSS) thường cao nhất trong ba phương pháp.","Hồi quy Ridge thu nhỏ các trọng số giúp giảm Test RSS xuống mức thấp hơn OLS, nhưng vẫn giữ lại đầy đủ tất cả các thuộc tính trong mô hình. Trong khi đó, LASSO đạt được sai số kiểm thử Test RSS nhỏ nhất đồng thời triệt tiêu nhiều trọng số về 0, chỉ giữ lại các thuộc tính quan trọng nhất (như lcavol, lweight, svi). Kết quả thực nghiệm khẳng định lợi thế của các phương pháp hiệu chỉnh trong việc nâng cao độ chính xác và tính đơn giản của mô hình."],"questions":[{"id":23,"text":"Khi thực nghiệm so sánh OLS, Ridge và LASSO trên cùng một tập dữ liệu (như tập dữ liệu ung thư tiền liệt tuyến 67 mẫu huấn luyện, 30 mẫu kiểm thử), kết quả cho thấy điều gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"OLS cho sai số trên tập kiểm thử (Test RSS) cao nhất do tập trung quá mức vào khớp dữ liệu huấn luyện."},{"k":"B","t":"LASSO đạt Test RSS nhỏ nhất và tạo ra vectơ trọng số thưa với nhiều hệ số bằng 0."},{"k":"C","t":"Ridge triệt tiêu toàn bộ 8 thuộc tính đặc trưng về 0 và chỉ giữ lại duy nhất trọng số bias w0."},{"k":"D","t":"Cả ba phương pháp đều cho ra bộ trọng số w* hoàn toàn giống hệt nhau trên mọi thuộc tính."}],"answer":["A","B"]},{"id":24,"text":"Ý nghĩa của việc LASSO triệt tiêu một số trọng số wj về 0 trong bài toán ứng dụng thực tế là gì?","multiple":false,"options":[{"k":"A","t":"Cho biết các thuộc tính tương ứng bị lỗi dữ liệu và bắt buộc phải xóa bỏ khỏi tập huấn luyện."},{"k":"B","t":"Cho biết mô hình LASSO bị bế tắc và không thể dự báo chính xác cho các mẫu dữ liệu mới."},{"k":"C","t":"Cho biết các thuộc tính tương ứng không mang lại nhiều giá trị và mô hình tự động chọn lọc thuộc tính quan trọng."},{"k":"D","t":"Cho biết tập dữ liệu huấn luyện bị đa cộng tuyến hoàn toàn khiến thuật toán dừng sớm."}],"answer":["C"]}]},{"id":13,"title":"Lựa chọn Siêu tham số & Đánh giá Mô hình","summary":["Hiệu quả dự báo của Hồi quy Ridge và LASSO phụ thuộc quyết định vào việc lựa chọn giá trị cho siêu tham số phạt λ. Nếu chọn λ quá nhỏ, hiệu ứng phạt không đáng kể và mô hình giữ nguyên nguy cơ quá khớp của OLS; ngược lại nếu chọn λ quá lớn, tất cả các trọng số đều bị thu nhỏ về sát 0 khiến mô hình bị kém khớp nghiêm trọng.","Để tìm giá trị λ* tối ưu, quy trình Lựa chọn Mô hình (Model Selection) sử dụng phương pháp chia tập dữ liệu thành ba phần độc lập: Tập huấn luyện (Training set) để học trọng số, Tập tối ưu (Validation set) để đo hiệu năng và chọn λ*, và Tập kiểm thử (Testing set) để đánh giá khả năng tổng quát hóa cuối cùng. Ngoài ra, kỹ thuật Kiểm chứng chéo (Cross-Validation) cũng được áp dụng rộng rãi để ước lượng lỗi tổng quát hóa một cách tin cậy trên các tập dữ liệu kích thước vừa và nhỏ.","B. Bài tập tham khảo"],"questions":[{"id":25,"text":"Quy trình lựa chọn siêu tham số phạt λ* (Model Selection) trong Hồi quy Ridge và LASSO được thực hiện như thế nào để đảm bảo tính khách quan? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chia tập dữ liệu D thành 3 tập rời nhau: Tập huấn luyện (Dtrain), Tập tối ưu (Tvalidation) và Tập kiểm thử (Ttest)."},{"k":"B","t":"Sử dụng Tập kiểm thử (Ttest) để huấn luyện trọng số w và chọn trực tiếp giá trị λ* tốt nhất."},{"k":"C","t":"Huấn luyện mô hình trên Dtrain với các giá trị λ khác nhau, chọn λ* cho hiệu năng cao nhất trên Tvalidation."},{"k":"D","t":"Chọn giá trị λ* sao cho tất cả các trọng số wj trong mô hình đạt giá trị cực đại lớn nhất."}],"answer":["A","C"]},{"id":26,"text":"Dưới góc nhìn ước lượng Bayes, việc sử dụng kỹ thuật hiệu chỉnh Ridge với chuẩn L2 tương đương với việc thực hiện phương pháp học nào?","multiple":false,"options":[{"k":"A","t":"Ước lượng Cực đại Likelihood (MLE) với giả thuyết phân bố đều trên tập tham số W."},{"k":"B","t":"Phương pháp gom nhóm phân vùng K-means trên không gian các vectơ trọng số."},{"k":"C","t":"Thuật toán lan truyền ngược Backpropagation trên mạng nơ-ron đa tầng có hàm kích hoạt Sigmoid."},{"k":"D","t":"Ước lượng Cực đại Hậu nghiệm (MAP) với giả thuyết trọng số w tuân theo phân bố Chuẩn Normal(0, σ^2 * I)."}],"answer":["D"]}]}]},{"id":"l4-5-clustering","title":"L4-5 clustering","summary":["Phân cụm dữ liệu (Clustering) là bài toán học không giám sát nhằm tự động phát hiện cấu trúc gom nhóm tự nhiên trong tập dữ liệu không có nhãn. Nguyên lý nền tảng là tối thiểu hóa khoảng cách nội cụm (tăng độ tương đồng giữa các điểm trong cùng nhóm) và tối đa hóa khoảng cách liên cụm (tăng độ biệt lập giữa các nhóm) dựa trên các thước đo khoảng cách như Euclid hay Manhattan. Thuật toán K-means là đại diện điển hình cho phương pháp phân vùng dựa trên tâm đại diện: khai báo trước số cụm k, sau đó lặp lại hai bước - (1) gán từng điểm dữ liệu vào tâm gần nhất và (2) cập nhật vị trí tâm cụm mới bằng trung bình cộng tọa độ các điểm thuộc cụm đó cho đến khi hàm tổng bình phương sai số SSE = Σ Σ ||x - ci||² hội tụ.","Do K-means truyền thống nhạy cảm với khởi tạo tâm ban đầu (dễ kẹt ở cực trị cục bộ) và điểm ngoại lệ, các biến thể như K-means++ (chọn tâm ban đầu dựa trên xác suất xác định) hay Online K-means (cập nhật tâm theo luồng dữ liệu thời gian thực w_mới = w_cũ + γ * (x - w_cũ)) được sử dụng để tối ưu. Để xác định số cụm k tối ưu, các kỹ thuật như phương pháp khuỷu tay (Elbow method) hay chỉ số Silhouette sil(i) = (b(i) - a(i)) / max(a(i), b(i)) được áp dụng để đánh giá độ nén và độ biệt lập.","Bên cạnh phân vùng, phương pháp Phân cụm Phân cấp (Hierarchical Clustering) xây dựng cây Dendrogram thể hiện các mức độ hợp nhất (từ dưới lên) hoặc chia tách (từ trên xuống) dựa trên các khoảng cách liên kết như Single-link, Complete-link hay phương pháp Ward mà không cần khai báo trước số cụm k. Khi dữ liệu chứa nhiều nhiễu hoặc có hình dạng phi cầu phức tạp (như hình vành khăn hay dải xoắn), thuật toán DBSCAN đại diện cho phương pháp dựa trên mật độ lại tỏ ra vượt trội: sử dụng hai tham số bán kính lân cận (Eps) và số điểm tối thiểu (MinPts) để gom các vùng mật độ cao liên tục thành cụm và tự động lọc bỏ các điểm ngoại lệ. Về bản chất kỹ thuật, phân cụm dữ liệu biến không gian thuộc tính đa chiều thành các phân vùng hình học hoặc cấu trúc phân cấp có ý nghĩa. Sự đánh đổi nằm ở đặc tính thuật toán: K-means có chi phí tính toán nhỏ O(n * k * t) nhưng gò ép cụm dạng hình cầu; Phân cấp trực quan cấu trúc dữ liệu tốt nhưng tốn bộ nhớ O(n²); còn DBSCAN linh hoạt về hình dạng và kháng nhiễu tốt nhưng nhạy cảm với sự chênh lệch mật độ trong cùng tập dữ liệu."],"topics":[{"id":1,"title":"Khái niệm Phân cụm Dữ liệu và Học không giám sát Phân cụm dữ liệu","summary":["(Clustering) là một bài toán cốt lõi trong học không giám sát (unsupervised learning), hướng tới việc tự động tổ chức tập dữ liệu D = {x1, x2, ..., xN} chưa được gán nhãn thành các nhóm tự nhiên gọi là cụm (cluster). Thuật toán tiếp nhận các vectơ đặc trưng đa chiều trong không gian Euclid và tính toán mức độ tương đồng giữa các đối tượng dựa trên khoảng cách hình học, từ đó phân tách các điểm dữ liệu thành các tập hợp sao cho các điểm cùng cụm tương tự nhau và khác biệt với các cụm còn lại. So với bài toán học có giám sát dựa vào nhãn lớp cho trước để huấn luyện mô hình dự đoán, phân cụm hoạt động hoàn toàn tự động dựa trên phân bố dữ liệu để phân đoạn khách hàng hoặc phân loại tài liệu mà không cần dữ liệu nhãn ban đầu."],"questions":[{"id":1,"text":"Trong một dự án phân tích dữ liệu giao dịch thương mại điện tử không có nhãn phân loại sẵn, đội ngũ kỹ thuật quyết định sử dụng thuật toán phân cụm. Đặc điểm nào sau đây thể hiện đúng bản chất của học không giám sát trong ngữ cảnh này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Thuật toán tự động tìm kiếm cấu trúc hình học và vùng mật độ tự nhiên của tập dữ liệu dựa trên không gian thuộc tính."},{"k":"B","t":"Mục tiêu chính là nhóm các giao dịch sao cho độ tương đồng giữa các đối tượng trong cùng một nhóm đạt mức tối đa."},{"k":"C","t":"Thuật toán cập nhật trọng số bằng cách so sánh nhãn dự đoán với nhãn mục tiêu thông qua hàm mất mát gán trước."},{"k":"D","t":"Quá trình gom nhóm bắt buộc phải có bước chia tập dữ liệu thành hai tập độc lập là tập huấn luyện và tập kiểm thử."}],"answer":["A","B"]},{"id":2,"text":"Một chuyên viên dữ liệu muốn áp dụng phân cụm để phân nhóm hành vi người dùng. Nhận định nào diễn tả chính xác điểm khác biệt căn bản giữa phân cụm và phân loại có giám sát?","multiple":false,"options":[{"k":"A","t":"Phân cụm hoạt động hoàn toàn dựa trên sự phân bố và độ tương đồng hình học của dữ liệu mà không cần nhãn lớp biết trước."},{"k":"B","t":"Phân cụm chỉ có thể hoạt động hiệu quả khi dữ liệu đầu vào đã được gán nhãn đầy đủ bởi các chuyên gia miền ứng dụng."},{"k":"C","t":"Phân loại hướng tới việc tối đa hóa khoảng cách nội cụm trong khi phân cụm hướng tới tối thiểu hóa sai số dự đoán nhãn."},{"k":"D","t":"Phân cụm chỉ áp dụng được cho dữ liệu một chiều trong khi phân loại hoạt động được trên dữ liệu đa chiều."}],"answer":["A"]}]},{"id":2,"title":"Thước đo Khoảng cách Nội cụm và Liên cụm","summary":["Chất lượng của một giải pháp phân cụm được quyết định bởi hai mục tiêu hình học song hành là khoảng cách nội cụm (intra-cluster distance) và khoảng cách liên cụm (inter-cluster distance). Bài toán yêu cầu tối ưu hóa đồng thời hai tiêu chí: tối thiểu hóa tổng khoảng cách giữa các điểm dữ liệu nằm trong cùng một cụm để đạt độ nén nội bộ cao nhất, đồng thời tối đa hóa khoảng cách giữa các trung tâm hoặc phần tử thuộc các cụm phân biệt để đảm bảo tính biệt lập rõ ràng. So với mô hình phân loại thông thường xác định ranh giới quyết định cố định, việc tối ưu khoảng cách nội cụm và liên cụm tạo ra các vùng gom nhóm linh hoạt giúp tách biệt các cấu trúc dữ liệu phức tạp."],"questions":[{"id":3,"text":"Cho hai giải pháp phân cụm C1 và C2 trên cùng một tập dữ liệu đa chiều. Để kết luận giải pháp C1 có chất lượng cấu trúc tốt hơn C2 theo các chỉ số nội tại, điều kiện nào sau đây là phù hợp? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tổng khoảng cách từ các điểm dữ liệu đến trọng tâm cụm tương ứng trong C1 nhỏ hơn trong C2."},{"k":"B","t":"Khoảng cách trung bình giữa các trọng tâm của các cụm biệt lập trong C1 nhỏ hơn trong C2."},{"k":"C","t":"Mức độ tách biệt giữa ranh giới các cụm lân cận trong C1 rõ rệt hơn và lớn hơn so với C2."},{"k":"D","t":"Khoảng cách nội cụm trung bình của C1 lớn hơn C2 nhằm đảm bảo tính bao phủ không gian."}],"answer":["A","C"]},{"id":4,"text":"Khi đánh giá chất lượng hình học của một mô hình phân cụm dựa trên đại diện tâm, hai tiêu chí tối ưu hóa nào thường được kết hợp đồng thời? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tối thiểu hóa khoảng cách giữa các điểm dữ liệu nằm trong cùng một cụm để đạt độ nén nội bộ."},{"k":"B","t":"Tối thiểu hóa khoảng cách giữa trọng tâm của các cụm phân biệt để tạo sự gần gũi giữa các nhóm."},{"k":"C","t":"Tối đa hóa khoảng cách nội cụm nhằm mở rộng phạm vi đại diện của từng trọng tâm."},{"k":"D","t":"Tối đa hóa khoảng cách tách biệt giữa trọng tâm các cụm độc lập để đảm bảo độ biệt lập."}],"answer":["A","D"]}]},{"id":3,"title":"Yêu cầu Kỹ thuật đối với Thuật toán Phân cụm","summary":["Một thuật toán phân cụm hiệu quả trong thực tế phải đáp ứng nhiều tiêu chí kỹ thuật nền tảng để làm việc tốt trên các tập dữ liệu thực tế lớn và đa dạng. Thuật toán cần đạt tính khả mở (scalability) trên dữ liệu quy mô lớn, khả năng xử lý đa dạng kiểu thuộc tính (định lượng, định danh, chuỗi, đồ thị), phát hiện cụm có hình dạng bất kỳ (hình cầu, dải xoắn, vành khăn), cũng như khả năng chịu nhiễu để lọc bỏ các điểm ngoại lệ mà không làm biến dạng kết quả.","Ví dụ, các thuật toán phân vùng đơn giản chỉ gom được các cụm hình cầu đồng nhất, trong khi các phương pháp tiên tiến đáp ứng đủ các tiêu chí này có thể xử lý cả cấu trúc vành khăn lồng nhau chứa nhiều điểm nhiễu cô lập."],"questions":[{"id":5,"text":"Khi lựa chọn một thuật toán phân cụm cho cơ sở dữ liệu lớn chứa cả thuộc tính định lượng và định danh có nhiều điểm ngoại lệ, yêu cầu kỹ thuật nào được ưu tiên hàng đầu?","multiple":false,"options":[{"k":"A","t":"Thuật toán có khả năng mở rộng tốt, chịu nhiễu cao và hỗ trợ các khoảng cách phi Euclid cho thuộc tính hỗn hợp."},{"k":"B","t":"Thuật toán bắt buộc phải giả định các cụm có hình dạng cầu đối xứng để tăng tốc độ tính toán."},{"k":"C","t":"Thuật toán không cần xử lý các điểm dữ liệu thiếu hay ngoại lệ vì chúng sẽ tự động bị loại bỏ ở bước gán."},{"k":"D","t":"Thuật toán chỉ hoạt động trên không gian hai chiều nhằm đảm bảo khả năng trực quan hóa đồ họa."}],"answer":["A"]},{"id":6,"text":"Thách thức kỹ thuật nào thường xuất hiện khi áp dụng các thuật toán phân cụm phân vùng truyền thống trên tập dữ liệu thực tế? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tốc độ tính toán giảm mạnh thành bậc lũy thừa khi số lượng điểm dữ liệu tăng lên gấp đôi."},{"k":"B","t":"Nhạy cảm với sự xuất hiện của các điểm dữ liệu ngoại lệ làm lệch vị trí trọng tâm đại diện."},{"k":"C","t":"Khó khăn trong việc phát hiện các cụm có hình dạng phi cầu phức tạp như hình vành khăn hay dải xoắn."},{"k":"D","t":"Bắt buộc phải chuyển đổi tất cả dữ liệu định tính sang dạng dữ liệu nhị phân trước khi chạy thuật toán."}],"answer":["B","C"]}]},{"id":4,"title":"Ứng dụng Thực tế của Phân cụm Dữ liệu","summary":["Phân cụm dữ liệu đóng vai trò là kỹ thuật khám phá tri thức quan trọng trong nhiều lĩnh vực công nghiệp và nghiên cứu nhờ khả năng tự động gom nhóm đối tượng. Kỹ thuật này được triển khai trong phân đoạn thị trường (market segmentation) để nhận diện nhóm khách hàng tiềm năng, phân tích mạng xã hội (social network analysis) để phát hiện cộng đồng, phân loại lưu lượng mạng (network traffic classification) trong mạng không dây, nén hình ảnh (image compression), tiền xử lý và giảm chiều dữ liệu, trong sinh học để phân loại gen."],"questions":[{"id":7,"text":"Trong thực tế công nghiệp và nghiên cứu, phân cụm dữ liệu được ứng dụng hiệu quả trong các bài toán nào sau đây? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Dự đoán chính xác giá nhà trong tương lai dựa trên lịch sử giao dịch và diện tích."},{"k":"B","t":"Phân đoạn tập khách hàng thương mại điện tử dựa trên thói quen mua sắm để tối ưu tiếp thị."},{"k":"C","t":"Phân loại email nhận được vào hai thư mục thư rác hoặc thư thường dựa trên nhãn mẫu."},{"k":"D","t":"Nén hình ảnh và giảm dung lượng lưu trữ bằng cách giảm số lượng màu đại diện."}],"answer":["B","D"]},{"id":8,"text":"Hai kịch bản ứng dụng nào thể hiện vai trò của phân cụm như một bước tiền xử lý cho các mô hình phân tích khác? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Nhận diện chữ viết tay từ hình ảnh đã gán nhãn chính xác."},{"k":"B","t":"Dự đoán chuỗi thời gian doanh thu tài chính dựa trên mô hình hồi quy."},{"k":"C","t":"Rút gọn số lượng đặc trưng bằng cách gộp các thuộc tính có sự tương đồng cao."},{"k":"D","t":"Trích xuất các điểm đại diện tâm cụm để giảm kích thước tập dữ liệu huấn luyện cho mô hình."}],"answer":["C","D"]}]},{"id":5,"title":"Các Thước đo Khoảng cách và Độ tương đồng","summary":["Thước đo khoảng cách định lượng độ tương đồng giữa các đối tượng dữ liệu và quyết định cấu trúc hình học của các cụm trong không gian thuộc tính. Ba thước đo phổ biến nhất bao gồm khoảng cách Euclid (chuẩn L2) d(x, y) = √(∑(xi - yi)²) đo độ dài đoạn thẳng trực tiếp, khoảng cách Manhattan (chuẩn L1) d(x, y) = ∑|xi - yi| tính tổng độ lệch theo các trục tọa độ, và khoảng cách Hamming đếm số lượng thuộc tính khác biệt cho dữ liệu định danh hoặc chuỗi. So với khoảng cách Euclid nhạy cảm với các điểm ngoại lệ do phép bình phương, khoảng cách Manhattan bền vững hơn với dữ liệu đa chiều, trong khi khoảng cách Hamming là giải pháp duy nhất cho dữ liệu chuỗi phi số."],"questions":[{"id":9,"text":"Cho hai điểm dữ liệu x = (1, 5) và y = (4, 1) trong không gian Euclid hai chiều. Khoảng cách Euclid và khoảng cách Manhattan giữa hai điểm này lần lượt có giá trị là bao nhiêu?","multiple":false,"options":[{"k":"A","t":"Khoảng cách Euclid bằng 5 và khoảng cách Manhattan bằng 7."},{"k":"B","t":"Khoảng cách Euclid bằng 7 và khoảng cách Manhattan bằng 5."},{"k":"C","t":"Khoảng cách Euclid bằng 25 và khoảng cách Manhattan bằng 7."},{"k":"D","t":"Khoảng cách Euclid bằng 5 và khoảng cách Manhattan bằng 25."}],"answer":["A"]},{"id":10,"text":"Đặc điểm kỹ thuật nào phản ánh đúng thuộc tính của các thước đo khoảng cách phổ biến? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Khoảng cách Euclid (chuẩn L2) nhạy cảm hơn với giá trị ngoại lệ so với khoảng cách Manhattan (chuẩn L1) do phép bình phương độ lệch."},{"k":"B","t":"Khoảng cách Hamming được tính bằng tổng số vị trí có thuộc tính khác nhau giữa hai chuỗi hoặc vectơ định danh."},{"k":"C","t":"Khoảng cách Manhattan luôn cho kết quả nhỏ hơn khoảng cách Euclid trên mọi cặp điểm dữ liệu."},{"k":"D","t":"Khoảng cách Euclid chỉ áp dụng được cho dữ liệu dạng chuỗi văn bản không chứa tọa độ số."}],"answer":["A","B"]}]},{"id":6,"title":"Phương pháp Phân vùng Dữ liệu","summary":["Phương pháp phân vùng (partition method) chia tập n đối tượng dữ liệu thành k phân vùng độc lập sao cho mỗi phân vùng chứa ít nhất một đối tượng và mỗi điểm thuộc về đúng một cụm. Do việc duyệt toàn bộ tổ hợp chia nhóm để đạt tối ưu toàn cục bị hạn chế về mặt tính toán, thuật toán áp dụng các phương pháp heuristic tham lam (greedy heuristics) như K-means để di chuyển điểm dữ liệu giữa các nhóm qua từng vòng lặp nhằm cải thiện chất lượng tối ưu cục bộ. Phương pháp phân vùng tạo ra các cụm phẳng rời rạc và hoạt động cực kỳ hiệu quả khi phát hiện các cụm có dạng hình cầu đồng đều."],"questions":[{"id":11,"text":"Nguyên lý cốt lõi của phương pháp phân cụm phân vùng (partition-based) thể hiện ở những đặc điểm nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chia tập n đối tượng thành k cụm sao cho mỗi cụm chứa ít nhất một đối tượng và mỗi điểm thuộc về đúng một cụm."},{"k":"B","t":"Xây dựng một cấu trúc cây thể hiện các cụm lồng nhau từ dưới lên hoặc từ trên xuống."},{"k":"C","t":"Thường sử dụng các thuật toán heuristic lặp để tối ưu hóa vị trí tâm đại diện cụm."},{"k":"D","t":"Tự động xác định số lượng cụm k tối ưu mà không cần bất kỳ tham số đầu vào nào từ người dùng."}],"answer":["A","C"]},{"id":12,"text":"Nhược điểm chung lớn nhất của phương pháp phân vùng dựa trên tâm (centroid-based partition) khi xử lý tập dữ liệu thực tế là gì?","multiple":false,"options":[{"k":"A","t":"Chi phí tính toán tăng theo chuỗi lũy thừa khiến thuật toán không thể chạy trên tập dữ liệu nhỏ."},{"k":"B","t":"Gặp khó khăn khi tìm kiếm các cụm có kích thước chênh lệch lớn, mật độ không đều hoặc hình dạng phi cầu."},{"k":"C","t":"Luôn tạo ra cấu trúc cây phân cấp quá phức tạp gây khó khăn cho việc giải thích kết quả."},{"k":"D","t":"Bắt buộc phải loại bỏ toàn bộ dữ liệu thuộc tính định lượng trước khi tính toán."}],"answer":["B"]}]},{"id":7,"title":"Thuật toán K-means","summary":["Thuật toán K-means (Lloyd, 1957) là phương pháp phân cụm phân vùng dựa trên tâm (centroid-based) phổ biến nhất nhờ tính đơn giản và hiệu quả. Thuật toán nhận vào tập dữ liệu D, số cụm k và hàm khoảng cách.","Quy trình lặp gồm hai bước chính: gán từng điểm dữ liệu x vào cụm Ci có tâm ceni gần nhất, sau đó tính lại ceni bằng trung bình cộng tọa độ các điểm thuộc cụm. Quá trình lặp dừng lại khi tâm cụm không đổi hoặc tổng bình phương sai số SSE = ∑∑ dist(x, ceni)² đạt trạng thái hội tụ. K-means có độ phức tạp thời gian tuyến tính theo số dữ liệu, làm cho nó trở thành lựa chọn hàng đầu cho dữ liệu quy mô lớn."],"questions":[{"id":13,"text":"Trong thuật toán K-means cơ bản, quy trình thực thi lặp lại hai bước chính nào cho đến khi hội tụ? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bước gán: Gán từng điểm dữ liệu vào cụm có trọng tâm gần nhất dựa trên hàm khoảng cách."},{"k":"B","t":"Bước phân tách: Chia đôi cụm có đường kính lớn nhất thành hai cụm nhỏ hơn."},{"k":"C","t":"Bước lọc nhiễu: Loại bỏ tất cả các điểm dữ liệu nằm cách tâm cụm quá hai lần độ lệch chuẩn."},{"k":"D","t":"Bước cập nhật: Tính toán lại vị trí trọng tâm của mỗi cụm bằng trung bình cộng tọa độ các điểm thuộc cụm đó."}],"answer":["A","D"]},{"id":14,"text":"Xét tập dữ liệu 1D gồm 4 điểm: x1 = 2, x2 = 4, x3 = 10, x4 = 12. Giả sử tại một vòng lặp, K-means phân thành 2 cụm: C1 = {2, 4} và C2 = {10, 12}. Nhận định nào sau đây là đúng về bước cập nhật trọng tâm và kiểm tra điều kiện dừng? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Trọng tâm mới của hai cụm lần lượt là c1 = 2 và c2 = 10."},{"k":"B","t":"Trọng tâm mới của hai cụm lần lượt là c1 = 3 và c2 = 11."},{"k":"C","t":"Nếu ở vòng lặp tiếp theo các điểm vẫn giữ nguyên gán cụm như trên, thuật toán K-means sẽ hội tụ và dừng lại."},{"k":"D","t":"Thuật toán bắt buộc phải chạy thêm ít nhất 10 vòng lặp nữa dù gán cụm không hề thay đổi."}],"answer":["B","C"]}]},{"id":8,"title":"Hàm Mục tiêu SSE và Điều kiện Hội tụ trong K-means","summary":["Tổng bình phương sai số (Sum-of-Squared Error - SSE) đóng vai trò là hàm mục tiêu tối ưu hóa, đo lường tổng khoảng cách bình phương từ mỗi điểm dữ liệu đến tâm cụm tương ứng. Công thức tính SSE là E = ∑_(i=1)^k ∑_(x ∈ Ci) dist(x, ceni)², trong đó ceni là trọng tâm đại diện của cụm Ci.","Thuật toán K-means đảm bảo giá trị E giảm đơn điệu sau mỗi vòng lặp và được coi là hội tụ khi không còn điểm dữ liệu nào bị đổi cụm, vị trí các tâm cụm ceni thay đổi không đáng kể, hoặc mức giảm của hàm SSE đạt ngưỡng tối thiểu. So với các mô hình không có hàm mục tiêu rõ ràng, việc sử dụng SSE giúp K-means đảm bảo tính hội tụ toán học về nghiệm tối ưu cục bộ."],"questions":[{"id":15,"text":"Dấu hiệu nào sau đây chỉ ra rằng thuật toán K-means đã đạt trạng thái hội tụ và có thể dừng vòng lặp? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giá trị hàm mục tiêu SSE đạt mức giảm đột biến và tiếp tục tăng mạnh ở vòng lặp sau."},{"k":"B","t":"Vị trí các trọng tâm cụm không có sự thay đổi đáng kể so với vòng lặp trước đó."},{"k":"C","t":"Số lượng cụm k tự động giảm về 1 sau khi tính toán xong tọa độ trọng tâm."},{"k":"D","t":"Không còn điểm dữ liệu nào bị gán lại sang cụm khác giữa hai vòng lặp liên tiếp."}],"answer":["B","D"]},{"id":16,"text":"Phát biểu nào sau đây mô tả đúng bản chất toán học của hàm mục tiêu Tổng bình phương sai số SSE trong K-means?","multiple":false,"options":[{"k":"A","t":"SSE là tổng khoảng cách lớn nhất giữa hai điểm dữ liệu bất kỳ thuộc hai cụm biệt lập."},{"k":"B","t":"SSE đo lường tổng bình phương khoảng cách từ mỗi điểm dữ liệu đến trọng tâm cụm mà nó thuộc về."},{"k":"C","t":"SSE luôn có giá trị tăng dần sau mỗi vòng lặp cho đến khi thuật toán hoàn thành."},{"k":"D","t":"SSE là khoảng cách trung bình ngắn nhất từ một điểm dữ liệu đến cụm lân cận gần nhất."}],"answer":["B"]}]},{"id":9,"title":"Nhược điểm Khởi tạo Tâm Ngẫu nhiên và Giải pháp Lặp lại K-means","summary":["Nhược điểm lớn nhất của K-means truyền thống là chất lượng phân cụm phụ thuộc rất lớn vào vị trí của k tâm khởi tạo ngẫu nhiên ban đầu. Khi các tâm khởi tạo rơi vào cùng một cụm tự nhiên hoặc nằm quá gần nhau, K-means dễ mắc kẹt tại các nghiệm tối ưu cục bộ kém chất lượng, dẫn đến kết quả phân cụm bị sai lệch và không nhất quán qua các lần chạy. Để khắc phục, giải pháp thực tế là chạy K-means nhiều lần độc lập với các tập tâm khởi tạo ngẫu nhiên khác nhau, sau đó chọn ra kết quả có tổng sai số bình phương SSE nhỏ nhất. So với việc chỉ chạy một lần, phương pháp lặp lại gia tăng xác suất đạt nghiệm tối ưu toàn cục nhưng làm tăng tổng thời gian tính toán."],"questions":[{"id":17,"text":"Việc chọn ngẫu nhiên k trọng tâm ban đầu trong K-means truyền thống có thể dẫn đến những rủi ro nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chi phí bộ nhớ tăng lên gấp đôi sau mỗi vòng lặp do phải lưu trữ ma trận khoảng cách."},{"k":"B","t":"Thuật toán bị rơi vào vòng lặp vô tận và không bao giờ dừng lại dù tập dữ liệu hữu hạn."},{"k":"C","t":"Thuật toán hội tụ về nghiệm cực trị cục bộ kém chất lượng do các tâm ban đầu nằm quá gần nhau."},{"k":"D","t":"Kết quả phân cụm thiếu tính nhất quán và thay đổi tùy thuộc vào giá trị khởi tạo ngẫu nhiên."}],"answer":["C","D"]},{"id":18,"text":"Hai giải pháp thực tế phổ biến nhằm khắc phục nhược điểm khởi tạo ngẫu nhiên của K-means truyền thống bao gồm: (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chạy thuật toán K-means nhiều lần độc lập với các tập tâm khởi tạo khác nhau và chọn kết quả có SSE nhỏ nhất."},{"k":"B","t":"Áp dụng cơ chế chọn tâm ban đầu dựa trên phân bố xác suất tỷ lệ thuận với bình phương khoảng cách D(x)²."},{"k":"C","t":"Bắt buộc gán điểm dữ liệu đầu tiên trong tập dữ liệu làm trọng tâm cho tất cả các cụm."},{"k":"D","t":"Chuyển toàn bộ dữ liệu sang không gian một chiều trước khi chọn tâm khởi tạo ngẫu nhiên."}],"answer":["A","B"]}]},{"id":10,"title":"Thuật toán K-means++","summary":["Thuật toán K-means++ được đề xuất nhằm giải quyết triệt để nhược điểm chọn tâm ngẫu nhiên của K-means bằng cơ chế khởi tạo tâm dựa trên phân bố xác suất. Thuật toán chọn ngẫu nhiên tâm c1 đầu tiên, sau đó chọn các tâm ci tiếp theo từ dữ liệu với xác suất P(x') = D(x')² / ∑ D(x)², trong đó D(x) là khoảng cách ngắn nhất từ điểm x đến tâm gần nhất đã chọn. Công thức này đảm bảo các điểm nằm càng xa các tâm hiện có càng có xác suất cao được chọn làm tâm mới, giúp các tâm khởi tạo dải đều trong không gian. Kết quả thử nghiệm trên tập dữ liệu Spam và Norm25 chứng minh K-means++ giúp giảm mạnh giá trị hàm mục tiêu Phi, tăng tốc độ hội tụ và giảm đáng kể sai số so với K-means truyền thống."],"questions":[{"id":19,"text":"Điểm cải tiến kỹ thuật cốt lõi của K-means++ so với K-means truyền thống nằm ở bước nào và thực hiện ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Cải tiến bước khởi tạo tâm bằng cách chọn các tâm tiếp theo với xác suất P(x') = D(x')² / ∑ D(x)²."},{"k":"B","t":"Thay đổi công thức tính trọng tâm cụm từ trung bình cộng sang trung vị của các điểm."},{"k":"C","t":"Đảm bảo các trọng tâm ban đầu phân bố dải đều và khoảng cách giữa chúng được đẩy rộng ra."},{"k":"D","t":"Loại bỏ hoàn toàn yếu tố ngẫu nhiên trong việc chọn trọng tâm đầu tiên c1."}],"answer":["A","C"]},{"id":20,"text":"Kết quả thử nghiệm K-means++ trên các tập dữ liệu thực tế (như Spam hay Norm25) trong tài liệu giảng dạy cho thấy ưu điểm nổi bật nào?","multiple":false,"options":[{"k":"A","t":"K-means++ luôn yêu cầu thời gian chạy lâu hơn K-means truyền thống trên mọi giá trị k."},{"k":"B","t":"K-means++ giúp giảm mạnh giá trị hàm mục tiêu Phi (Φ), tăng tốc độ hội tụ và giảm sai số phân cụm."},{"k":"C","t":"K-means++ tự động tìm được số cụm k tối ưu mà không cần chạy lặp qua nhiều k."},{"k":"D","t":"K-means++ chỉ hoạt động hiệu quả khi dữ liệu có số chiều lớn hơn 1000 đặc trưng."}],"answer":["B"]}]},{"id":11,"title":"Phương pháp Elbow Xác định Số cụm K Tối ưu","summary":["Do K-means yêu cầu người dùng phải cung cấp trước tham số k, phương pháp Elbow (điểm khuỷu tay) là kỹ thuật heuristic giúp xác định số lượng cụm k tối ưu dựa trên biến thiên của sai số nội cụm. Phương pháp thực hiện chạy K-means với một chuỗi giá trị k tăng dần (ví dụ k từ 1 đến 10), tính tổng bình phương khoảng cách nội cụm S (SSE) cho mỗi k, sau đó biểu diễn đường cong mối quan hệ giữa S và k trên đồ thị. Điểm gập (elbow) trên đồ thị – nơi tốc độ giảm của S bắt đầu chậm lại đột ngột – được chọn làm số cụm k tối ưu vì nó thể hiện điểm cân bằng giữa độ chính xác và tính gọn nhẹ của mô hình. phương pháp Elbow cung cấp căn cứ định lượng trực quan để xác định cấu trúc cụm thực sự."],"questions":[{"id":21,"text":"Khi áp dụng phương pháp Elbow để tìm số cụm k phù hợp cho K-means, nhà phân tích thực hiện các bước nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chạy K-means với một chuỗi giá trị k tăng dần và tính tổng bình phương sai số SSE (S) tương ứng với mỗi k."},{"k":"B","t":"Chọn giá trị k tại điểm mà hàm SSE đạt giá trị lớn nhất trên đồ thị biểu diễn."},{"k":"C","t":"Bắt buộc chọn k bằng đúng số lượng thuộc tính đặc trưng có trong tập dữ liệu đầu vào."},{"k":"D","t":"Vẽ đồ thị biểu diễn mối quan hệ giữa SSE và k để tìm điểm khuỷu tay (elbow point) – nơi tốc độ giảm SSE chậm lại rõ rệt."}],"answer":["A","D"]},{"id":22,"text":"Nguyên lý toán học đằng sau điểm gập (elbow) trên đồ thị SSE theo k là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tăng k luôn làm tăng giá trị sai số nội cụm do số lượng cụm tăng lên."},{"k":"B","t":"Khi k tăng đến giá trị cấu trúc tự nhiên, việc tăng thêm k không còn giúp giảm đáng kể phương sai nội cụm."},{"k":"C","t":"Điểm gập thể hiện sự cân bằng hợp lý giữa việc giảm sai số nội cụm và việc giữ mô hình đơn giản."},{"k":"D","t":"Tại điểm gập, khoảng cách giữa các trọng tâm cụm hoàn toàn triệt tiêu về giá trị 0."}],"answer":["B","C"]}]},{"id":12,"title":"Đánh giá Chất lượng Phân cụm bằng Chỉ số Silhouette","summary":["Chỉ số Silhouette là thước đo đánh giá chất lượng phân cụm nội tại (intrinsic evaluation), đo lường độ chặt chẽ của điểm dữ liệu trong cụm so với mức độ tách biệt với cụm lân cận. Với mỗi điểm oi, chỉ số Silhouette được tính theo công thức sil(oi) = (b(oi) - a(oi)) / max(a(oi), b(oi)), trong đó a(oi) là khoảng cách trung bình đến các điểm trong cùng cụm, và b(oi) là khoảng cách trung bình nhỏ nhất đến các điểm thuộc cụm lân cận gần nhất. Giá trị sil(oi) nằm trong khoảng [-1, 1]; giá trị tiến gần 1 phản ánh điểm dữ liệu phân cụm rất tốt, trong khi giá trị âm cảnh báo phân sai cụm. Chọn k có chỉ số Silhouette trung bình (Average Silhouette) cao nhất giúp xác định cấu trúc cụm tối ưu chính xác."],"questions":[{"id":23,"text":"Cho một điểm dữ liệu i có khoảng cách nội cụm trung bình a(i) = 2.0 và khoảng cách trung bình nhỏ nhất đến cụm lân cận b(i) = 6.0. Giá trị Silhouette sil(i) của điểm này bằng bao nhiêu?","multiple":false,"options":[{"k":"A","t":"sil(i) = 0.33."},{"k":"B","t":"sil(i) = 0.50."},{"k":"C","t":"sil(i) = 0.67."},{"k":"D","t":"sil(i) = -0.67."}],"answer":["C"]},{"id":24,"text":"Nhận định nào diễn tả đúng ý nghĩa của chỉ số Silhouette khi đánh giá kết quả phân cụm? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Chỉ số Silhouette trung bình trên toàn bộ dữ liệu luôn đạt giá trị lớn nhất tại k = 1."},{"k":"B","t":"Điểm dữ liệu có giá trị Silhouette tiến gần về 1 chứng tỏ nó được phân cụm rất phù hợp."},{"k":"C","t":"Giá trị Silhouette chỉ phụ thuộc vào khoảng cách nội cụm a(i) mà hoàn toàn không xét tới khoảng cách liên cụm b(i)."},{"k":"D","t":"Điểm dữ liệu có giá trị Silhouette nhận giá trị âm cảnh báo khả năng điểm đó đã bị phân sai sang cụm không phù hợp."}],"answer":["B","D"]}]},{"id":13,"title":"Kỹ thuật Xử lý Nhiễu và Điểm Ngoại lệ trong K-means","summary":["Sự hiện diện của nhiễu và điểm ngoại lệ (outliers) ảnh hưởng nghiêm trọng đến K-means do tâm cụm tính bằng trung bình cộng rất nhạy cảm với các giá trị xa trung tâm. Hai giải pháp tiền xử lý cốt lõi là loại bỏ ngoại lệ (outlier removal - loại bỏ các điểm có khoảng cách quá xa tâm cụm trước hoặc trong quá trình học) và lấy mẫu ngẫu nhiên (random sampling - thực hiện phân cụm trên một tập mẫu S ngẫu nhiên chứa ít nhiễu hơn, sau đó gán dữ liệu còn lại vào các tâm cụm thu được). So với việc chạy K-means trực tiếp trên dữ liệu thô chứa nhiều biến động, các kỹ thuật này gia tăng độ bền vững của mô hình và tiết kiệm đáng kể tài nguyên tính toán."],"questions":[{"id":25,"text":"Kỹ thuật loại bỏ ngoại lệ (outlier removal) và lấy mẫu ngẫu nhiên (random sampling) giúp ích gì cho K-means? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giảm sự lệch vị trí trọng tâm do trung bình cộng rất nhạy cảm với các giá trị nằm cực xa trung tâm."},{"k":"B","t":"Loại bỏ hoàn toàn yêu cầu tính toán khoảng cách giữa các điểm dữ liệu trong vòng lặp."},{"k":"C","t":"Giúp thuật toán K-means luôn tìm được nghiệm tối ưu toàn cục chỉ sau 1 vòng lặp duy nhất."},{"k":"D","t":"Xây dựng mô hình trên tập mẫu S ít nhiễu giúp tiết kiệm tài nguyên tính toán và gia tăng độ bền vững."}],"answer":["A","D"]},{"id":26,"text":"Hai lợi ích kỹ thuật trực tiếp khi áp dụng tiền xử lý lọc ngoại lệ cho K-means là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giúp các trọng tâm cụm không bị kéo dịch chuyển bất thường về phía các giá trị nhiễu cô lập."},{"k":"B","t":"Đảm bảo cấu trúc các cụm tìm được phản ánh đúng phân bố mật độ thực tế của đa số dữ liệu."},{"k":"C","t":"Đảm bảo tất cả các cụm tạo ra đều chứa số lượng điểm dữ liệu bằng nhau tuyệt đối."},{"k":"D","t":"Làm cho thuật toán K-means không cần phải cập nhật lại tọa độ trọng tâm ở các vòng lặp sau."}],"answer":["A","B"]}]},{"id":14,"title":"Thuật toán Online K-means cho Dữ liệu Luồng và Dữ liệu Lớn","summary":["Thuật toán K-means truyền thống bắt buộc phải đọc toàn bộ dữ liệu huấn luyện trong mỗi vòng lặp nên gặp bế tắc khi xử lý dữ liệu quy mô khổng lồ hoặc dữ liệu luồng (stream data) xuất hiện theo thời gian, dẫn đến sự ra đời của Online K-means. Về mặt kỹ thuật, Online K-means giải quyết giới hạn này bằng cách tuần tự hóa quy trình phân cụm (serialization), chỉ lưu trữ danh sách k tâm cụm trong bộ nhớ và cập nhật vị trí các tâm ngay khi nhận từng điểm dữ liệu mới. Chi tiết này loại bỏ hoàn toàn yêu cầu đọc lại toàn bộ tập dữ liệu gốc, đưa chi phí bộ nhớ về O(k) và cho phép xử lý luồng dữ liệu liên tục. So với K-means dạng lô (batch) có chi phí lưu trữ và tính toán tốn kém, Online K-means đạt tốc độ xử lý thời gian thực vượt trội trên các hệ thống Big Data."],"questions":[{"id":27,"text":"Hạn chế lớn nhất của K-means dạng lô (batch K-means) khiến nó không thể làm việc với dữ liệu luồng (stream data) là gì?","multiple":false,"options":[{"k":"A","t":"Không thể tính toán khoảng cách Euclid khi số lượng điểm dữ liệu vượt quá 1000 mẫu."},{"k":"B","t":"Yêu cầu bộ nhớ phải lưu trữ toàn bộ ma trận nghịch đảo của tất cả các điểm dữ liệu."},{"k":"C","t":"Bắt buộc phải đọc và duyệt qua toàn bộ tập dữ liệu huấn luyện trong mỗi vòng lặp để cập nhật trọng tâm."},{"k":"D","t":"Chỉ cho phép xử lý các tập dữ liệu có đúng 2 thuộc tính đặc trưng."}],"answer":["C"]},{"id":28,"text":"Thuật toán Online K-means giải quyết bài toán phân cụm trên Big Data và luồng dữ liệu nhờ những cơ chế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tuần tự hóa quy trình: chỉ lưu giữ danh sách k tâm trong bộ nhớ và cập nhật ngay khi tiếp nhận từng mẫu dữ liệu xt."},{"k":"B","t":"Cập nhật vị trí tâm cụm dựa trên thông tin đạo hàm ngẫu nhiên (stochastic gradient) từ một mẫu duy nhất."},{"k":"C","t":"Yêu cầu lưu trữ lại toàn bộ lịch sử dữ liệu quá khứ trong bộ nhớ đệm trước khi tính toán."},{"k":"D","t":"Tăng số lượng trọng tâm k lên liên tục theo tốc độ tăng của luồng dữ liệu đầu vào."}],"answer":["A","B"]}]},{"id":15,"title":"Cơ chế Gradient Descent và Tốc độ Học trong Online K-means","summary":["Khác với K-means truyền thống cập nhật tâm cụm bằng trung bình cộng hình học trên toàn tập dữ liệu, Online K-means bản chất là một mô hình học trực tuyến (online learning) giải bài toán tối ưu hàm mất mát Q_kmeans = ∑(xi - w(xi))² thông qua thuật toán giảm đạo hàm ngẫu nhiên (Stochastic Gradient Descent - SGD).","Thay vì tính full gradient trên toàn bộ M mẫu Q't = ∑[xi - wt(xi)], Online K-means chỉ tính đạo hàm cục bộ trên một mẫu xt duy nhất tại thời điểm t và cập nhật tâm cụm gần nhất wt theo quy tắc wt+1 = wt + γt * (xt - wt(xt)). Trong đó, tốc độ học (learning rate) γt là một dãy số dương thỏa mãn điều kiện ∑ γt = ∞ và ∑ γt² < ∞, thường chọn dưới dạng γt = (t + τ)-κ với τ, κ > 0; hằng số κ ∈ (0.5, 1] đóng vai trò là tốc độ quên (forgetting rate), điều khiển mức độ mô hình ghi nhớ dữ liệu quá khứ so với ảnh hưởng của các quan sát mới. So với cơ chế tính toán tĩnh của K-means dạng lô, việc ứng dụng SGD với tốc độ học điều chỉnh linh hoạt giúp Online K-means học thích ứng liên tục theo thời gian."],"questions":[{"id":29,"text":"Trong công thức cập nhật tâm cụm của Online K-means wt+1 = wt + γt * (xt - wt), ý nghĩa của tốc độ học (learning rate) γt = (t + τ)^(-κ) là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hằng số κ ∈ (0.5, 1] đóng vai trò là tốc độ quên (forgetting rate), điều tiết mức độ ảnh hưởng của dữ liệu mới so với quá khứ."},{"k":"B","t":"Khi t tăng lên, tốc độ học γt giảm dần giúp vị trí tâm cụm hội tụ ổn định hơn về lâu dài."},{"k":"C","t":"Tốc độ học γt bắt buộc phải là một số nguyên dương tăng dần theo thời gian lặp t."},{"k":"D","t":"Giá trị κ càng lớn thì quan sát mới xt tại thời điểm t càng chiếm tỷ trọng đóng góp lớn vào vị trí tâm mới."}],"answer":["A","B"]},{"id":30,"text":"Cho một tâm cụm hiện tại w = (2, 4) và nhận được điểm dữ liệu mới x = (6, 10). Nếu tốc độ học tại bước này là γ = 0.25, tọa độ tâm cụm mới w_mới sau khi cập nhật bằng bao nhiêu?","multiple":false,"options":[{"k":"A","t":"w_mới = (2.5, 4.5)."},{"k":"B","t":"w_mới = (8.0, 14.0)."},{"k":"C","t":"w_mới = (3.0, 5.5)."},{"k":"D","t":"w_mới = (4.0, 7.0)."}],"answer":["C"]}]},{"id":16,"title":"Phương pháp Phân cụm Phân cấp và Biểu đồ cây Dendrogram","summary":["Phân cụm phân cấp (Hierarchical Clustering) xây dựng một cấu trúc cây thể hiện mối quan hệ lồng nhau giữa các cụm ở nhiều mức độ chi tiết khác nhau mà không yêu cầu khai báo trước số cụm k. Phương pháp bao gồm hai tiếp cận chính: gom cụm (Agglomerative - từ dưới lên, bắt đầu từ các điểm đơn lẻ rồi gộp dần) và chia tách (Divisive - từ trên xuống, bắt đầu từ một cụm lớn rồi chia nhỏ), trong đó toàn bộ quá trình hợp nhất được trực quan hóa bằng biểu đồ cây Dendrogram. Người dùng có thể cắt cây Dendrogram theo một đường nằm ngang ở độ cao khoảng cách mong muốn để thu được số cụm tối ưu mà không cần huấn luyện lại mô hình."],"questions":[{"id":31,"text":"Điểm khác biệt quan trọng nhất về mặt tham số giữa Phân cụm Phân cấp (Hierarchical Clustering) và K-means là gì?","multiple":false,"options":[{"k":"A","t":"Phân cụm phân cấp chỉ hoạt động trên không gian một chiều trong khi K-means hoạt động đa chiều."},{"k":"B","t":"Phân cụm phân cấp bắt buộc phải sử dụng khoảng cách Manhattan thay vì khoảng cách Euclid."},{"k":"C","t":"Phân cụm phân cấp luôn tạo ra các cụm có dạng hình cầu hoàn hảo với mật độ cố định."},{"k":"D","t":"Phân cụm phân cấp không yêu cầu người dùng phải khai báo trước số lượng cụm k khi bắt đầu thuật toán."}],"answer":["D"]},{"id":32,"text":"Vai trò chính của biểu đồ cây Dendrogram trong phân cụm phân cấp là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tự động loại bỏ tất cả các giá trị ngoại lệ khỏi tập dữ liệu mà không cần lọc trước."},{"k":"B","t":"Trực quan hóa toàn bộ lịch sử hợp nhất hoặc chia tách các cụm ở các mức độ khoảng cách khác nhau."},{"k":"C","t":"Cho phép người dùng chọn số lượng cụm linh hoạt bằng cách cắt cây theo một đường nằm ngang ở độ cao mong muốn."},{"k":"D","t":"Chuyển đổi dữ liệu từ dạng thuộc tính phi số sang dạng số tự nhiên."}],"answer":["B","C"]}]},{"id":17,"title":"Các Phương pháp Liên kết trong Phân cụm Gom cụm","summary":["Khoảng cách giữa các cụm trong phân cụm gom cụm (Agglomerative) được xác định thông qua các phương pháp liên kết (linkage methods). Các thước đo tiêu biểu bao gồm Single-Link (khoảng cách giữa hai điểm gần nhất, dễ bị hiệu ứng dây chuyền chaining effect), Complete-Link (khoảng cách giữa hai điểm xa nhất, tạo cụm nén chặt nhưng nhạy cảm với ngoại lệ), Average-Link (trung bình cộng khoảng cách mọi cặp điểm), và Ward's method (đo độ gia tăng tổng bình phương sai số SSE khi gộp cụm). So với Single-Link dễ bị vô tình nối các cụm biệt lập do một vài điểm nhiễu rải rác, phương pháp Ward và Complete-Link tạo ra các cụm nén đồng nhất và được áp dụng phổ biến nhất trong thực tế."],"questions":[{"id":33,"text":"Sự khác biệt về mặt kỹ thuật giữa phương pháp Liên kết Đơn (Single-Link) và Liên kết Đầy đủ (Complete-Link) khi tính khoảng cách giữa hai cụm CA và CB là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Single-Link luôn tạo ra các cụm nén chặt hình tròn trong khi Complete-Link gây ra hiệu ứng dây chuyền."},{"k":"B","t":"Single-Link tính khoảng cách bằng độ dài ngắn nhất giữa hai điểm thuộc hai cụm: d(CA, CB) = min { d(x, y) }."},{"k":"C","t":"Complete-Link không bị ảnh hưởng bởi điểm ngoại lệ trong khi Single-Link rất nhạy cảm với ngoại lệ."},{"k":"D","t":"Complete-Link tính khoảng cách bằng độ dài lớn nhất giữa hai điểm thuộc hai cụm: d(CA, CB) = max { d(x, y) }."}],"answer":["B","D"]},{"id":34,"text":"Phương pháp liên kết Ward (Ward's method) trong phân cụm gom cụm đưa ra quyết định hợp nhất hai cụm dựa trên tiêu chí nào?","multiple":false,"options":[{"k":"A","t":"Tối đa hóa khoảng cách Euclid giữa hai trọng tâm cụm gần nhất."},{"k":"B","t":"Đếm số lượng điểm dữ liệu trùng lặp giữa hai cụm cần gộp."},{"k":"C","t":"Chọn hai cụm có khoảng cách giữa hai điểm xa nhất là nhỏ nhất."},{"k":"D","t":"Tối thiểu hóa sự gia tăng của tổng bình phương sai số SSE sau khi gộp hai cụm thành một."}],"answer":["D"]}]},{"id":18,"title":"Phương pháp Phân cụm dựa trên Mật độ và Thuật toán DBSCAN","summary":["Khác với các phương pháp phân vùng và phân cấp dựa trên khoảng cách hình học, phân cụm dựa trên mật độ (Density-based Clustering - tiêu biểu là DBSCAN) định nghĩa cụm là vùng không gian có mật độ điểm dữ liệu cao, được phân tách bởi các vùng mật độ thấp. Thuật toán phát triển cụm từ các điểm lõi thỏa mãn chứa tối thiểu MinPts điểm trong bán kính lân cận Eps, cho phép phát hiện các cụm có hình dạng bất kỳ (như hình dải xoắn hay vành khăn) và tự động lọc bỏ các điểm nhiễu/ngoại lệ cô lập. So với K-means vốn giả định cụm hình cầu và bắt buộc gán mọi điểm vào cụm, phương pháp dựa trên mật độ hoạt động bền vững hơn nhiều khi đối mặt với dữ liệu nhiễu và cấu trúc hình học phức tạp.","B. Bài tập tham khảo"],"questions":[{"id":35,"text":"Ưu điểm cốt lõi của thuật toán DBSCAN so với thuật toán K-means thể hiện ở những điểm nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bắt buộc gán tất cả mọi điểm dữ liệu vào một cụm duy nhất dù điểm đó ở rất xa."},{"k":"B","t":"Yêu cầu tính toán ma trận nghịch đảo của toàn bộ thuộc tính trước khi phân cụm."},{"k":"C","t":"Có khả năng phát hiện các cụm có hình dạng bất kỳ (phi cầu, hình vành khăn, dải xoắn phức tạp)."},{"k":"D","t":"Tự động nhận diện và lọc bỏ các điểm dữ liệu nhiễu/ngoại lệ không thỏa mãn điều kiện mật độ."}],"answer":["C","D"]},{"id":36,"text":"Hai tham số đầu vào quan trọng nhất điều khiển hoạt động phân cụm dựa trên mật độ trong DBSCAN là gì?","multiple":false,"options":[{"k":"A","t":"Số lượng cụm k và số vòng lặp tối đa MaxIter."},{"k":"B","t":"Tốc độ học (γt) và tốc độ quên (κ)."},{"k":"C","t":"Khoảng cách nội cụm a(i) và khoảng cách liên cụm b(i)."},{"k":"D","t":"Bán kính lân cận (Eps) và số lượng điểm tối thiểu trong vùng lân cận (MinPts)."}],"answer":["D"]}]}]},{"id":"l6-decision-tree","title":"L6 decision tree","summary":["Cây Quyết định (Decision Tree) là mô hình học có giám sát biểu diễn cấu trúc phân cấp để ánh xạ các thuộc tính đầu vào thành nhãn lớp dự đoán. Về cấu trúc logic, mỗi đường đi từ nút gốc đến nút lá tương ứng với một phép hội (AND) các điều kiện kiểm tra, và toàn bộ cây biểu diễn một tập luật IF-THEN dưới dạng phép tuyển (OR). Thuật toán học phổ biến như ID3 xây dựng cây theo chiến lược chia để trị từ trên xuống (top-down greedy search): tại mỗi nút, thuật toán chọn thuộc tính có độ tăng thông tin Gain(S, A) = Entropy(S) - Σ (|Sv| / |S| * Entropy(Sv)) lớn nhất để rẽ nhánh, trong đó Entropy(S) = - Σ (pi * log2(pi)) đo lường độ hỗn tạp của dữ liệu. Nhờ cơ chế chọn nút tham lam này, các thuộc tính có khả năng phân biệt tốt nhất luôn được ưu tiên đưa lên gần nút gốc.","Dù có tính giải thích trực quan cao, cây quyết định đơn lẻ rất dễ gặp hiện tượng quá khớp (overfitting) do mọc cây quá sâu để khớp các điểm nhiễu, buộc phải áp dụng các kỹ thuật cắt tỉa (pruning) hoặc chuẩn hóa bằng chỉ số Gain Ratio. Thuật toán Rừng Ngẫu nhiên (Random Forest - Breiman, 2001) giải quyết triệt để rào cản này bằng phương pháp học kết hợp (Ensemble Learning) dựa trên cơ chế ngẫu nhiên hóa kép. Thứ nhất, kỹ thuật Bagging (Bootstrapping) sinh ra K tập dữ liệu con bằng cách rút mẫu ngẫu nhiên có hoàn trả n mẫu từ tập gốc, tạo ra tập Out-Of-Bag (OOB ~36.8%) làm tập kiểm chứng tự nhiên. Thứ hai, tại mỗi nút rẽ nhánh, thuật toán ngẫu nhiên chọn một tập con m = √d thuộc tính để tìm vị trí rẽ nhánh tối ưu, đồng thời cho phép mỗi cây mọc tối đa mà không cắt tỉa.","Về bản chất kỹ thuật, sức mạnh của Random Forest dựa trên nguyên lý \"trí tuệ tập thể\": kết hợp phán đoán của K cây quyết định không tương quan bằng cơ chế bầu chọn đa số (max-voting) cho bài toán phân loại hoặc tính trung bình cộng (averaging) cho bài toán hồi quy. Theo phân tích Bias-Variance trade-off, mặc dù từng cây cá thể có phương sai cao (high variance) do chỉ học trên một tập con dữ liệu, việc lấy trung bình phán đoán từ K cây độc lập giúp kéo phương sai tổng thể của mô hình xuống tiệm cận 0 mà không làm tăng độ lệch (bias). Đánh đổi lại cho khả năng chống quá khớp và độ chính xác vượt trội trên dữ liệu số chiều lớn này là việc mất đi tính giải thích trực quan minh bạch của các luật IF-THEN đơn lẻ, biến hệ thống thành một mô hình tập hợp phức tạp."],"topics":[{"id":1,"title":"Bài toán Phân loại và Dạng dữ liệu Thuộc tính","summary":["Bài toán phân loại (classification) trong học có giám sát hướng tới việc học một hàm phán đoán y* từ tập dữ liệu huấn luyện D = {(x1, y1), ..., (xM, yM)} để dự đoán nhãn lớp rời rạc y ∈ C cho các quan sát x = (x1, ..., xn)^T. Về mặt biểu diễn dữ liệu, các thuộc tính đầu vào thường thuộc dạng định danh/phạm trù (nominal/categorical) thể hiện các nhãn danh mục không chứa thứ tự tự nhiên (như Gender ∈ {male, female, other} hay Outlook ∈ {sunny, overcast, rain}). So với bài toán hồi quy (regression) vốn có không gian đầu ra Y là chuỗi giá trị số thực liên tục, bài toán phân loại tập trung gán mỗi mẫu quan sát vào đúng một nhãn lớp định trước."],"questions":[{"id":1,"text":"Trong một dự án phân tích dữ liệu y tế không có sẵn cấu trúc số học tuyến tính, đội ngũ phát triển quyết định xây dựng mô hình phân loại có giám sát. Đặc điểm nào sau đây thể hiện đúng bản chất của bài toán phân loại và cách biểu diễn thuộc tính trong ngữ cảnh này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Thuật toán học một hàm phán đoán dựa trên tập dữ liệu học có nhãn để gán mỗi mẫu quan sát vào một nhãn lớp rời rạc định trước."},{"k":"B","t":"Các thuộc tính dạng định danh (nominal/categorical) đại diện cho các nhóm danh mục không có thứ tự ưu tiên hay khoảng cách số học tự nhiên."},{"k":"C","t":"Thuộc tính dạng thứ tự (ordinal) cho phép thực hiện trực tiếp các phép toán cộng trừ nhân chia tọa độ như không gian Euclid."},{"k":"D","t":"Mục tiêu chính của mô hình phân loại là tự động phát hiện số lượng cụm mật độ tự nhiên mà không cần đến thông tin nhãn lớp."}],"answer":["A","B"]},{"id":2,"text":"Một chuyên viên dữ liệu chuẩn bị tập thuộc tính đầu vào cho mô hình phân loại dự đoán rủi ro tín dụng, bao gồm các thông tin: Giới tính, Trình độ học vấn (Trung học, Đại học, Sau đại học), và Thu nhập hàng tháng. Nhận định nào sau đây mô tả chính xác bản chất của các dạng thuộc tính này?","multiple":false,"options":[{"k":"A","t":"Cả ba thuộc tính trên đều thuộc dạng định danh không có thứ tự và có thể đo trực tiếp bằng khoảng cách Euclid."},{"k":"B","t":"Giới tính là thuộc tính định lượng số thực, trong khi Trình độ học vấn là thuộc tính định danh phân cấp không thể so sánh."},{"k":"C","t":"Giới tính thuộc dạng thuộc tính định danh, Trình độ học vấn là thuộc tính thứ tự, và Thu nhập là thuộc tính định lượng số thực."},{"k":"D","t":"Thu nhập hàng tháng thuộc dạng thuộc tính thứ tự không có giá trị đại số, trong khi Giới tính là thuộc tính liên tục."}],"answer":["C"]}]},{"id":2,"title":"Cây Quyết định và Biểu diễn Luật IF-THEN","summary":["Cây quyết định (Decision Tree) là mô hình phân cấp biểu diễn một hàm phán đoán, trong đó mỗi nút trong (internal node) kiểm tra một thuộc tính, mỗi nhánh đại diện cho một giá trị của thuộc tính đó, và mỗi nút lá (leaf node) chứa nhãn lớp dự đoán. Về mặt biểu diễn logic, mỗi đường đi từ nút gốc đến nút lá tương ứng với một phép hội (conjunction/AND) của các điều kiện kiểm tra thuộc tính, và toàn bộ cây quyết định biểu diễn một phép tuyển (disjunction/OR) của các phép hội đó dưới dạng tập các luật IF-THEN. So với các mô hình tuyến tính tham số đóng, cây quyết định cung cấp khả năng giải thích tri thức trực quan, giúp người dùng dễ dàng truy vết quy trình đưa ra quyết định."],"questions":[{"id":3,"text":"Cây quyết định (Decision Tree) được đánh giá là một mô hình biểu diễn tri thức trực quan có tính giải thích cao. Về mặt cấu trúc logic, hai đặc điểm nào sau đây thể hiện đúng cách cây quyết định biểu diễn hàm phán đoán? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Mỗi đường đi từ nút gốc đến nút lá biểu diễn một phép tuyển (OR) của các thuộc tính kiểm tra."},{"k":"B","t":"Mỗi đường đi từ nút gốc đến nút lá tương ứng với một phép hội (AND) các điều kiện kiểm tra thuộc tính."},{"k":"C","t":"Toàn bộ cây quyết định tương ứng với một luật phân loại đơn lẻ bao gồm phép hội tất cả các nút lá."},{"k":"D","t":"Toàn bộ cây quyết định biểu diễn một tập hợp các luật IF-THEN dưới dạng phép tuyển (OR) của các phép hội."}],"answer":["B","D"]},{"id":4,"text":"Khi đưa một mẫu dữ liệu mới có vectơ đặc trưng x đi qua một cây quyết định phân loại đã được huấn luyện hoàn chỉnh, quy trình dự đoán nhãn lớp diễn ra như thế nào?","multiple":false,"options":[{"k":"A","t":"Mẫu x bắt đầu kiểm tra tại nút gốc, đi xuống theo nhánh tương ứng với giá trị thuộc tính cho đến khi gặp nút lá và nhận nhãn tại lá đó."},{"k":"B","t":"Mẫu x được kiểm tra đồng thời tại tất cả các nút lá, sau đó tính trung bình cộng nhãn của toàn bộ các nút lá trên cây."},{"k":"C","t":"Mẫu x kiểm tra ngược từ các nút lá lên nút gốc và dừng lại ở nút trong đầu tiên có thuộc tính định danh thỏa mãn."},{"k":"D","t":"Mẫu x được chiếu lên không gian hai chiều và gán nhãn dựa vào khoảng cách ngắn nhất tới nút trong có chiều sâu lớn nhất."}],"answer":["A"]}]},{"id":3,"title":"Cơ chế Dự đoán và Xây dựng Cây Top-Down","summary":["Khi có một mẫu dữ liệu mới, mô hình thực hiện dự đoán nhãn bằng cách bắt đầu từ nút gốc, kiểm tra các thuộc tính để đi xuống theo các nhánh tương ứng cho đến khi chạm tới nút lá. Về mặt kỹ thuật, quy trình huấn luyện cây tuân theo chiến lược chia để trị từ trên xuống (top-down greedy scheme): tại mỗi nút, thuật toán chọn ra thuộc tính kiểm tra phân biệt tốt nhất để rẽ nhánh, tách tập dữ liệu thành các tập con và tiếp tục gọi đệ quy. Trong các thuật toán truyền thống như ID3, mỗi thuộc tính kiểm tra chỉ xuất hiện tối đa một lần trên bất kỳ đường đi nào từ gốc đến lá."],"questions":[{"id":5,"text":"Trong chiến lược chia để trị từ trên xuống (top-down greedy scheme) để xây dựng cây quyết định, những nguyên tắc rẽ nhánh nào sau đây được tuân thủ? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tại mỗi nút trong, thuật toán chọn ra thuộc tính kiểm tra có khả năng phân biệt dữ liệu tốt nhất để phân chia các mẫu vào các nút con."},{"k":"B","t":"Mỗi thuộc tính sau khi được chọn làm nút rẽ nhánh sẽ liên tục xuất hiện lặp lại ở tất cả các nút con tiếp theo trên cùng một nhánh."},{"k":"C","t":"Quá trình phát triển cây dừng lại tại một nút khi tất cả các mẫu dữ liệu gắn với nút đó thuộc về cùng một nhãn lớp thuần khiết."},{"k":"D","t":"Thuật toán tiến hành thử nghiệm tất cả các hoán vị cây có thể có để đảm bảo luôn chọn được cây có kích thước nhỏ nhất toàn cục."}],"answer":["A","C"]},{"id":6,"text":"Trong thuật toán xây dựng cây quyết định phân loại truyền thống cho thuộc tính rời rạc (như ID3), số lần tối đa một thuộc tính kiểm tra có thể xuất hiện trên một đường đi duy nhất từ gốc đến lá là bao nhiêu?","multiple":false,"options":[{"k":"A","t":"Không giới hạn số lần, phụ thuộc vào số lượng mẫu dữ liệu ở tập huấn luyện."},{"k":"B","t":"Tối đa bằng số lượng nhãn lớp xuất hiện ở tập dữ liệu đầu vào."},{"k":"C","t":"Tối đa hai lần, ứng với hai nhánh phân chia có Entropy nhỏ nhất."},{"k":"D","t":"Tối đa một lần duy nhất trên bất kỳ đường đi nào từ nút gốc đến nút lá."}],"answer":["D"]}]},{"id":4,"title":"Thuật toán ID3","summary":["Thuật toán ID3 (Iterative Dichotomiser 3), do Ross Quinlan phát minh năm 1986, là giải thuật học tham lam nền tảng xây dựng cây quyết định top-down dành riêng cho tập dữ liệu có các thuộc tính định danh. Kỹ thuật thực thi của ID3 liên tục chọn thuộc tính kiểm tra tốt nhất tại nút hiện tại dựa trên tiêu chuẩn Information Gain, phân chia dữ liệu vào các nhánh con và lặp lại đệ quy. Quá trình mọc cây dừng lại khi tất cả các mẫu dữ liệu tại nút thuộc về cùng một lớp nhãn c (thuần khiết tuyệt đối) hoặc khi toàn bộ tập thuộc tính khả dụng đã được sử dụng hết."],"questions":[{"id":7,"text":"Thuật toán ID3 (Iterative Dichotomiser 3) do Ross Quinlan đề xuất được thiết kế dựa trên các nguyên tắc thực thi kỹ thuật nào sau đây? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tự động chuyển đổi toàn bộ thuộc tính định danh sang dạng tọa độ liên tục trước khi chọn nút rẽ nhánh."},{"k":"B","t":"Sử dụng chiến lược tìm kiếm tham lam từ trên xuống để chọn thuộc tính kiểm tra tốt nhất tại từng nút."},{"k":"C","t":"Quá trình mọc cây đệ quy sẽ dừng lại nếu tập thuộc tính kiểm tra khả dụng tại nút đang xét đã được sử dụng hết."},{"k":"D","t":"Cho phép thuật toán quay lùi (backtrack) để hủy bỏ các nút rẽ nhánh ở gốc nếu phát hiện sai số ở các nút lá."}],"answer":["B","C"]},{"id":8,"text":"Giả sử tại một nút trong của cây ID3, tập dữ liệu huấn luyện S_node gồm 10 mẫu thuộc lớp Positive và 0 mẫu thuộc lớp Negative. Thuật toán ID3 sẽ xử lý nút này như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Ngừng đệ quy rẽ nhánh tại nút này và biến nó thành một nút lá được gán nhãn Positive."},{"k":"B","t":"Tiếp tục chọn thuộc tính kiểm tra tiếp theo để rẽ nhánh vì tập dữ liệu chưa hết thuộc tính."},{"k":"C","t":"Chuyển nút này thành nút gốc của một cây quyết định mới và gọi lại thuật toán từ đầu."},{"k":"D","t":"Nút này được xác định đạt độ thuần khiết tuyệt đối (purity) với giá trị Entropy bằng 0."}],"answer":["A","D"]}]},{"id":5,"title":"Thước đo Độ Hỗn tạp Entropy trong Lý thuyết Thông tin","summary":["Entropy là độ đo cốt lõi trong lý thuyết thông tin dùng để định lượng độ hỗn tạp hoặc mức độ không thuần khiết (impurity) của một tập dữ liệu S. Công thức Entropy với c lớp nhãn được định nghĩa là Entropy(S) = - ∑ (pi * log2(pi)), với pi là tỷ lệ các mẫu mang nhãn i trong S và quy ước 0 * log2(0) = 0. Về mặt ý nghĩa, Entropy biểu diễn số lượng bit trung bình cần thiết để mã hóa nhãn lớp của một mẫu, đồng thời đo lường mức độ không thể dự đoán của biến ngẫu nhiên. Nếu tập S chứa 14 mẫu gồm 9 mẫu Yes và 5 mẫu No, giá trị Entropy(S) tính ra xấp xỉ 0.94; nếu tập S hoàn toàn tinh khiết (100% cùng lớp), Entropy sẽ bằng 0."],"questions":[{"id":9,"text":"Cho một tập dữ liệu S gồm 16 mẫu quan sát thuộc hai lớp nhãn (C1 và C2). Xét hai trường hợp phân bố: Trường hợp I có 8 mẫu C1 và 8 mẫu C2; Trường hợp II có 16 mẫu C1 và 0 mẫu C2. Nhận định nào sau đây là chính xác về giá trị Entropy(S)? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Entropy(S) ở Trường hợp I bằng 0 do hai lớp có số lượng mẫu bằng nhau tuyệt đối."},{"k":"B","t":"Entropy(S) ở Trường hợp II bằng 1 do tập dữ liệu đạt kích thước tối đa 16 mẫu."},{"k":"C","t":"Entropy(S) ở Trường hợp I đạt giá trị cực đại bằng 1.0 do mức độ không thuần khiết cao nhất."},{"k":"D","t":"Entropy(S) ở Trường hợp II bằng 0 do tập dữ liệu hoàn toàn tinh khiết, 100% thuộc về lớp C1."}],"answer":["C","D"]},{"id":10,"text":"Cho một tập dữ liệu S gồm 8 mẫu Yes và 8 mẫu No. Công thức Entropy(S) = - p_Yes * log2(p_Yes) - p_No * log2(p_No) cho kết quả là bao nhiêu?","multiple":false,"options":[{"k":"A","t":"Entropy(S) = 0."},{"k":"B","t":"Entropy(S) = 1.0."},{"k":"C","t":"Entropy(S) = 0.5."},{"k":"D","t":"Entropy(S) = 0.94."}],"answer":["B"]}]},{"id":6,"title":"Mức giảm Entropy và Chỉ số Information Gain","summary":["Information Gain (độ tăng thông tin) đo lường mức giảm Entropy kỳ vọng khi tập dữ liệu S được phân chia theo các giá trị của thuộc tính A. Công thức tính là Gain(S, A) = Entropy(S) - ∑ (|Sv| / |S| * Entropy(Sv)), trong đó Sv là tập con các mẫu có thuộc tính A nhận giá trị v. Về mặt kỹ thuật, thuộc tính nào đem lại giá trị Gain lớn nhất sẽ làm giảm độ hỗn tạp nhiều nhất và được ưu tiên chọn làm nút kiểm tra. Ví dụ trong bài toán dự đoán chơi Tennis với 14 mẫu, thuộc tính Outlook có Gain(S, Outlook) = 0.246, cao hơn Humidity (0.151), Wind (0.048) và Temperature (0.029), do đó Outlook được chọn làm nút gốc."],"questions":[{"id":11,"text":"Giả sử tại nút gốc có tập dữ liệu S gồm 14 mẫu (9+, 5-) với Entropy(S) = 0.94. Người ta tính toán mức độ hiệu quả của hai thuộc tính A1 và A2 thu được: Gain(S, A1) = 0.246 và Gain(S, A2) = 0.048. Nhận định nào sau đây là đúng về kỹ thuật chọn nút rẽ nhánh? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Thuộc tính A1 đem lại lượng thông tin thu được lớn hơn và làm giảm độ hỗn tạp nhiều hơn so với A2."},{"k":"B","t":"Giá trị Gain(S, A1) cao hơn chứng tỏ việc phân chia theo A1 tạo ra các tập con có độ thuần khiết trung bình tốt hơn A2."},{"k":"C","t":"Thuật toán ID3 sẽ chọn A2 làm nút rẽ nhánh tại gốc vì thuộc tính có Gain nhỏ hơn giúp giảm độ sâu của cây."},{"k":"D","t":"Hai thuộc tính A1 và A2 bắt buộc phải được nhân tích độ lệch để tạo thành một tiêu chuẩn chọn nút hợp nhất."}],"answer":["A","B"]},{"id":12,"text":"Cho tập S gồm 8 mẫu (4+, 4-) có Entropy(S) = 1.0. Xét thuộc tính B có 2 giá trị {v1, v2}. Phân chia theo B thu được hai tập con: S_v1 có 4 mẫu (4+, 0-) và S_v2 có 4 mẫu (0+, 4-). Giá trị Information Gain(S, B) và thuộc tính của phép phân chia này là bao nhiêu? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Gain(S, B) = 0."},{"k":"B","t":"Gain(S, B) = 0.5."},{"k":"C","t":"Gain(S, B) = 1.0."},{"k":"D","t":"Thành phần Entropy kỳ vọng sau khi chia theo B bằng 0 do cả hai tập con đều hoàn toàn tinh khiết."}],"answer":["C","D"]}]},{"id":7,"title":"Chiến lược Tìm kiếm Tham lam và Thiên vị Học tập của ID3","summary":["Chiến lược tìm kiếm của ID3 hướng tới việc tìm kiếm một cây quyết định khớp tốt với dữ liệu huấn luyện thông qua việc phát triển cây từng bước. Về mặt kỹ thuật, ID3 là một giải thuật tham lam, không bao giờ thực hiện quay lùi (no backtracking) để đánh giá lại các thuộc tính đã chọn, dẫn đến việc chỉ đảm bảo tìm thấy một nghiệm tối ưu cục bộ. Thiên vị học tập (inductive bias) của ID3 ưu tiên các cây quyết định đơn giản (chiều cao cây thấp) và đặt các thuộc tính có Information Gain lớn nằm gần nút gốc."],"questions":[{"id":13,"text":"Chiến lược tìm kiếm không gian cây quyết định của thuật toán ID3 mang những đặc điểm kỹ thuật và thiên vị học tập (inductive bias) nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Là giải thuật tìm kiếm tham lam (greedy search) tuyệt đối không thực hiện quay lùi (no backtracking) để đánh giá lại các thuộc tính đã chọn."},{"k":"B","t":"Thiên vị học tập của ID3 ưu tiên các cây quyết định có cấu trúc đơn giản, chiều cao thấp hơn so với các cây phức tạp."},{"k":"C","t":"Luôn đảm bảo tìm thấy giải pháp cây quyết định tối ưu toàn cục (globally optimal tree) cho mọi tập dữ liệu."},{"k":"D","t":"Đặt các thuộc tính có giá trị Information Gain nhỏ ở vị trí gần nút gốc để kéo dài chiều sâu tìm kiếm."}],"answer":["A","B"]},{"id":14,"text":"Hậu quả trực tiếp của việc thuật toán ID3 không bao giờ thực hiện quay lùi (no backtracking) trong quá trình phát triển cây là gì?","multiple":false,"options":[{"k":"A","t":"Thuật toán luôn bị rơi vào lặp vô tận khi tập dữ liệu có chứa thuộc tính dạng số thực liên tục."},{"k":"B","t":"Thuật toán bắt buộc phải thử tất cả các hoán vị của tập thuộc tính trước khi đưa ra kết quả."},{"k":"C","t":"ID3 chỉ đảm bảo tìm thấy giải pháp tối ưu cục bộ (locally optimal tree) thay vì tối ưu toàn cục."},{"k":"D","t":"Kích thước cây sinh ra luôn là cây nhị phân hoàn hảo có số nút lá đúng bằng số thuộc tính."}],"answer":["C"]}]},{"id":8,"title":"Vấn đề Quá khớp (Overfitting) trong Cây Quyết định","summary":["Mặc dù cây quyết định có thể phát triển cho đến khi phân loại chính xác 100% dữ liệu huấn luyện, mô hình rất dễ gặp rủi ro quá khớp (overfitting). Về chi tiết kỹ thuật, khi dữ liệu huấn luyện chứa nhiễu (noise) hoặc lỗi gán nhãn, ID3 bị dẫn dắt sai hướng và tiếp tục tạo ra nhiều phân nhánh phức tạp chỉ để khớp các điểm nhiễu cô lập. Đồ thị thực nghiệm chứng minh rằng khi kích thước cây (số nút) tiếp tục tăng, độ chính xác trên tập huấn luyện vẫn gia tăng nhưng độ chính xác trên tập kiểm thử (test data) lại bị sụt giảm nghiêm trọng."],"questions":[{"id":15,"text":"Hiện tượng quá khớp (overfitting) là một thách thức nghiêm trọng khi huấn luyện cây quyết định. Những nguyên nhân và biểu hiện kỹ thuật nào sau đây mô tả đúng hiện tượng này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Quá khớp xảy ra khi cây quyết định ngừng mọc quá sớm lúc dữ liệu huấn luyện chưa đạt độ tinh khiết."},{"k":"B","t":"Dữ liệu huấn luyện chứa nhiễu, lỗi gán nhãn hoặc ngoại lệ dẫn dắt ID3 tạo ra các phân nhánh phức tạp cô lập."},{"k":"C","t":"Cây quyết định bị quá khớp luôn có cấu trúc quá nông với chiều sâu bằng 1 nên không học được mô hình."},{"k":"D","t":"Đồ thị thể hiện khi số nút cây tiếp tục tăng, độ chính xác trên tập huấn luyện vẫn gia tăng nhưng độ chính xác trên tập kiểm thử bị giảm mạnh."}],"answer":["B","D"]},{"id":16,"text":"Khi quan sát đồ thị biểu diễn mối quan hệ giữa kích thước cây quyết định (số nút) và độ chính xác phân loại, dấu hiệu nào khẳng định mô hình bắt đầu bị quá khớp?","multiple":false,"options":[{"k":"A","t":"Độ chính xác trên tập huấn luyện giảm dần trong khi độ chính xác trên tập kiểm thử tăng liên tục."},{"k":"B","t":"Độ chính xác trên tập huấn luyện tiến gần 100% nhưng độ chính xác trên tập kiểm chứng/kiểm thử bắt đầu giảm đi."},{"k":"C","t":"Cả độ chính xác trên tập huấn luyện và tập kiểm thử đều đi ngang và giữ nguyên ở mức rất thấp."},{"k":"D","t":"Số lượng thuộc tính bị loại bỏ khỏi cây vượt quá 90% tổng số thuộc tính đầu vào."}],"answer":["B"]}]},{"id":9,"title":"Các Giải pháp Tránh Quá khớp: Ngừng học Sớm và Cắt tỉa Cây","summary":["Để ngăn ngừa quá khớp, hai chiến lược kỹ thuật chính được triển khai là ngừng học sớm (pre-pruning) và cắt tỉa sau (post-pruning). Ngừng học sớm can thiệp trong lúc mọc cây bằng cách dừng phân nhánh nếu nút đạt Entropy = 0, số mẫu nhỏ hơn ngưỡng, chiều sâu đạt giới hạn, hoặc Gain quá nhỏ. Ngược lại, cắt tỉa sau cho phép cây phát triển tối đa rồi tiến hành loại bỏ các nút con không hiệu quả dựa trên tập kiểm chứng (validation set / reduced-error pruning) hoặc cộng thêm hệ số phạt độ phức tạp vào hàm mất mát."],"questions":[{"id":17,"text":"Hai chiến lược kỹ thuật chính được triển khai để giải quyết hiện tượng quá khớp trong cây quyết định là ngừng học sớm (pre-pruning) và cắt tỉa sau (post-pruning). Đặc điểm của hai phương pháp này bao gồm: (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Ngừng học sớm can thiệp trong quá trình mọc cây bằng cách dừng rẽ nhánh nếu Gain nhỏ hơn ngưỡng hoặc số mẫu ở nút quá ít."},{"k":"B","t":"Cắt tỉa sau bắt buộc phải xóa toàn bộ nút gốc và huấn luyện lại một cây mới hoàn toàn từ tập dữ liệu kiểm chứng."},{"k":"C","t":"Cắt tỉa sau (post-pruning) cho phép cây phát triển tối đa rồi mới tiến hành loại bỏ các nút con kém hiệu quả từ dưới lên."},{"k":"D","t":"Ngừng học sớm luôn mang lại kết quả thực tế tốt hơn cắt tỉa sau do xác định chính xác thời điểm dừng học tối ưu."}],"answer":["A","C"]},{"id":18,"text":"Kỹ thuật cắt tỉa cây giảm lỗi (reduced-error pruning) sử dụng tập dữ liệu kiểm chứng (validation set) như thế nào để cải thiện khả năng tổng quát hóa của cây? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bắt buộc phải thay thế toàn bộ dữ liệu kiểm chứng vào tập huấn luyện gốc trước khi cắt tỉa."},{"k":"B","t":"Tiến hành đánh giá khả năng tổng quát hóa của các nút rẽ nhánh dựa trên hiệu năng đo được trên tập kiểm chứng độc lập."},{"k":"C","t":"Chỉ cắt tỉa các nút lá có Entropy bằng 0 và giữ lại tất cả các nút có độ hỗn tạp lớn trên tập huấn luyện."},{"k":"D","t":"Thực hiện cắt tỉa đệ quy từ dưới lên cho đến khi việc loại bỏ thêm nút con sẽ làm sụt giảm độ chính xác trên tập kiểm chứng."}],"answer":["B","D"]}]},{"id":10,"title":"Xử lý Thuộc tính Nhiều Giá trị và Chỉ số Gain Ratio","summary":["Tiêu chuẩn Information Gain truyền thống gặp nhược điểm lớn là luôn thiên vị các thuộc tính có nhiều giá trị duy nhất (như thuộc tính Day, ID hay số tài khoản). Về mặt kỹ thuật, một thuộc tính có vô số giá trị riêng biệt sẽ chia tập học thành nhiều tập con kích thước 1 mẫu có Entropy = 0, đạt Gain cực đại và bị chọn làm nút gốc, tạo ra cây có chiều cao bằng 1 nhưng rất rộng và khả năng tổng quát hóa kém. Để khắc phục, độ đo Gain Ratio chuẩn hóa Gain qua đại lượng SplitInformation: GainRatio(S, A) = Gain(S, A) / SplitInformation(S, A), giúp phạt nặng các thuộc tính sinh ra quá nhiều nhánh rẽ."],"questions":[{"id":19,"text":"Nhược điểm lớn nhất của chỉ số Information Gain truyền thống khi gặp thuộc tính có quá nhiều giá trị duy nhất (như thuộc tính Mã định danh ID, Day, hay Số tài khoản) và cách giải quyết bằng Gain Ratio thể hiện ở những điểm nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Information Gain thiên vị các thuộc tính có nhiều giá trị vì chúng tạo ra các tập con có kích thước bằng 1 với Entropy = 0, đạt Gain cực đại."},{"k":"B","t":"Thuộc tính có vô số giá trị duy nhất luôn bị chỉ số Information Gain xếp ở vị trí nút lá có chiều sâu lớn nhất."},{"k":"C","t":"Gain Ratio chuẩn hóa Gain bằng cách chia cho đại lượng SplitInformation nhằm tăng điểm số cho các thuộc tính có nhiều phân nhánh."},{"k":"D","t":"Chỉ số Gain Ratio phạt nặng các thuộc tính sinh ra quá nhiều nhánh rẽ bằng đại lượng SplitInformation ở mẫu số."}],"answer":["A","D"]},{"id":20,"text":"Công thức GainRatio(S, A) = Gain(S, A) / SplitInformation(S, A) được áp dụng nhằm khắc phục thiên vị học tập nào của thuật toán ID3?","multiple":false,"options":[{"k":"A","t":"Khắc phục sự thiên vị ưu tiên các thuộc tính có quá nhiều giá trị phân nhánh độc lập."},{"k":"B","t":"Khắc phục hiện tượng cây quyết định bị dừng mọc quá sớm khi tập dữ liệu có kích thước lớn."},{"k":"C","t":"Khắc phục hạn chế không thể tính toán được Entropy khi tập dữ liệu chứa nhãn lớp nhị phân."},{"k":"D","t":"Khắc phục việc mô hình không thể thực hiện dự đoán trên các thuộc tính dạng định danh."}],"answer":["A"]}]},{"id":11,"title":"Xử lý Thuộc tính Số thực Liên tục (Discretization)","summary":["Đối với các tập dữ liệu chứa thuộc tính số thực liên tục (real attributes), ID3 áp dụng kỹ thuật rời rạc hóa (discretization) để chuyển đổi miền giá trị liên tục thành các thuộc tính định danh. Kỹ thuật này tiến hành chia miền giá trị liên tục thành một tập các khoảng (intervals) không giao nhau có số mẫu tương đương hoặc dùng phân cụm đơn giản. Nhược điểm kỹ thuật của phương pháp này là nếu một mẫu dữ liệu mới nằm sát ranh giới phân khoảng, sự biến động nhẹ ở đầu vào có thể làm mẫu rơi nhầm sang nhánh khác, dẫn đến sai lệch lớn ở kết quả phán đoán cuối cùng."],"questions":[{"id":21,"text":"Để áp dụng thuật toán cây quyết định dạng ID3 cho các thuộc tính có miền giá trị số thực liên tục (như Nhiệt độ = 23.5, 31.2...), kỹ thuật rời rạc hóa (discretization) và những rủi ro đi kèm bao gồm: (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Rời rạc hóa bằng cách chia toàn bộ dữ liệu liên tục thành vô số khoảng có kích thước bằng 0 để giữ nguyên độ chính xác."},{"k":"B","t":"Chuyển đổi thuộc tính liên tục thành thuộc tính định danh bằng cách chia miền giá trị thành các khoảng (intervals) không giao nhau."},{"k":"C","t":"Nhược điểm kỹ thuật là nếu mẫu dữ liệu nằm sát ranh giới phân khoảng, sự nhiễu nhẹ ở đầu vào cũng làm mẫu rơi nhầm sang nhánh khác."},{"k":"D","t":"Kỹ thuật rời rạc hóa luôn đảm bảo loại bỏ hoàn toàn hiện tượng quá khớp mà không làm mất mát thông tin dữ liệu."}],"answer":["B","C"]},{"id":22,"text":"Một nhà phân tích dữ liệu áp dụng phương pháp chia khoảng (interval splitting) để rời rạc hóa thuộc tính \"Thu nhập hàng tháng\" thành 4 khoảng giá trị. Nhược điểm tiềm ẩn lớn nhất của cách làm này là gì?","multiple":false,"options":[{"k":"A","t":"Thuật toán ID3 sẽ hoàn toàn từ chối thực thi trên thuộc tính đã được rời rạc hóa."},{"k":"B","t":"Sự nhạy cảm tại ranh giới phân khoảng có thể khiến một biến động nhỏ ở đầu vào làm thay đổi hoàn toàn nhánh rẽ dự đoán."},{"k":"C","t":"Khoảng giá trị làm cho Entropy của toàn bộ tập dữ liệu huấn luyện tự động gia tăng lên mức cực đại bằng 10."},{"k":"D","t":"Thuộc tính sau khi rời rạc hóa bắt buộc phải được chuyển đổi thành bài toán phân cụm không giám sát."}],"answer":["B"]}]},{"id":12,"title":"Xử lý Giá trị Thiếu (Missing Values)","summary":["Hiện tượng thiếu giá trị (missing values) ở các thuộc tính quan sát là một vấn đề tự nhiên và phổ biến trong dữ liệu thực tế. Trong quá trình học cây quyết định, khi mẫu x bị thiếu giá trị xA tại thuộc tính A, hai giải pháp điền giá trị được áp dụng: (1) điền xA bằng giá trị xuất hiện phổ biến nhất (mode) của thuộc tính A trên toàn bộ tập huấn luyện; (2) điền xA bằng giá trị xuất hiện phổ biến nhất của A trong số các mẫu thuộc cùng lớp nhãn với x. Quy trình tự động này giúp mô hình tận dụng triệt để dữ liệu không hoàn chỉnh mà không cần loại bỏ mẫu."],"questions":[{"id":23,"text":"Trong thực tế, một mẫu dữ liệu x có thể bị thiếu giá trị xA tại thuộc tính A. Hai giải pháp kỹ thuật điền giá trị thiếu thường được tích hợp trực tiếp trong thuật toán mọc cây quyết định bao gồm: (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Điền xA bằng giá trị xuất hiện phổ biến nhất (mode) của thuộc tính A trên toàn bộ tập dữ liệu huấn luyện."},{"k":"B","t":"Loại bỏ ngay lập tức thuật toán cây quyết định và chuyển sang mô hình học không giám sát."},{"k":"C","t":"Nhân tất cả các thuộc tính khác với giá trị 0 để triệt tiêu ảnh hưởng của giá trị bị thiếu."},{"k":"D","t":"Điền xA bằng giá trị xuất hiện phổ biến nhất của thuộc tính A tính riêng trên nhóm các mẫu có cùng nhãn lớp với x."}],"answer":["A","D"]},{"id":24,"text":"Lợi ích kỹ thuật lớn nhất của việc tích hợp cơ chế tự động xử lý giá trị thiếu trực tiếp trong cây quyết định là gì?","multiple":false,"options":[{"k":"A","t":"Giúp biến tất cả các thuộc tính định danh thành thuộc tính số thực liên tục mà không cần chia khoảng."},{"k":"B","t":"Đảm bảo cây quyết định thu được luôn có chiều cao tối đa bằng 1."},{"k":"C","t":"Làm cho giá trị Entropy của tất cả các nút con tự động triệt tiêu về 0."},{"k":"D","t":"Tận dụng tối đa các bản ghi dữ liệu không hoàn chỉnh mà không cần loại bỏ mẫu hay tiền xử lý thủ công."}],"answer":["D"]}]},{"id":13,"title":"Ý tưởng Cốt lõi của Rừng Ngẫu nhiên (Random Forests)","summary":["Rừng ngẫu nhiên (Random Forests - do Leo Breiman đề xuất năm 2001) là phương pháp học kết hợp (ensemble learning) giải quyết cả bài toán phân loại và hồi quy bằng cách tổng hợp phán đoán từ một tập hợp nhiều cây quyết định. Ý tưởng cốt lõi của thuật toán là kết hợp dự đoán từ K cây quyết định độc lập bằng cách lấy trung bình cộng đối với bài toán hồi quy hoặc bầu chọn đa số đối với bài toán phân loại. Mặc dù từng cây quyết định cá thể có thể bị kém khớp hay có độ lệch cao (high bias) do chỉ học trên tập dữ liệu con, sự tổng hợp tri thức từ nhiều cây giúp các thông tin bổ sung cho nhau, làm giảm phương sai tổng thể và đem lại độ chính xác vượt trội."],"questions":[{"id":25,"text":"Thuật toán Rừng ngẫu nhiên (Random Forests - Breiman, 2001) dựa trên phương pháp học kết hợp (ensemble learning). Hai nguyên lý cốt lõi cấu thành nên mô hình này bao gồm: (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Xây dựng một mô hình cây quyết định đơn lẻ duy nhất nhưng huấn luyện qua hàng nghìn vòng lặp liên tiếp."},{"k":"B","t":"Dự đoán cuối cùng dựa trên sự kết hợp kết quả từ một tập hợp gồm nhiều cây quyết định cá thể độc lập."},{"k":"C","t":"Áp dụng cơ chế lấy trung bình cộng đối với bài toán hồi quy hoặc bầu chọn đa số đối với bài toán phân loại."},{"k":"D","t":"Bắt buộc tất cả các cây trong rừng phải sử dụng chung một tập thuộc tính rẽ nhánh hoàn toàn giống nhau."}],"answer":["B","C"]},{"id":26,"text":"Vì sao sự kết hợp phán đoán từ một tập hợp gồm K cây quyết định ngẫu nhiên trong Random Forests lại đạt độ chính xác cao hơn một cây quyết định đơn lẻ? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Sự tổng hợp tri thức từ nhiều cây ngẫu nhiên giúp các phán đoán bổ sung thông tin và sửa lỗi cho nhau."},{"k":"B","t":"Mỗi cây quyết định đơn lẻ trong rừng luôn đảm bảo đạt độ chính xác 100% trên tập dữ liệu mới."},{"k":"C","t":"Rừng ngẫu nhiên biến tất cả các bài toán phân loại phức tạp thành mô hình hồi quy tuyến tính đơn giản."},{"k":"D","t":"Việc lấy trung bình hoặc bầu chọn đa số từ tập hợp các cây đa dạng giúp làm giảm phương sai (variance) tổng thể."}],"answer":["A","D"]}]},{"id":14,"title":"Kỹ thuật Lấy mẫu Bootstrapping và Bagging","summary":["Để các cây trong rừng không bị trùng lặp cấu trúc, Random Forests áp dụng kỹ thuật Bagging (Bootstrap Aggregating) để sinh ra K tập dữ liệu huấn luyện con Di từ tập gốc D. Về mặt kỹ thuật, mỗi tập Di được tạo ra bằng phương pháp Bootstrapping – lấy mẫu ngẫu nhiên có hoàn trả (sampling with replacement) n mẫu từ tập D. Do cơ chế rút có hoàn trả, mỗi tập Di chỉ chứa khoảng 63.2% số mẫu duy nhất từ D, còn 36.8% số mẫu không được rút trúng gọi là tập Out-Of-Bag (OOB). Tập OOB đóng vai trò như tập kiểm chứng tự nhiên giúp đánh giá độ chính xác của từng cây mà không cần dữ liệu test riêng biệt."],"questions":[{"id":27,"text":"Kỹ thuật Bagging (Bootstrap Aggregating) sử dụng phương pháp lấy mẫu Bootstrapping để huấn luyện các cây trong Random Forest như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Áp dụng cơ chế lấy mẫu ngẫu nhiên không hoàn trả để đảm bảo tất cả các mẫu dữ liệu xuất hiện đúng 1 lần."},{"k":"B","t":"Mỗi tập huấn luyện Di được tạo bằng cách rút ngẫu nhiên có hoàn trả (sampling with replacement) n mẫu từ tập gốc D."},{"k":"C","t":"Tất cả K tập dữ liệu con Di đều chứa 100% số lượng mẫu dữ liệu giống hệt nhau từ tập gốc D."},{"k":"D","t":"Tỷ lệ khoảng 36.8% mẫu dữ liệu không xuất hiện trong Di (gọi là mẫu Out-Of-Bag - OOB) đóng vai trò làm tập kiểm chứng tự nhiên."}],"answer":["B","D"]},{"id":28,"text":"Tệp mẫu Out-Of-Bag (OOB) sinh ra từ quá trình Bootstrapping mang lại giá trị kỹ thuật gì cho mô hình Random Forest? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Được sử dụng như một tập kiểm chứng (validation set) tự nhiên để đánh giá hiệu năng của từng cây mà không cần chia tập test riêng."},{"k":"B","t":"Bắt buộc phải được bổ sung thêm vào nút gốc của cây để gia tăng số lượng thuộc tính kiểm tra."},{"k":"C","t":"Cho phép ước lượng sai số tổng quát hóa (generalization error) của toàn bộ mô hình một cách khách quan."},{"k":"D","t":"Được sử dụng để tính toán ma trận khoảng cách Euclid giữa các cây quyết định trong rừng."}],"answer":["A","C"]}]},{"id":15,"title":"Kỹ thuật Ngẫu nhiên hóa Thuộc tính và Phát triển Cây Tối đa","summary":["Để triệt tiêu sự tương quan giữa các cây do thuộc tính mạnh nhất luôn bị chọn ở gốc, Random Forests bổ sung cơ chế ngẫu nhiên hóa thuộc tính (attribute randomization). Tại mỗi nút trong quá trình mọc cây, thuật toán chọn ngẫu nhiên một tập con S gồm m thuộc tính (thường chọn m = √d cho phân loại) và chỉ tìm thuộc tính rẽ nhánh tối ưu trong tập S này. Sau đó, mỗi cây được cho phép phát triển đến kích thước lớn nhất mà không thực hiện cắt tỉa (no pruning). Yếu tố ngẫu nhiên kép này giúp tạo ra tập hợp K cây hoàn toàn đa dạng về cấu trúc."],"questions":[{"id":29,"text":"Trong thuật toán Random Forest, cơ chế ngẫu nhiên hóa thuộc tính (attribute randomization) tại từng nút và quy trình mọc cây được thực hiện ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tại mỗi nút, thuật toán chọn ngẫu nhiên một tập con S gồm m thuộc tính và chỉ tìm thuộc tính rẽ nhánh tốt nhất trong tập S này."},{"k":"B","t":"Mỗi cây quyết định cá thể trong rừng được cho phép phát triển đến kích thước lớn nhất mà không thực hiện cắt tỉa (no pruning)."},{"k":"C","t":"Việc ngẫu nhiên hóa thuộc tính bắt buộc tất cả các nút rẽ nhánh ở mọi cây phải sử dụng chung thuộc tính có Gain lớn nhất."},{"k":"D","t":"Cây quyết định trong rừng bắt buộc phải bị cắt tỉa sớm (pre-pruned) để chiều sâu cây không vượt quá 2 tầng."}],"answer":["A","B"]},{"id":30,"text":"Vì sao Random Forest lại kết hợp hai yếu tố: \"Ngẫu nhiên hóa thuộc tính tại từng nút\" và \"Cho cây mọc tối đa không cắt tỉa\"? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Để triệt tiêu hoàn toàn khả năng tính toán của thuật toán trên các tập dữ liệu có số chiều lớn."},{"k":"B","t":"Để đảm bảo tất cả các cây trong rừng đều bị gò ép mọc theo một cấu trúc hình học cố định."},{"k":"C","t":"Giảm sự tương quan (correlation) giữa các cây, tạo nên cấu trúc cây đa dạng để các cây bổ sung tri thức cho nhau."},{"k":"D","t":"Mặc dù từng cây mọc tối đa không cắt tỉa có phương sai cao, sự kết hợp tập hợp cây đa dạng giúp giảm phương sai tổng thể."}],"answer":["C","D"]}]},{"id":16,"title":"Cơ chế Kết hợp Kết quả (Combination) và Phân tích Bias-Variance","summary":["Bước Combination thực hiện tổng hợp phán đoán từ K cây quyết định cá thể để đưa ra kết quả cuối cùng cho mẫu dữ liệu mới. Trong bài toán phân loại, mô hình áp dụng cơ chế bầu chọn đa số (max-voting); trong bài toán hồi quy, mô hình tính trung bình cộng (averaging) các giá trị dự đoán từ K cây. Theo phân tích Bias-Variance trade-off, việc lấy trung bình phán đoán từ nhiều cây độc lập giúp làm giảm đáng kể phương sai (variance) của toàn bộ mô hình xuống gần 0 mà không làm tăng độ lệch (bias), giúp Random Forests chống quá khớp cực kỳ hiệu quả."],"questions":[{"id":31,"text":"Khi thực hiện kết hợp kết quả (combination) trong Random Forest, cơ chế bầu chọn/tính trung bình hoạt động thế nào và tác động ra sao đến Bias-Variance trade-off? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bài toán phân loại sử dụng trung bình cộng trọng số, trong khi bài toán hồi quy sử dụng bầu chọn đa số tuyệt đối."},{"k":"B","t":"Bài toán phân loại áp dụng cơ chế bầu chọn đa số (max-voting), bài toán hồi quy áp dụng lấy trung bình cộng (averaging)."},{"k":"C","t":"Việc lấy trung bình phán đoán từ K cây độc lập giúp giảm đáng kể phương sai (variance) mà không làm tăng độ lệch (bias)."},{"k":"D","t":"Cơ chế kết hợp kết quả làm tăng độ lệch (bias) của toàn bộ mô hình lên gấp K lần so với cây đơn lẻ."}],"answer":["B","C"]},{"id":32,"text":"Phân tích lý thuyết về Bias-Variance trade-off cho thấy ưu điểm vượt trội nào của mô hình Rừng ngẫu nhiên (Random Forest) so với một Cây quyết định đơn lẻ (Decision Tree)?","multiple":false,"options":[{"k":"A","t":"Random Forest làm giảm mạnh phương sai (variance) của mô hình xuống gần 0, giúp chống quá khớp cực kỳ hiệu quả."},{"k":"B","t":"Random Forest làm tăng phương sai lên mức tối đa để mô hình khớp hoàn toàn với dữ liệu nhiễu."},{"k":"C","t":"Random Forest chuyển đổi bài toán phân loại có giám sát thành mô hình phân cụm không giám sát."},{"k":"D","t":"Random Forest triệt tiêu hoàn toàn thuộc tính đầu vào và chỉ dự đoán dựa trên hằng số cố định."}],"answer":["A"]}]},{"id":17,"title":"Hiệu năng Thực tế và Ưu điểm của Random Forests","summary":["Random Forests hiện là một trong những thuật toán học máy phổ biến và đạt độ chính xác cao nhất trong thực tế. Đánh giá thực nghiệm của Fernández-Delgado et al. (2014) trên 55 bài toán phân loại thực tế khẳng định hiệu năng vượt trội và tính tổng quát cao của phương pháp này. Về mặt kỹ thuật, Random Forests triển khai dễ dàng, xử lý hiệu quả các tập dữ liệu có số chiều rất lớn mà không bị quá khớp, đồng thời có thể chạy song song hóa cực kỳ hiệu quả trên các hệ thống tính toán hiện đại.","B. Bài tập tham khảo"],"questions":[{"id":33,"text":"Theo đánh giá thực nghiệm toàn diện của Fernández-Delgado et al. (2014) trên 55 bài toán phân loại thực tế, Random Forest khẳng định những ưu điểm nổi bật nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Là một trong những thuật toán học máy phổ biến, đạt độ chính xác cao nhất và có tính tổng quát hóa rất tốt."},{"k":"B","t":"Xử lý hiệu quả các tập dữ liệu có số chiều rất lớn (high dimensions) mà không bị quá khớp."},{"k":"C","t":"Không thể thực hiện tính toán song song do các cây quyết định bắt buộc phải học nối tiếp nhau."},{"k":"D","t":"Mô hình Random Forest có tính giải thích trực quan và dễ truy vết quy tắc hơn một cây quyết định đơn lẻ."}],"answer":["A","B"]},{"id":34,"text":"Nhược điểm kỹ thuật đáng chú ý nhất của mô hình Rừng ngẫu nhiên (Random Forest) khi so sánh với một Cây quyết định đơn lẻ (Decision Tree) là gì?","multiple":false,"options":[{"k":"A","t":"Random Forest có độ chính xác dự đoán luôn thấp hơn một cây quyết định đơn lẻ trên mọi tập dữ liệu."},{"k":"B","t":"Random Forest không thể áp dụng được cho các bài toán phân loại có chứa thuộc tính định danh."},{"k":"C","t":"Mất đi tính giải thích trực quan và khả năng truy vết luật IF-THEN đơn giản do cấu trúc gồm nhiều cây phức tạp."},{"k":"D","t":"Chi phí bộ nhớ và thời gian tính toán của Random Forest luôn nhỏ hơn một cây quyết định đơn lẻ."}],"answer":["C"]}]}]},{"id":"l7-neural-network","title":"L7 neural network","summary":["Mạng Nơ-ron Nhân tạo (ANN) xuất phát từ ý tưởng mô phỏng mạng lưới thần kinh sinh học, nhằm xây dựng một mô hình xử lý thông tin phân tán có khả năng tự học và xấp xỉ các hàm phi tuyến phức tạp từ dữ liệu. Đơn vị tính toán nền tảng là nơ-ron nhân tạo: tiếp nhận các tín hiệu đầu vào xi mang trọng số wi, kết hợp cùng tham số bias w0 để tính tổng Net = w0 + Σ(wi * xi), rồi đi qua một hàm kích hoạt phi tuyến f(·) để sinh đầu ra. Việc kết nối các nơ-ron thành cấu trúc đa tầng (Multi-layer) giúp mô hình vượt qua giới hạn của Perceptron đơn tầng vốn chỉ phân tách được dữ liệu tuyến tính, từ đó dựng nên các đường biên quyết định phi tuyến phức tạp trong không gian nhiều chiều.","Về quy trình vận hành, quá trình học của ANN là một chu trình tối ưu bộ trọng số w để tối thiểu hóa sai số giữa kết quả dự báo và đáp án thực tế thông qua một hàm mất mát (như MSE). Thuật toán Lan truyền ngược (Backpropagation - BP) đóng vai trò là cơ chế tính toán gradient cốt lõi: mạng thực hiện lượt chạy tiến (Forward Pass) để tính giá trị đầu ra, sau đó truyền ngược tín hiệu sai số từ tầng đầu ra về các tầng ẩn dựa trên quy tắc đạo hàm chuỗi (chain rule) để điều chỉnh trọng số theo hướng giảm gradient (Δwab = η * δa * xb). Việc khởi tạo trọng số ngẫu nhiên nhỏ giúp phá vỡ tính đối xứng giữa các nơ-ron và tránh bão hòa hàm kích hoạt, kết hợp cùng tốc độ học η và thành phần quán tính Momentum (α) giúp chu trình tối ưu hội tụ nhanh và tránh dao động.","Về bản chất kỹ thuật, giá trị lớn nhất của Mạng nơ-ron nằm ở khả năng tự động học biểu diễn đặc trưng (representation learning). Thay vì yêu cầu người dùng trích xuất thuộc tính thủ công, các tầng ẩn đóng vai trò như những cấp độ biến đổi trung gian, biến dữ liệu thô ban đầu thành các không gian đặc trưng có khả năng phân tách cao. Hàm kích hoạt phi tuyến giúp \"bẻ cong\" ranh giới dữ liệu, còn Backpropagation đóng vai trò phân bổ trách nhiệm sai số chính xác đến từng trọng số liên kết. Đánh đổi lại sức mạnh xấp xỉ hàm tổng quát (Universal Approximation Theorem) này là bản chất \"hộp đen\" (black box): tri thức học được bị phân tán thành hàng triệu trọng số số thực, khiến việc truy vết các quy tắc logic minh bạch đằng sau từng phán đoán trở nên cực kỳ khó khăn."],"topics":[{"id":1,"title":"Khái niệm chung về Mạng Nơ-ron Nhân tạo (ANN)","summary":["Mạng nơ-ron nhân tạo (ANN) là cấu trúc xử lý thông tin phân tán và song song mức độ cao, được lấy cảm hứng mô phỏng từ hệ thống nơ-ron thần kinh sinh học của não bộ con người. Mô hình sở hữu năng lực học tập, nhớ lại và khái quát hóa tri thức từ dữ liệu thực nghiệm. Khả năng xử lý của ANN phụ thuộc trực tiếp vào kiến trúc mạng, đặc tính của các nơ-ron, thuật toán huấn luyện và tập dữ liệu đầu vào.","Về bản chất, ANN đóng vai trò như một bộ xấp xỉ hàm đa biến phức tạp, biến đổi không gian đặc trưng đầu vào thành không gian đầu ra mong muốn thông qua đồ thị các nút liên kết mang trọng số. Cơ chế hoạt động dựa trên việc truyền dữ liệu qua các tầng xử lý để đưa ra phán đoán, sau đó đo lường độ sai lệch với thực tế để điều chỉnh thích nghi các tham số trọng số. Ví dụ, trong bài toán nhận diện chữ số viết tay từ ảnh, ANN nhận đầu vào là giá trị pixel của bức ảnh và xuất ra xác suất tương ứng với các chữ số từ 0 đến 9."],"questions":[{"id":1,"text":"Trong một dự án phân tích dữ liệu thị giác máy tính, đội ngũ kỹ thuật lựa chọn mô hình Mạng Nơ-ron Nhân tạo (ANN) để xử lý dữ liệu. Các đặc điểm nào sau đây thể hiện đúng bản chất và năng lực xử lý của mô hình ANN trong ngữ cảnh này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"ANN là cấu trúc xử lý thông tin phân tán và song song mức độ cao, được lấy cảm hứng từ hệ thống nơ-ron sinh học."},{"k":"B","t":"ANN yêu cầu tất cả dữ liệu đầu vào phải được gán nhãn thủ công dưới dạng đường ranh giới tuyến tính cố định."},{"k":"C","t":"Mô hình sở hữu khả năng tự điều chỉnh trọng số liên kết để học tập, nhớ lại và khái quát hóa tri thức từ dữ liệu."},{"k":"D","t":"Hiệu năng của ANN chỉ phụ thuộc duy nhất vào số lượng máy tính phần cứng mà không phụ thuộc vào kiến trúc mạng hay tập học."}],"answer":["A","C"]},{"id":2,"text":"Khi đóng vai trò như một hệ thống xử lý tri thức, bản chất toán học cốt lõi của một Mạng Nơ-ron Nhân tạo (ANN) là gì?","multiple":false,"options":[{"k":"A","t":"Là một thuật toán chia để trị gom nhóm dữ liệu không giám sát dựa trên ma trận khoảng cách Hamming."},{"k":"B","t":"Bù trừ sai số phân tán bằng cách đếm số lượng thuộc tính xuất hiện nhiều nhất trong tập dữ liệu huấn luyện."},{"k":"C","t":"Là một bộ xấp xỉ hàm đa biến phức tạp, biến đổi không gian đặc trưng đầu vào thành không gian đầu ra mong muốn."},{"k":"D","t":"Là một tập hợp các quy tắc logic dạng IF-THEN được khởi tạo cố định trước khi tiếp nhận dữ liệu thực nghiệm."}],"answer":["C"]}]},{"id":2,"title":"Cấu trúc Nơ-ron Nhân tạo và Vai trò của Thành phần Bias","summary":["Một nơ-ron nhân tạo tiếp nhận các tín hiệu đầu vào xi đi kèm với các trọng số liên kết wi tương ứng. Thành phần chênh lệch bias w0 (gắn với x0 = 1) được bổ sung vào tổ hợp tuyến tính để tính đầu vào thuần Net = w0 + Σ wi xi. Kết quả Net sau đó được đưa qua hàm kích hoạt f(·) để sản xuất tín hiệu đầu ra Out = f(Net).","Ý nghĩa kỹ thuật của nơ-ron nhân tạo là một đơn vị tính toán cơ bản kết hợp giữa phép tổng có trọng số và một phép biến đổi phi tuyến. Cơ chế hoạt động của bias w0 đóng vai trò như một ngưỡng dịch chuyển đường ranh giới quyết định ra khỏi gốc tọa độ, giúp nơ-ron linh hoạt định hình mặt phẳng phân tách giữa các lớp dữ liệu. Ví dụ, nếu không có bias (Net = w1 x1), đường ranh giới bắt buộc phải đi qua gốc tọa độ (0,0); khi bổ sung bias w0 (Net = w1 x1 + w0), đường ranh giới có thể tịnh tiến tự do trên mặt phẳng để phân tách chính xác các điểm dữ liệu nằm xa gốc tọa độ."],"questions":[{"id":3,"text":"Xét một nơ-ron nhân tạo với tập đầu vào x = (x1, x2, ..., xm), bộ trọng số w = (w1, w2, ..., wm) và thành phần bias w0. Những phát biểu nào sau đây mô tả đúng vai trò kỹ thuật của bias w0 và quy trình tính toán tín hiệu tại nơ-ron? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bias w0 là một biến ngẫu nhiên thay đổi liên tục theo từng bước thời gian mà không được lưu trong bộ trọng số."},{"k":"B","t":"Bias w0 gắn liền với một đầu vào giả định x0 = 1 và tham gia vào tổng có trọng số Net = w0 + Σ wi xi."},{"k":"C","t":"Tín hiệu đầu ra Out được tính bằng cách nhân trực tiếp bias w0 với giá trị trung bình cộng của các đầu vào."},{"k":"D","t":"Bias w0 đóng vai trò như một ngưỡng dịch chuyển mặt phẳng ranh giới phân tách ra khỏi gốc tọa độ."}],"answer":["B","D"]},{"id":4,"text":"Một kỹ sư loại bỏ hoàn toàn thành phần bias w0 khỏi tất cả các nơ-ron trong mạng (đặt Net = w1 x1 + w2 x2). Hạn chế kỹ thuật trực tiếp nào sẽ xuất hiện khi huấn luyện mô hình phân loại dữ liệu hai chiều?","multiple":false,"options":[{"k":"A","t":"Tất cả các đường ranh giới phân tách do các nơ-ron tạo ra bắt buộc phải đi qua gốc tọa độ (0,0)."},{"k":"B","t":"Mạng nơ-ron sẽ hoàn toàn không thể tính toán được đạo hàm riêng trong giai đoạn lan truyền ngược."},{"k":"C","t":"Giá trị đầu ra của các nơ-ron tự động bị nén về 0 bất kể giá trị của các thuộc tính đầu vào."},{"k":"D","t":"Tất cả các trọng số liên kết wi sẽ bị cố định giá trị và không thể cập nhật qua các chu kỳ học."}],"answer":["A"]}]},{"id":3,"title":"Các Hàm Kích hoạt (Activation Functions)","summary":["Hàm kích hoạt f(·) quyết định tín hiệu đầu ra của nơ-ron dựa trên đầu vào thuần Net. Các dạng hàm phổ biến bao gồm hàm ngưỡng (hard-limited/step) cho đầu ra rời rạc (-1/1 hoặc 0/1), hàm tuyến tính bão hòa (threshold logic), hàm Sigmoid nén đầu ra vào khoảng (0, 1), hàm Tanh nén đầu ra vào khoảng (-1, 1), và hàm ReLU (Out = max(0, Net)) có dải giá trị không âm.","Ý tưởng cốt lõi của hàm kích hoạt là đưa tính chất phi tuyến vào mạng nơ-ron; nếu không có hàm kích hoạt phi tuyến, toàn bộ mạng đa tầng sẽ bị thoái hóa thành một mô hình biến đổi tuyến tính đơn giản. Cơ chế của các hàm khả vi như Sigmoid hay ReLU cho phép tính toán đạo hàm liên tục, giúp truyền tín hiệu sai số ngược từ tầng sau về tầng trước. Ví dụ, hàm Sigmoid chuyển đổi một giá trị Net bất kỳ thành xác suất nằm trong khoảng (0, 1), rất phù hợp làm hàm kích hoạt tại tầng đầu ra cho bài toán phân loại nhị phân."],"questions":[{"id":5,"text":"Hàm kích hoạt f(·) đóng vai trò quyết định đối với khả năng biểu diễn của mạng nơ-ron. Các nhận định nào sau đây diễn tả đúng bản chất kỹ thuật và đặc tính của các hàm kích hoạt phổ biến? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hàm kích hoạt đưa tính chất phi tuyến vào mạng, giúp mô hình học được các ranh giới phân tách phức tạp."},{"k":"B","t":"Hàm Sigmoid chuyển đổi đầu vào Net thành giá trị nằm trong khoảng từ -1 đến 1 để phục vụ phân loại đa lớp."},{"k":"C","t":"Các hàm khả vi như Sigmoid hay ReLU cho phép tính đạo hàm liên tục, hỗ trợ truyền tín hiệu sai số ở giai đoạn học."},{"k":"D","t":"Hàm ReLU biến đổi tất cả các giá trị đầu vào Net thành 0 để triệt tiêu hoàn toàn các tín hiệu nhiễu."}],"answer":["A","C"]},{"id":6,"text":"Giả sử một mạng nơ-ron đa tầng chỉ sử dụng các hàm kích hoạt tuyến tính f(Net) = c * Net (với c là hằng số) tại tất cả các nơ-ron ở các tầng ẩn và tầng đầu ra. Hệ quả toán học nào sẽ xảy ra với mô hình này?","multiple":false,"options":[{"k":"A","t":"Mạng nơ-ron bị mất khả năng lan truyền ngược và dừng cập nhật trọng số ngay tại vòng lặp đầu tiên."},{"k":"B","t":"Mạng nơ-ron sẽ tự động chuyển thành mô hình phân cụm K-means trên không gian thuộc tính."},{"k":"C","t":"Độ chính xác của mạng tăng lên gấp bội do phép tính tuyến tính không làm thất thoát thông tin."},{"k":"D","t":"Toàn bộ mạng đa tầng bị thoái hóa và tương đương với một mô hình biến đổi tuyến tính đơn giản."}],"answer":["D"]}]},{"id":4,"title":"Kiến trúc Mạng Nơ-ron Nhân tạo (ANN Architecture)","summary":["Kiến trúc ANN tổ chức các nơ-ron thành các tầng rõ rệt: Tầng đầu vào (Input layer), một hoặc nhiều Tầng ẩn (Hidden layers), và Tầng đầu ra (Output layer). Về dạng kết nối, mạng lan truyền tiến (Feed-forward) chỉ cho phép tín hiệu truyền một chiều từ trước ra sau. Ngược lại, mạng phản hồi (Feedback) và hồi quy (Recurrent) chứa các liên kết ngược về tầng trước, liên kết ngang cùng tầng, hoặc tạo thành các vòng lặp kín.","Cấu trúc tổ chức của mạng quyết định trực tiếp luồng luân chuyển thông tin và khả năng biểu diễn của mô hình. Cơ chế lan truyền tiến giúp xử lý dữ liệu tĩnh hiệu quả theo từng bước độc lập, trong khi cơ chế hồi quy tạo ra bộ nhớ trạng thái nội bộ giúp mô hình duy trì thông tin từ các bước thời gian trước. Ví dụ, mạng Feed-forward đa tầng được dùng cho bài toán phân loại ảnh tĩnh, trong khi mạng Hồi quy (RNN) được áp dụng để xử lý chuỗi văn bản hoặc dự báo dữ liệu chuỗi thời gian."],"questions":[{"id":7,"text":"Khi thiết kế kiến trúc cho mạng nơ-ron nhân tạo, sự khác biệt giữa cấu trúc Lan truyền tiến (Feed-forward) và cấu trúc Phản hồi/Hồi quy (Recurrent) thể hiện ở những điểm nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Mạng Feed-forward cho phép tín hiệu luân chuyển tự do theo các vòng lặp kín giữa các nơ-ron cùng tầng."},{"k":"B","t":"Mạng Feed-forward chỉ truyền tín hiệu theo một chiều duy nhất từ tầng đầu vào qua các tầng ẩn đến tầng đầu ra."},{"k":"C","t":"Mạng Recurrent không thể huấn luyện bằng thuật toán tối ưu hóa Gradient Descent do cấu trúc đa tầng."},{"k":"D","t":"Mạng Recurrent chứa các liên kết phản hồi hoặc vòng lặp, giúp mô hình lưu trữ thông tin trạng thái từ quá khứ."}],"answer":["B","D"]},{"id":8,"text":"Trong kiến trúc mạng nơ-ron đa tầng, các nơ-ron thuộc tầng ẩn (Hidden layer) đóng vai trò kỹ thuật nào trong quá trình xử lý thông tin? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Biến đổi không gian dữ liệu đầu vào thành các biểu diễn đặc trưng phi tuyến ở cấp độ cao hơn."},{"k":"B","t":"Tương tác trực tiếp với môi trường bên ngoài để tiếp nhận dữ liệu thô và xuất kết quả dự báo."},{"k":"C","t":"Trích xuất các mẫu hình trung gian giúp mạng xây dựng các mặt phẳng phân tách phức tạp."},{"k":"D","t":"Cố định giá trị các trọng số liên kết để ngăn chặn hiện tượng quá khớp ở tầng đầu ra."}],"answer":["A","C"]}]},{"id":5,"title":"Huấn luyện Mạng Nơ-ron và Hàm Mất mát Thực nghiệm","summary":["Quá trình huấn luyện mạng nơ-ron (với cấu trúc mạng cố định) là bài toán học tham số để tìm bộ trọng số w tối ưu từ tập dữ liệu huấn luyện D. Việc học được thực hiện bằng cách tối thiểu hóa một hàm sai số thực nghiệm L(w) = (1/|D|) * Σ loss(dx, out(x)), đo lường mức độ chênh lệch giữa đầu ra của mạng out(x) và nhãn mong muốn dx. Các phương pháp tối ưu dựa trên Gradient phổ biến gồm Backpropagation, SGD, Adam và AdaGrad.","Về bản chất, huấn luyện tham số là quá trình dò tìm điểm cực tiểu của bề mặt sai số trong không gian trọng số nhiều chiều. Cơ chế hoạt động dựa vào việc tính toán vectơ độ dốc Gradient (∇E) của hàm mất mát theo từng trọng số, sau đó cập nhật trọng số theo hướng ngược chiều gradient để giảm dần tổng sai số. Ví dụ, với bài toán hồi quy, hàm mất mát bình phương trung bình (MSE) được sử dụng để phạt nặng các độ lệch lớn giữa giá trị dự báo và thực tế."],"questions":[{"id":9,"text":"Quá trình huấn luyện một mạng nơ-ron nhân tạo với cấu trúc cố định trên tập dữ liệu D = {(x, d)} là một bài toán học tham số. Những nhận định nào sau đây mô tả đúng mục tiêu và cơ chế của quá trình này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Mục tiêu là tìm bộ trọng số w sao cho tổng số lượng nơ-ron ẩn trong mạng giảm về mức tối thiểu."},{"k":"B","t":"Việc học tham số được thực hiện bằng cách thay đổi cấu trúc liên kết và thêm bớt các tầng xử lý."},{"k":"C","t":"Mô hình tối ưu bộ trọng số w thông qua việc tối thiểu hóa một hàm sai số thực nghiệm L(w) trên tập D."},{"k":"D","t":"Hàm sai số đo lường mức độ chênh lệch giữa giá trị dự báo Out(x) của mạng và nhãn mong muốn d."}],"answer":["C","D"]},{"id":10,"text":"Trong bài toán hồi quy dự báo giá trị số thực, hàm mất mát Bình phương Trung bình (MSE) L(w) = (1/|D|) * Σ (d - Out)^2 thường được lựa chọn để huấn luyện mạng nơ-ron. Lý do kỹ thuật chính của lựa chọn này là gì?","multiple":false,"options":[{"k":"A","t":"MSE giúp triệt tiêu hoàn toàn các trọng số liên kết có giá trị âm ở tầng đầu ra."},{"k":"B","t":"MSE phạt nặng các độ lệch lớn giữa giá trị dự báo và thực tế, đồng thời là hàm trơn dễ tính đạo hàm."},{"k":"C","t":"MSE tự động nén tất cả các giá trị dự báo Out về khoảng xác suất từ 0 đến 1."},{"k":"D","t":"MSE đảm bảo mạng nơ-ron đạt được nghiệm tối ưu toàn cục chỉ sau một chu kỳ học duy nhất."}],"answer":["B"]}]},{"id":6,"title":"Mô hình Perceptron và Thuật toán Học Perceptron","summary":["Perceptron là dạng mạng ANN đơn giản nhất gồm duy nhất 1 nơ-ron sử dụng hàm kích hoạt dạng ngưỡng Out = sign(Net(w, x)) để phân loại nhị phân. Mặt phẳng phân tách (separation plane) w0 + w1 x1 + w2 x2 = 0 chia không gian thuộc tính thành hai nửa tương ứng với hai lớp đầu ra. Thuật toán học Perceptron dạng lô (batch) cập nhật trọng số theo quy tắc Δw ← Δw + η * (d - Out) * x mỗi khi phát hiện mẫu bị phân loại sai.","Thực chất, Perceptron là một bộ phân loại tuyến tính xác định ranh giới quyết định dạng siêu phẳng. Cơ chế học của Perceptron dựa trên sự tự điều chỉnh từng bước: nếu mẫu thuộc lớp 1 mà Perceptron đoán -1, trọng số w sẽ cộng thêm một lượng tỷ lệ với x để tăng Net; ngược lại nếu đoán sai sang 1, w sẽ trừ đi một lượng tương ứng để giảm Net. Ví dụ, Perceptron có thể học hoàn hảo để biểu diễn các cổng logic cơ bản như AND, OR."],"questions":[{"id":11,"text":"Xét mô hình Perceptron đơn tầng với hàm kích hoạt dạng ngưỡng Out = sign(Net). Thuật toán học Perceptron cập nhật trọng số theo quy tắc Δw = η * (d - Out) * x. Những nhận định nào sau đây diễn tả đúng cơ chế học này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Trọng số w chỉ được cập nhật khi mẫu huấn luyện bị phân loại sai (d khác Out)."},{"k":"B","t":"Nếu mẫu thuộc lớp 1 nhưng mô hình đoán -1, trọng số w được cộng thêm một lượng tỷ lệ với x để tăng Net."},{"k":"C","t":"Nếu mẫu được phân loại đúng, trọng số w sẽ tự động giảm về 0 để tiết kiệm bộ nhớ lưu trữ."},{"k":"D","t":"Tốc độ học η bắt buộc phải là một số nguyên dương lớn hơn 100 để đảm bảo thuật toán dừng lại."}],"answer":["A","B"]},{"id":12,"text":"Một Perceptron hai đầu vào x1, x2 có trọng số w1 = 2, w2 = -3 và bias w0 = 6. Phương trình thể hiện ranh giới phân tách (separation plane) giữa hai lớp dữ liệu trong không gian hai chiều là gì?","multiple":false,"options":[{"k":"A","t":"2 x1 - 3 x2 = 0"},{"k":"B","t":"2 x1 + 3 x2 - 6 = 0"},{"k":"C","t":"6 + 2 x1 - 3 x2 = 0"},{"k":"D","t":"6 x0 + 2 x1 + 3 x2 = 1"}],"answer":["C"]}]},{"id":7,"title":"Hạn chế của Perceptron và Bài toán Phân tách Tuyến tính","summary":["Thuật toán học Perceptron được chứng minh toán học sẽ chắc chắn hội tụ nếu tập dữ liệu đầu vào là phân tách tuyến tính (linearly separable) và tốc độ học η đủ nhỏ. Ngược lại, nếu tập dữ liệu không phân tách tuyến tính được, thuật toán học Perceptron sẽ rơi vào lặp vô tận và không bao giờ hội tụ.","Điểm mấu chốt tạo nên hạn chế này xuất phát từ việc một nơ-ron đơn lẻ chỉ tạo ra được một đường ranh giới tuyến tính thẳng trong không gian thuộc tính. Cơ chế phân loại của nó không thể tự uốn cong hay tạo ra các ranh giới phi tuyến để bao bọc các nhóm dữ liệu nằm xen kẽ nhau. Ví dụ điển hình là bài toán cổng logic XOR với 4 điểm dữ liệu (0,0) → 0, (1,1) → 0, (0,1) → 1, (1,0) → 1; không thể vẽ bất kỳ một đường thẳng đơn lẻ nào để phân tách hai lớp nhãn này, khiến Perceptron đơn tầng hoàn toàn thất bại."],"questions":[{"id":13,"text":"Định lý hội tụ Perceptron đặt ra các điều kiện và giới hạn nghiêm ngặt đối với mô hình Perceptron đơn tầng. Những kết luận kỹ thuật nào sau đây là chính xác? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Perceptron chắc chắn hội tụ trên mọi tập dữ liệu bất kể phân bố hình học của các điểm dữ liệu."},{"k":"B","t":"Thuật toán học Perceptron đảm bảo hội tụ nếu tập dữ liệu huấn luyện là phân tách tuyến tính."},{"k":"C","t":"Perceptron đơn tầng có thể giải quyết hoàn hảo bài toán cổng logic phi tuyến XOR."},{"k":"D","t":"Nếu tập dữ liệu không phân tách tuyến tính được, thuật toán học Perceptron sẽ rơi vào lặp vô tận."}],"answer":["B","D"]},{"id":14,"text":"Nguyên nhân bản chất nào khiến cho một mô hình Perceptron đơn tầng hoàn toàn thất bại khi giải bài toán cổng logic XOR với 4 điểm dữ liệu (0,0) → 0, (1,1) → 0, (0,1) → 1, (1,0) → 1?","multiple":false,"options":[{"k":"A","t":"Không thể vẽ được một đường ranh giới tuyến tính thẳng đơn lẻ để phân tách hai tập điểm dữ liệu này."},{"k":"B","t":"Cổng logic XOR yêu cầu hàm kích hoạt tại tầng đầu ra phải là hàm bước nhảy không khả vi."},{"k":"C","t":"Kích thước tập dữ liệu 4 mẫu quá nhỏ khiến cho giá trị bias w0 bị triệt tiêu về 0."},{"k":"D","t":"Thuật toán Perceptron không hỗ trợ các phép tính đại số trên giá trị đầu vào là 0 và 1."}],"answer":["A"]}]},{"id":8,"title":"Tối ưu hóa Sai số dựa trên Gradient Descent","summary":["Đối với mạng nơ-ron có hàm kích hoạt trơn, sai số tại một mẫu là Ex(w) = (1/2) * Σ (di - Outi)^2 và sai số toàn tập học là ED(w) = (1/|D|) * Σ Ex(w). Vectơ Gradient ∇E(w) xác định hướng gia tăng sai số nhanh nhất; do đó, hướng giảm sai số nhanh nhất là hướng ngược chiều gradient. Quy tắc cập nhật trọng số có dạng Δw = -η * ∇E(w), tương ứng với Δwi = -η * (∂E / ∂wi).","Về mặt nguyên lý, Gradient Descent là phương pháp tối ưu hóa xấp xỉ liên tục dựa trên đạo hàm riêng cấp một. Cơ chế hoạt động tương tự như việc thả một viên bi trượt xuống từ đỉnh đồi: tại mỗi điểm đứng, mô hình tính độ dốc địa hình và bước một khoảng ngắn η về phía thung lũng có độ dốc âm sâu nhất. Việc cập nhật có thể thực hiện theo lô (Batch), theo từng mẫu (Incremental/Stochastic SGD), hoặc theo nhóm nhỏ (Mini-batch)."],"questions":[{"id":15,"text":"Để tối thiểu hóa hàm sai số ED(w) của mạng nơ-ron có hàm kích hoạt trơn, thuật toán Gradient Descent dựa trên các nguyên lý giải tích nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Vectơ Gradient ∇E(w) chỉ hướng gia tăng sai số nhanh nhất trong không gian trọng số."},{"k":"B","t":"Hướng giảm sai số nhanh nhất là hướng cùng chiều với vectơ độ dốc Gradient ∇E(w)."},{"k":"C","t":"Quy tắc cập nhật trọng số Δw = -η * ∇E(w) di chuyển bộ trọng số theo hướng ngược chiều gradient."},{"k":"D","t":"Độ dốc Gradient luôn bằng 0 tại tất cả các điểm nằm xa điểm tối ưu cục bộ."}],"answer":["A","C"]},{"id":16,"text":"So sánh giữa các chế độ cập nhật trọng số trong Gradient Descent, đặc điểm nổi bật của phương pháp Cập nhật theo nhóm nhỏ (Mini-batch Gradient Descent) là gì?","multiple":false,"options":[{"k":"A","t":"Chỉ cập nhật trọng số một lần duy nhất sau khi đã duyệt qua toàn bộ dữ liệu ở tất cả các chu kỳ."},{"k":"B","t":"Cập nhật trọng số ngay lập tức sau khi tính sai số cho đúng một mẫu dữ liệu đơn lẻ."},{"k":"C","t":"Triệt tiêu hoàn toàn sự ảnh hưởng của tốc độ học η đối với sự hội tụ của hàm sai số."},{"k":"D","t":"Cân bằng giữa tốc độ tính toán và độ ổn định của hướng gradient bằng cách tính sai số trên các nhóm mẫu nhỏ."}],"answer":["D"]}]},{"id":9,"title":"Thuật toán Lan truyền Ngược (Backpropagation - BP)","summary":["Mạng nơ-ron đa tầng (Multi-layer NN) được huấn luyện bằng thuật toán Lan truyền ngược (BP) có khả năng biểu diễn các hàm phân tách phi tuyến phức tạp. Thuật toán BP vận hành qua hai giai đoạn cốt lõi: Giai đoạn lan truyền tiến (Forward pass) truyền tín hiệu đầu vào qua các tầng để nhận giá trị đầu ra thực tế Out, và Giai đoạn lan truyền ngược sai số (Error backward pass) tính toán sai số tại tầng đầu ra rồi truyền ngược lại các tầng trước để tính gradient cục bộ và cập nhật trọng số.","Về bản chất, BP là sự kết hợp giữa chiến lược Gradient Descent và quy tắc đạo hàm chuỗi (chain rule) trong giải tích. Cơ chế hoạt động cho phép phân bổ trách nhiệm gây ra sai số đầu ra về cho từng trọng số liên kết ở các tầng ẩn sâu bên trong mạng, điều mà các thuật toán đơn tầng không làm được. Ví dụ, khi dự báo giá nhà sai lệch 10.000 USD ở tầng đầu ra, thuật toán BP tính toán mức độ đóng góp sai số của từng nơ-ron ở tầng ẩn để điều chỉnh lực liên kết tương ứng."],"questions":[{"id":17,"text":"Thuật toán Lan truyền Ngược (Backpropagation - BP) là giải thuật nền tảng để huấn luyện mạng nơ-ron đa tầng. Hai giai đoạn vận hành cốt lõi của BP bao gồm những hoạt động nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giai đoạn khởi tạo: Xóa bỏ tất cả các nơ-ron ẩn có tín hiệu đầu ra nhỏ hơn ngưỡng quy định."},{"k":"B","t":"Giai đoạn lan truyền tiến (Forward pass): Truyền tín hiệu từ tầng đầu vào qua các tầng ẩn để tính đầu ra Out."},{"k":"C","t":"Giai đoạn lan truyền ngược (Backward pass): Tính sai số ở đầu ra, truyền ngược về trước để tính gradient và cập nhật w."},{"k":"D","t":"Giai đoạn cắt tỉa: Chuyển toàn bộ các nơ-ron ở tầng ẩn thành các nơ-ron thuộc tầng đầu ra."}],"answer":["B","C"]},{"id":18,"text":"Trong thuật toán Backpropagation, cơ chế toán học nào cho phép mô hình tính toán được mức độ đóng góp sai số của các nơ-ron nằm sâu ở các tầng ẩn? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Áp dụng quy tắc đạo hàm chuỗi (chain rule) trong giải tích để tính đạo hàm riêng của hàm sai số theo từng trọng số."},{"k":"B","t":"Gán cố định giá trị sai số của các nơ-ron tầng ẩn bằng đúng giá trị sai số đo được ở tầng đầu vào."},{"k":"C","t":"Loại bỏ tất cả các hàm kích hoạt phi tuyến để chuyển phép tính lan truyền ngược thành phép nhân ma trận vuông."},{"k":"D","t":"Lan truyền ngược tín hiệu sai số từ các nơ-ron tầng sau tác động ngược lại để tính tín hiệu sai số cục bộ δ tại tầng ẩn."}],"answer":["A","D"]}]},{"id":10,"title":"Cơ chế Cập nhật Trọng số và Quy tắc Delta Tổng quát","summary":["Công thức cập nhật trọng số cho liên kết từ nơ-ron b sang nơ-ron a (b → a) trong thuật toán BP tuân theo quy tắc Delta tổng quát: Δwab = η * δa * xb. Trong đó xb là tín hiệu đầu ra từ nơ-ron b, và δa là tín hiệu sai số cục bộ tại nơ-ron a. Điểm khác biệt cốt lõi là tín hiệu sai số δi tại tầng đầu ra được tính trực tiếp từ độ lệch [di - Outi] * f'(Neti), trong khi δq tại tầng ẩn được tính truy hồi từ tổng các δi của tầng sau tác động ngược lại: δq = f'(Netq) * Σ (δi * wiq).","Ý nghĩa kỹ thuật của quy tắc Delta tổng quát là cơ chế lan truyền ngược sai số dạng sóng: các nơ-ron ở tầng ẩn nhận tín hiệu sai số bằng tổng gia trọng các tín hiệu sai số từ tất cả các nơ-ron tầng sau mà nó kết nối tới. Cơ chế này đảm bảo mọi trọng số liên kết trong mạng đa tầng đều được cập nhật một cách chính xác theo nguyên lý giảm gradient. Ví dụ, một nơ-ron ẩn kết nối tới 3 nơ-ron đầu ra sẽ tổng hợp sai số lan truyền từ cả 3 nơ-ron này để tính ra mức độ điều chỉnh trọng số đầu vào của chính nó."],"questions":[{"id":19,"text":"Công thức cập nhật trọng số liên kết từ nơ-ron b sang nơ-ron a trong thuật toán BP tuân theo Quy tắc Delta tổng quát: Δwab = η * δa * xb. Những phát biểu nào sau đây diễn tả đúng bản chất của các thành phần trong công thức này? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Thành phần xb đại diện cho tín hiệu đầu ra được truyền đến từ nơ-ron b."},{"k":"B","t":"Thành phần δa là tốc độ học cố định được thiết lập riêng cho nơ-ron a."},{"k":"C","t":"Lượng điều chỉnh Δwab tỷ lệ nghịch với tín hiệu sai số cục bộ δa tại nơ-ron a."},{"k":"D","t":"Thành phần δa đo lường tín hiệu sai số cục bộ chịu ảnh hưởng bởi đạo hàm của hàm kích hoạt f'(Net_a)."}],"answer":["A","D"]},{"id":20,"text":"Điểm khác biệt cốt lõi trong việc tính toán tín hiệu sai số cục bộ δ giữa nơ-ron i thuộc Tầng đầu ra và nơ-ron q thuộc Tầng ẩn là gì?","multiple":false,"options":[{"k":"A","t":"Tín hiệu δ tại tầng đầu ra luôn bằng 0, trong khi δ tại tầng ẩn bằng tổng trọng số liên kết."},{"k":"B","t":"Tín hiệu δ tại tầng đầu ra tính trực tiếp từ độ lệch (d - Out), còn δ tại tầng ẩn tính truy hồi từ tổng gia trọng các δ của tầng sau."},{"k":"C","t":"Tín hiệu δ tại tầng ẩn không phụ thuộc vào đạo hàm của hàm kích hoạt f'(Net_q)."},{"k":"D","t":"Tín hiệu δ tại tầng đầu ra được tính bằng cách nhân trực tiếp giá trị đầu vào x với tốc độ học η."}],"answer":["B"]}]},{"id":11,"title":"Khởi tạo Trọng số và Khắc phục Điểm Bão hòa / Điểm Yên ngựa","summary":["Trọng số của mạng BP thường được khởi tạo bằng các giá trị ngẫu nhiên nhỏ (như phân phối Gaussian hoặc Uniform). Nếu khởi tạo trọng số với giá trị quá lớn, hàm kích hoạt Sigmoid sẽ nhanh chóng rơi vào điểm bão hòa (saturation). Hậu quả là đạo hàm f'(Net) tiệm cận về 0, làm các tín hiệu sai số δ bị triệt tiêu và hệ thống rơi vào trạng thái bế tắc tại các điểm yên ngựa (saddle points).","Mục đích của việc khởi tạo trọng số ngẫu nhiên nhỏ là để phá vỡ tính đối xứng (symmetry breaking) giữa các nơ-ron và giữ cho giá trị đầu vào thuần Net nằm trong vùng có độ dốc lớn nhất của hàm kích hoạt. Cơ chế này giúp đạo hàm f'(Net) đạt giá trị đủ lớn, đảm bảo tín hiệu gradient lan truyền mạnh mẽ qua các tầng. Ví dụ, nếu tất cả trọng số ban đầu đều bằng 0, tất cả nơ-ron ở tầng ẩn sẽ nhận cùng một tín hiệu và tính ra gradient giống hệt nhau, khiến mạng không thể học được các đặc trưng đa dạng."],"questions":[{"id":21,"text":"Việc khởi tạo trọng số ban đầu cho mạng nơ-ron đa tầng đóng vai trò rất quan trọng đối với sự thành công của thuật toán BP. Những kết luận kỹ thuật nào sau đây là chính xác? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tất cả các trọng số ban đầu nên được gán bằng 0 để đảm bảo tính đối xứng hoàn hảo giữa các nơ-ron."},{"k":"B","t":"Trọng số ban đầu nên được gán bằng các giá trị thực rất lớn để tăng tốc độ lan truyền tiến."},{"k":"C","t":"Cần khởi tạo trọng số bằng các giá trị ngẫu nhiên nhỏ để phá vỡ tính đối xứng (symmetry breaking)."},{"k":"D","t":"Khởi tạo trọng số quá lớn dễ làm hàm Sigmoid rơi vào vùng bão hòa, khiến gradient tiệm cận 0 và gây bế tắc học tập."}],"answer":["C","D"]},{"id":22,"text":"Khi các trọng số liên kết trong mạng nơ-ron được khởi tạo với giá trị quá lớn, hiện tượng \"điểm bão hòa\" (saturation) ở hàm kích hoạt Sigmoid f(Net) = 1 / (1 + e^-Net) gây ra tác động tiêu cực nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giá trị đầu vào thuần Net rơi vào vùng rất xa trung tâm, làm cho đạo hàm f'(Net) tiệm cận về 0."},{"k":"B","t":"Tín hiệu sai số δ bị triệt tiêu khiến các trọng số hầu như không thể cập nhật (biến mất gradient)."},{"k":"C","t":"Mạng nơ-ron tự động chuyển thành mô hình Perceptron đơn tầng và loại bỏ tất cả các tầng ẩn."},{"k":"D","t":"Hàm sai số L(w) tự động giảm xuống bằng 0 làm cho mô hình dừng học ngay lập tức."}],"answer":["A","B"]}]},{"id":12,"title":"Tốc độ Học (Learning Rate) và Thành phần Quán tính (Momentum)","summary":["Tốc độ học η ảnh hưởng trực tiếp đến sự hội tụ của BP: η quá lớn làm hệ thống dao động mạnh hoặc bỏ qua điểm tối ưu toàn cục; η quá nhỏ khiến quá trình học kéo dài tốn thời gian. Để khắc phục hiện tượng dao động khi η lớn, thành phần quán tính (momentum) α được bổ sung vào công thức cập nhật: Δw(t) = -η * ∇E(t) + α * Δw(t-1) với α ∈ (0, 1) (thường chọn α = 0.9).","Ý tưởng đằng sau thành phần momentum là bổ sung hiệu ứng quán tính từ bước cập nhật trước đó vào bước cập nhật hiện tại. Cơ chế này giúp bước cập nhật tiếp tục di chuyển theo hướng cũ nếu hướng gradient không đổi, giúp mô hình lướt nhanh qua các vùng bằng phẳng (plateau) và dập tắt các dao động xích zắc rào cản khi đi qua lòng chảo hẹp. Ví dụ, khi trượt xuống bề mặt sai số có dạng khe hẹp, momentum giúp triệt tiêu các bước nhảy qua lại hai bên thành khe và tăng tốc lao thẳng về phía đáy thung lũng."],"questions":[{"id":23,"text":"Tốc độ học η và thành phần quán tính (momentum) α là hai siêu tham số quan trọng trong thuật toán BP. Những nhận định nào sau đây diễn tả đúng ảnh hưởng của chúng đến quá trình tối ưu hóa? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Tốc độ học η quá nhỏ sẽ làm cho mô hình liên tục dao động xích zắc và không bao giờ tiến về đáy thung lũng."},{"k":"B","t":"Tốc độ học η quá lớn có thể khiến bước cập nhật nhảy vọt qua điểm tối ưu hoặc gây dao động mất ổn định."},{"k":"C","t":"Thành phần quán tính α bắt buộc phải nhận giá trị âm để đảo ngược hướng di chuyển của trọng số."},{"k":"D","t":"Momentum bổ sung hiệu ứng quán tính từ bước cập nhật trước, giúp mô hình lướt qua các vùng bằng phẳng và dập tắt dao động."}],"answer":["B","D"]},{"id":24,"text":"Công thức cập nhật trọng số chứa thành phần quán tính có dạng Δw(t) = -η * ∇E(t) + α * Δw(t-1). Ý nghĩa vật lý / hình học của đại lượng α * Δw(t-1) trong quy tắc này là gì?","multiple":false,"options":[{"k":"A","t":"Triệt tiêu hoàn toàn độ dốc Gradient hiện tại ∇E(t) để giữ nguyên vị trí trọng số."},{"k":"B","t":"Đột ngột thay đổi kích thước của mạng nơ-ron bằng cách nhân bản các trọng số ở bước t-1."},{"k":"C","t":"Duy trì \"động năng\" từ hướng cập nhật ở bước thời gian trước, giúp mô hình duy trì đà di chuyển ổn định."},{"k":"D","t":"Bắt buộc mô hình phải quay trở lại vị trí trọng số ban đầu nếu sai số ở bước t lớn hơn bước t-1."}],"answer":["C"]}]},{"id":13,"title":"Khả năng Biểu diễn và Hạn chế Hộp đen của Mạng Nơ-ron","summary":["Theo Định lý xấp xỉ tổng quát (Universal Approximation Theorem), một mạng nơ-ron lan truyền tiến chỉ cần 1 tầng ẩn với các nơ-ron phi tuyến là đủ khả năng xấp xỉ tốt bất kỳ hàm liên tục bị chặn nào. Dù sở hữu ưu điểm vượt trội về độ chính xác và tính toán song song trên dữ liệu phức tạp, nhược điểm lớn nhất của ANN là thiếu quy tắc chuẩn để chọn số lượng nơ-ron tầng ẩn (phụ thuộc vào thử nghiệm trial and error) và bản chất hoạt động như một \"hộp đen\" (black box) cực kỳ khó giải thích cơ chế suy luận.","Về bản chất, mạng nơ-ron là sự kết hợp tự động của hàng triệu phép biến đổi phi tuyến phi số học, trong đó tri thức được phân tán rải rác dưới dạng hàng triệu giá trị trọng số liên kết. Cơ chế này giúp mạng đạt hiệu năng cực cao trên dữ liệu phi cấu trúc nhưng lại khiến con người không thể trích xuất ra các luật IF-THEN minh bạch như cây quyết định. Ví dụ, một mạng nơ-ron sâu chẩn đoán chính xác bệnh lý từ ảnh X-quang với độ chính xác 99%, nhưng bác sĩ không thể truy vết lý do toán học cụ thể vì sao mô hình lại đưa ra quyết định đó.","B. Bài tập tham khảo"],"questions":[{"id":25,"text":"Định lý xấp xỉ tổng quát (Universal Approximation Theorem) khẳng định khả năng biểu diễn của mạng nơ-ron lan truyền tiến. Những phát biểu nào sau đây thể hiện đúng tinh thần của định lý này và thực tế ứng dụng? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Một mạng lan truyền tiến chỉ cần 1 tầng ẩn với các nơ-ron phi tuyến là đủ xấp xỉ tốt bất kỳ hàm liên tục bị chặn nào."},{"k":"B","t":"Định lý chứng minh sự tồn tại về mặt lý thuyết của bộ trọng số phù hợp nhưng không chỉ ra cách tìm bộ trọng số đó."},{"k":"C","t":"Mạng nơ-ron 1 tầng ẩn luôn đảm bảo tìm được nghiệm hoàn hảo cho mọi tập dữ liệu trong thời gian O(1)."},{"k":"D","t":"Định lý đưa ra công thức toán học chính xác để xác định số lượng nơ-ron ẩn tối ưu cho mọi bài toán."}],"answer":["A","B"]},{"id":26,"text":"Mặc dù sở hữu độ chính xác rất cao trên dữ liệu phức tạp, Mạng Nơ-ron Nhân tạo (ANN) thường bị coi là mô hình \"hộp đen\" (black box). Nhược điểm kỹ thuật này xuất phát từ nguyên nhân nào và gây ra hạn chế gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"ANN không hỗ trợ khả năng tính toán song song trên các hệ thống phần cứng hiện đại."},{"k":"B","t":"Tri thức được phân tán rải rác dưới dạng hàng triệu trọng số liên kết phi tuyến, rất khó truy vết quy tắc logic minh bạch."},{"k":"C","t":"Người dùng không thể trích xuất ra các luật IF-THEN rõ ràng để giải thích lý do cụ thể vì sao mô hình đưa ra phán đoán."},{"k":"D","t":"Mạng nơ-ron hoàn toàn không thể thực hiện dự báo trên các tập dữ liệu ảnh, video hay âm thanh."}],"answer":["B","C"]}]}]},{"id":"l8-svm","title":"L8 SVM","summary":["Máy Vectơ Hỗ trợ (Support Vector Machine - SVM) là phương pháp học có giám sát mạnh mẽ do Vapnik và các đồng nghiệp đề xuất, được thiết kế ban đầu cho bài toán phân loại tuyến tính nhị phân. Dưới góc nhìn hình học, mô hình tìm kiếm một siêu phẳng phân tách (decision boundary) có dạng f(x) = <w, x> + b = 0 để chia không gian thuộc tính thành hai nửa chứa các mẫu thuộc lớp dương (y = +1) và lớp âm (y = -1). Điểm đột phá của SVM nằm ở nguyên lý cực đại hóa mức lề (Max-Margin): trong số vô số siêu phẳng phân tách khả thi, SVM chọn siêu phẳng nằm cách đều các điểm dữ liệu gần nhất của hai lớp một khoảng Margin = 2 / ||w|| lớn nhất. Lý thuyết học máy chứng minh rằng siêu phẳng lề cực đại giúp tối thiểu hóa rủi ro mắc lỗi phân loại và đạt khả năng tổng quát hóa tối ưu trên dữ liệu mới.","Việc cực đại hóa mức lề được quy về bài toán tối ưu lồi quy hoạch bậc hai có ràng buộc bất đẳng thức: tối thiểu hóa (1/2) * ||w||² thỏa mãn yi * (<w, xi> + b) ≥ 1 với mọi mẫu huấn luyện. Thông qua việc thiết lập hàm Lagrange với các biến đối ngẫu αi ≥ 0 và áp dụng bộ điều kiện KKT (Karush-Kuhn-Tucker), bài toán gốc (Primal) được đưa về dạng đối ngẫu (Dual Form) cực đại hóa LD(α) = Σ αi - (1/2) * Σ Σ αi * αj * yi * yj * <xi, xj> chỉ với ràng buộc đơn giản Σ αi * yi = 0 và αi ≥ 0. Nhờ điều kiện bù KKT, SVM sở hữu tính thưa (sparsity) cực kỳ vượt trội: ranh giới quyết định và hàm phán đoán f(z) = sign(Σ αi * yi * K(xi, z) + b)* chỉ phụ thuộc hoàn toàn vào một tập con nhỏ các điểm dữ liệu nằm trên lề gọi là các Vectơ hỗ trợ (Support Vectors với αi > 0).","Khi dữ liệu thực tế chứa nhiễu hoặc các lớp chồng lấn, mô hình Soft-Margin SVM bổ sung biến nới lỏng ξi ≥ 0 cùng hằng số phạt C (tương ứng với hàm mất mát Hinge Loss) để chấp nhận vi phạm lề ở mức độ soát lỗi cho phép, làm xuất hiện ràng buộc hộp đối ngẫu 0 ≤ αi ≤ C. Đối với các bài toán phi tuyến phức tạp, SVM áp dụng Kỹ thuật Kernel (Kernel Trick): thay vì tính toán trực tiếp phép ánh xạ φ(x) đưa dữ liệu lên không gian đặc trưng (Feature Space) nhiều chiều, mô hình thay thế tích vô hướng bằng một hàm nhân K(x, z) = <φ(x), φ(z)> (như Polynomial, Gaussian RBF, Sigmoid) giúp tránh triệt tiêu bởi \"lời nguyền số chiều\". Mặc dù hoạt động rất hiệu quả trên dữ liệu số chiều lớn (như phân loại văn bản) và có nền tảng toán học chặt chẽ, việc sử dụng các hàm Kernel phi tuyến khiến mô hình mang tính chất \"hộp đen\" và cực kỳ khó giải thích cơ chế suy luận chi tiết."],"topics":[{"id":1,"title":"Bài toán SVM","summary":["Mạng Vectơ Hỗ trợ (Support Vector Machine - SVM) là phương pháp học máy có giám sát được đề xuất bởi Vladimir Vapnik và các đồng nghiệp vào những năm 1970 và trở nên phổ biến rộng rãi từ thập niên 1990. Về mặt nguyên lý ban đầu, SVM là thuật toán phân loại tuyến tính với mục tiêu tìm một siêu phẳng (hyperplane) trong không gian thuộc tính để phân tách dữ liệu thành hai lớp nhãn biệt lập (lớp dương y = +1 và lớp âm y = -1). Khi xử lý các tập dữ liệu phi tuyến không thể phân tách bằng mặt phẳng thẳng, mô hình tích hợp thêm các hàm nhân (Kernel functions) để biến đổi dữ liệu.","Ý tưởng kỹ thuật cốt lõi của SVM dựa trên nền tảng toán học và lý thuyết thống kê chặt chẽ nhằm đảm bảo hiệu năng tổng quát hóa tối ưu. Điểm mạnh vượt trội của mô hình là khả năng làm việc cực kỳ hiệu quả trong các không gian dữ liệu số chiều rất lớn mà không bị suy giảm độ chính xác do hiện tượng quá khớp. Lợi thế này giúp SVM trở thành một trong những lựa chọn hàng đầu cho các bài toán phân loại dữ liệu phi cấu trúc phức tạp, điển hình là bài toán phân loại văn bản (text categorization)."],"questions":[{"id":1,"text":"Trong bối cảnh phát triển của các thuật toán học máy có giám sát, mô hình Máy Vectơ Hỗ trợ (SVM) sở hữu những ưu điểm nền tảng và thế mạnh ứng dụng nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"SVM sở hữu nền tảng lý thuyết toán học và thống kê chặt chẽ, hướng tới tối thiểu hóa rủi ro phân loại sai."},{"k":"B","t":"SVM chỉ có thể hoạt động hiệu quả khi số lượng thuộc tính đầu vào nhỏ hơn rất nhiều so với số lượng mẫu huấn luyện."},{"k":"C","t":"Mô hình làm việc cực kỳ hiệu quả trong các không gian dữ liệu số chiều lớn, điển hình là bài toán phân loại văn bản."},{"k":"D","t":"Mô hình tự động trích xuất các quy tắc IF-THEN minh bạch giúp người dùng dễ dàng giải thích cơ chế suy luận."}],"answer":["A","C"]},{"id":2,"text":"Khi xét mô hình Linear SVM (không sử dụng biến đổi phi tuyến), phát biểu nào mô tả đúng bản chất kỹ thuật và cách thức vận hành của mô hình? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Linear SVM thực chất là trường hợp đặc biệt của SVM khi áp dụng một hàm nhân tuyến tính (linear kernel)."},{"k":"B","t":"Mô hình tìm kiếm một siêu phẳng phân tách dạng f(x) = <w, x> + b = 0 để chia không gian thành hai nửa nhãn lớp."},{"k":"C","t":"Giá trị của hệ số bias b bắt buộc phải bằng 0 để siêu phẳng ranh giới đi qua gốc tọa độ trong không gian thuộc tính."},{"k":"D","t":"Vectơ trọng số w đại diện cho pháp tuyến vuông góc với siêu phẳng phân tách ranh giới quyết định."}],"answer":["A","D"]}]},{"id":2,"title":"Giả thuyết Phân tách Tuyến tính","summary":["Trong bài toán phân loại tuyến tính nhị phân, tập dữ liệu huấn luyện D gồm r mẫu quan sát dạng D = {(x1, y1), (x2, y2), ..., (xr, yr)}. Mỗi mẫu dữ liệu xi là một vectơ n chiều đại diện cho n thuộc tính đầu vào, và yi là nhãn lớp nhận giá trị rời rạc thuộc tập {-1, +1}. Siêu phẳng phân tách được biểu diễn dưới dạng hàm tuyến tính f(x) = <w, x> + b = 0, trong đó w là vectơ trọng số pháp tuyến, b là hệ số lệch bias, và <w, x> biểu diễn phép tính tích vô hướng của hai vectơ.","Về mặt giả thuyết, thuật toán SVM đặt ra giả định ban đầu rằng tồn tại ít nhất một siêu phẳng tuyến tính có khả năng phân tách hoàn toàn hai lớp nhãn dương và âm mà không mắc lỗi. Điều kiện phân loại đúng yêu cầu mọi mẫu xi có nhãn yi = +1 phải thỏa mãn <w, xi> + b ≥ 0, và mọi mẫu có nhãn yi = -1 phải thỏa mãn <w, xi> + b < 0. Phương trình toán học này đóng vai trò là ranh giới quyết định (decision boundary) để mô hình gán nhãn cho các điểm dữ liệu mới dựa trên dấu của hàm f(x)."],"questions":[{"id":3,"text":"Cho tập dữ liệu huấn luyện D = {(x1, y1), (x2, y2), ..., (xr, yr)} trong không gian n chiều với nhãn lớp yi thuộc {-1, +1}. Giả thuyết phân tách tuyến tính và điều kiện phân loại đúng được phát biểu như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giá trị nhãn lớp yi nhận các giá trị xác suất liên tục nằm trong khoảng từ -1 đến 1 để phục vụ phân loại đa lớp."},{"k":"B","t":"Giả thuyết phân tách tuyến tính giả định tồn tại ít nhất một siêu phẳng phân chia hoàn toàn hai lớp nhãn mà không mắc lỗi."},{"k":"C","t":"Mọi mẫu thuộc lớp âm (yi = -1) đều phải thỏa mãn điều kiện tích vô hướng <w, xi> + b > 1."},{"k":"D","t":"Điều kiện phân loại đúng yêu cầu yi * (<w, xi> + b) ≥ 0 áp dụng cho tất cả r mẫu dữ liệu trong tập học."}],"answer":["B","D"]},{"id":4,"text":"Khi tập dữ liệu huấn luyện thỏa mãn điều kiện phân tách tuyến tính, thực tế sẽ tồn tại vô số siêu phẳng có thể chia tách chính xác hai lớp nhãn. Nguyên lý quyết định của SVM để chọn ra siêu phẳng tối ưu duy nhất là gì?","multiple":false,"options":[{"k":"A","t":"Chọn siêu phẳng có khoảng cách lề (margin) tới các điểm dữ liệu gần nhất của hai lớp đạt giá trị cực đại."},{"k":"B","t":"Chọn siêu phẳng đi qua giá trị trung bình cộng tọa độ của tất cả các mẫu thuộc lớp dương và lớp âm."},{"k":"C","t":"Chọn siêu phẳng tối thiểu hóa tổng khoảng cách Euclid tới tất cả các điểm dữ liệu trong tập học."},{"k":"D","t":"Chọn siêu phẳng chứa số lượng điểm dữ liệu nằm trực tiếp trên mặt phẳng ranh giới nhiều nhất."}],"answer":["A"]}]},{"id":3,"title":"Mức lề & Siêu phẳng Biên","summary":["Khi tập dữ liệu phân tách tuyến tính được, thực tế tồn tại vô số siêu phẳng khác nhau có thể phân chia chính xác hai lớp nhãn. SVM giải quyết sự nhập nhằng này bằng cách chọn siêu phẳng phân tách H0 nằm ở vị trí sao cho khoảng cách tới các điểm dữ liệu gần nhất của hai lớp đạt giá trị lớn nhất (Max-Margin). Hai siêu phẳng biên song song H+ (đi qua điểm dương x+ gần nhất: <w, x+> + b = 1) và H- (đi qua điểm âm x- gần nhất: <w, x-> + b = -1) được định nghĩa để kẹp chặt vùng ranh giới an toàn.","Ý nghĩa hình học của mức lề (Margin) là tổng khoảng cách d+ từ H0 tới H+ và d- từ H0 tới H-. Sử dụng công thức khoảng cách từ một điểm tới siêu phẳng d = |<w, x> + b| / ||w||, ta tính được d+ = 1 / ||w|| và d- = 1 / ||w||. Do đó, tổng độ rộng mức lề được xác định bằng công thức Margin = 2 / ||w||. Việc tối đa hóa khoảng không gian trống này giúp mô hình chống lại nhiễu biên và đạt mức sai số dự báo nhỏ nhất theo chứng minh của lý thuyết học máy."],"questions":[{"id":5,"text":"Xét hai siêu phẳng biên song song H+ (đi qua điểm dương x+ gần nhất) và H- (đi qua điểm âm x- gần nhất) nằm về hai phía của ranh giới H0: <w, x> + b = 0. Những nhận định nào sau đây là đúng? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Phương trình của hai siêu phẳng biên lần lượt là H+: <w, x+> + b = 1 và H-: <w, x-> + b = -1."},{"k":"B","t":"Mức lề Margin được tính bằng khoảng cách ngắn nhất từ gốc tọa độ tới siêu phẳng ranh giới H0."},{"k":"C","t":"Tổng độ rộng mức lề phân tách giữa hai siêu phẳng biên được xác định bằng công thức Margin = 2 / ||w||."},{"k":"D","t":"Trong dải không gian nằm giữa H+ và H- luôn tồn tại một số điểm dữ liệu nhiễu thuộc cả hai lớp."}],"answer":["A","C"]},{"id":6,"text":"Trong không gian vectơ n chiều, khoảng cách từ một điểm dữ liệu xi bất kỳ tới siêu phẳng phân tách H0: <w, x> + b = 0 được xác định bằng công thức toán học nào?","multiple":false,"options":[{"k":"A","t":"d = (<w, xi> + b) / <w, w>"},{"k":"B","t":"d = |<w, xi> + b| * ||w||"},{"k":"C","t":"d = |<w, xi> + b| / ||w||"},{"k":"D","t":"d = ||w|| / |<w, xi> + b|"}],"answer":["C"]}]},{"id":4,"title":"Bài toán Cực đại hóa Mức lề","summary":["Nguyên lý học lề cực đại của SVM được phát biểu dưới dạng bài toán tối ưu hóa quy hoạch bậc hai (Quadratic Programming). Mục tiêu cực đại hóa độ rộng mức lề Margin = 2 / ||w|| hoàn toàn tương đương với bài toán tối thiểu hóa độ dài vectơ trọng số ||w||, hay chính xác hơn là tối thiểu hóa hàm mục tiêu (1/2) * ||w||². Việc chuyển đổi sang dạng bình phương giúp loại bỏ dấu căn bậc hai và tạo ra một hàm lồi trơn dễ tính đạo hàm.","Cơ chế ràng buộc yêu cầu tất cả r mẫu dữ liệu huấn luyện phải nằm hoàn toàn bên ngoài dải lề phân tách. Điều kiện này được viết gộp thành tập bất đẳng thức yi * (<w, xi> + b) ≥ 1 với mọi i từ 1 đến r. Đây là bài toán tối ưu có ràng buộc bất đẳng thức tuyến tính ở dạng gốc (Primal Formulation), đảm bảo rằng mô hình không chỉ phân loại đúng nhãn mà còn duy trì khoảng cách an toàn tối thiểu bằng 1/||w|| tới siêu phẳng ranh giới."],"questions":[{"id":7,"text":"Phát biểu bài toán tối ưu hóa quy hoạch bậc hai dạng gốc (Primal Formulation) để tìm siêu phẳng có lề cực đại trong Hard-Margin SVM bao gồm những thành phần nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hàm mục tiêu yêu cầu cực đại hóa độ dài chuẩn vectơ trọng số ||w|| để mở rộng không gian tìm kiếm."},{"k":"B","t":"Bài toán quy về việc tối thiểu hóa hàm lồi trơn (1/2) * ||w||² (hoặc <w, w> / 2)."},{"k":"C","t":"Ràng buộc bất đẳng thức tuyến tính yêu cầu yi * (<w, xi> + b) ≥ 1 áp dụng với mọi mẫu xi (i = 1...r)."},{"k":"D","t":"Ràng buộc yêu cầu tất cả các biến trọng số wi bắt buộc phải nhận giá trị thực không âm."}],"answer":["B","C"]},{"id":8,"text":"Tại sao trong việc thiết lập bài toán tối ưu Hard-Margin SVM, người ta lại chuyển mục tiêu từ cực đại hóa Margin = 2 / ||w|| sang cực tiểu hóa (1/2) * ||w||²? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Phép biến đổi sang (1/2) * ||w||² giúp triệt tiêu căn bậc hai, tạo ra hàm lồi trơn dễ tính đạo hàm."},{"k":"B","t":"Cực tiểu hóa (1/2) * ||w||² giúp loại bỏ hoàn toàn hệ số bias b ra khỏi phương trình siêu phẳng."},{"k":"C","t":"Bài toán cực tiểu hóa (1/2) * ||w||² đảm bảo nghiệm thu được luôn là cực trị toàn cục duy nhất."},{"k":"D","t":"Hai bài toán này cho ra hai bộ trọng số w khác nhau nhưng cùng chung ranh giới quyết định."}],"answer":["A","C"]}]},{"id":5,"title":"Hàm Lagrange & Biến Đối ngẫu","summary":["Để giải bài toán tối ưu lồi có ràng buộc bất đẳng thức, phương pháp nhân tử Lagrange được áp dụng để đưa các điều kiện ràng buộc vào hàm mục tiêu. Hàm Lagrange dạng gốc LP(w, b, α) được xây dựng bằng cách lấy hàm mục tiêu trừ đi tổng các ràng buộc có gia trọng: LP(w, b, α) = (1/2) * <w, w> - Σ αi * [yi * (<w, xi> + b) - 1]. Trong đó, αi ≥ 0 là các hệ số nhân Lagrange tương ứng với từng mẫu dữ liệu thứ i.","Ý nghĩa của hàm Lagrange là chuyển bài toán tìm cực tiểu có ràng buộc rắc rối thành bài toán tìm điểm yên ngựa (saddle point) minimax không ràng buộc: cực tiểu hóa LP theo các biến gốc (w, b) và cực đại hóa theo các biến đối ngẫu αi ≥ 0. Các biến gốc w và b trực tiếp định hình vị trí siêu phẳng, trong khi mỗi biến đối ngẫu αi đóng vai trò như một lực phạt đo lường mức độ ảnh hưởng hoặc ép buộc của mẫu dữ liệu xi lên vị trí siêu phẳng."],"questions":[{"id":9,"text":"Để đưa bài toán tối ưu có ràng buộc bất đẳng thức về dạng không ràng buộc, hàm Lagrange gốc LP(w, b, α) được xây dựng như thế nào và chứa các loại biến nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hàm Lagrange được định nghĩa bằng công thức LP = (1/2)*<w, w> + Σ αi * [yi*(<w, xi> + b) - 1]."},{"k":"B","t":"Các hệ số nhân Lagrange αi tương ứng với từng ràng buộc được phép nhận giá trị thực tùy ý."},{"k":"C","t":"Hàm Lagrange có dạng LP = (1/2)*<w, w> - Σ αi * [yi*(<w, xi> + b) - 1] với điều kiện αi ≥ 0."},{"k":"D","t":"Biến w, b được gọi là các biến gốc (primal variables), còn αi được gọi là các biến đối ngẫu (dual variables)."}],"answer":["C","D"]},{"id":10,"text":"Việc giải bài toán tối ưu hàm Lagrange LP(w, b, α) tương đương với việc tìm điểm yên ngựa (saddle point) minimax nào trong không gian tham số?","multiple":false,"options":[{"k":"A","t":"argmax_{w,b} min_{α ≥ 0} LP(w, b, α)"},{"k":"B","t":"argmin_{w,b} max_{α ≥ 0} LP(w, b, α)"},{"k":"C","t":"argmax_{w,b,α} LP(w, b, α)"},{"k":"D","t":"argmin_{w,b,α} LP(w, b, α)"}],"answer":["B"]}]},{"id":6,"title":"Bộ Điều kiện Karush-Kuhn-Tucker (KKT)","summary":["Theo lý thuyết tối ưu lồi, nghiệm tối ưu toàn cục của hàm Lagrange bắt buộc phải thỏa mãn bộ điều kiện Karush-Kuhn-Tucker (KKT). Lấy đạo hàm riêng của LP theo biến w và b rồi gán bằng 0 cho ta các phương trình: w = Σ αi * yi * xi và Σ αi * yi = 0. Đồng thời, điều kiện bổ sung bù (complementary slackness) yêu cầu tích αi * [yi * (<w, xi> + b) - 1] = 0 với mọi i.","Mục đích của điều kiện bù KKT là tạo ra tính thưa (sparsity) cho mô hình thông qua sự phân hóa giá trị αi. Đối với các mẫu nằm an toàn ngoài dải lề (yi * (<w, xi> + b) > 1), điều kiện KKT bắt buộc hệ số αi = 0. Ngược lại, chỉ những mẫu nằm ngay sát trên hai đường lề biên H+ hoặc H- (yi * (<w, xi> + b) = 1) mới có αi > 0; các điểm dữ liệu đặc biệt này được định nghĩa là các Vectơ hỗ trợ (Support Vectors - SV)."],"questions":[{"id":11,"text":"Xét bộ điều kiện Karush-Kuhn-Tucker (KKT) áp dụng cho bài toán tối ưu Hard-Margin SVM. Những kết quả đạo hàm riêng và điều kiện bổ sung nào sau đây là chính xác? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Đạo hàm theo vectơ trọng số cho kết quả w = Σ αi * yi * xi (i = 1...r)."},{"k":"B","t":"Đạo hàm theo hệ số bias cho kết quả phương trình cân bằng nhãn Σ αi * yi = 0 (i = 1...r)."},{"k":"C","t":"Điều kiện bổ sung bù yêu cầu αi + [yi * (<w, xi> + b) - 1] = 0 áp dụng cho mọi mẫu huấn luyện."},{"k":"D","t":"Tất cả các hệ số nhân Lagrange αi bắt buộc phải nhận giá trị lớn hơn 1 tại điểm tối ưu."}],"answer":["A","B"]},{"id":12,"text":"Theo lý thuyết đối ngẫu KKT, điều kiện bổ sung bù αi * [yi * (<w, xi> + b) - 1] = 0 giúp xác định các điểm Vectơ hỗ trợ (Support Vectors) như thế nào?","multiple":false,"options":[{"k":"A","t":"Tất cả các điểm dữ liệu trong tập học đều có αi > 0 và đóng vai trò là Support Vectors."},{"k":"B","t":"Điểm nằm an toàn ngoài dải lề có yi * (<w, xi> + b) > 1 sẽ tương ứng với giá trị αi > 0."},{"k":"C","t":"Điểm bị phân loại sai nhãn sẽ có giá trị αi = 0 và bị triệt tiêu khỏi phương trình ranh giới."},{"k":"D","t":"Chỉ những điểm nằm đúng trên siêu phẳng lề (H+ hoặc H-) mới có αi > 0, được gọi là Support Vectors."}],"answer":["D"]}]},{"id":7,"title":"Dạng Đối ngẫu (Dual Form)","summary":["Bằng cách thế các quan hệ đạo hàm KKT (w = Σ αi * yi * xi và Σ αi * yi = 0) ngược lại vào hàm Lagrange gốc LP, các biến gốc w và b bị triệt tiêu hoàn toàn. Kết quả thu được là bài toán đối ngẫu LD(α) chỉ phụ thuộc vào các biến đối ngẫu α: cực đại hóa LD(α) = Σ αi - (1/2) * Σ Σ αi * αj * yi * yj * <xi, xj>. Ràng buộc đối ngẫu bao gồm Σ αi * yi = 0 và αi ≥ 0 với mọi i.","Về mặt nguyên lý, bài toán đối ngẫu dễ giải quyết hơn rất nhiều so với bài toán gốc nhờ tập ràng buộc tuyến tính đơn giản. Điểm quan trọng nhất là dữ liệu đầu vào xi chỉ xuất hiện dưới dạng tích vô hướng <xi, xj> thay vì các tọa độ vectơ riêng lẻ. Cấu trúc toán học này chính là chìa khóa mở ra khả năng mở rộng thuật toán sang các không gian đặc trưng phi tuyến số chiều lớn ở các phần tiếp theo."],"questions":[{"id":13,"text":"Bằng cách thế các quan hệ KKT vào hàm Lagrange gốc, bài toán đối ngẫu LD(α) và các ràng buộc đi kèm được phát biểu ở dạng nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Hàm mục tiêu đối ngẫu là bài toán cực tiểu hóa LD(α) = Σ αi + (1/2) * Σ Σ αi * αj * yi * yj * <xi, xj>."},{"k":"B","t":"Hàm mục tiêu đối ngẫu là cực đại hóa LD(α) = Σ αi - (1/2) * Σ Σ αi * αj * yi * yj * <xi, xj>."},{"k":"C","t":"Tập ràng buộc đối ngẫu bao gồm hai điều kiện đơn giản: Σ αi * yi = 0 và αi ≥ 0 (với mọi i = 1...r)."},{"k":"D","t":"Hàm mục tiêu đối ngẫu bắt buộc phải tính toán trực tiếp các hệ số trọng số gốc w và bias b."}],"answer":["B","C"]},{"id":14,"text":"So với bài toán tối ưu gốc (Primal Form), bài toán đối ngẫu (Dual Form) của Hard-Margin SVM sở hữu những lợi thế kỹ thuật cốt lõi nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Ràng buộc của bài toán đối ngẫu (αi ≥ 0 và Σ αi * yi = 0) đơn giản hơn rất nhiều so với bài toán gốc."},{"k":"B","t":"Bài toán đối ngẫu giúp giảm số lượng biến tối ưu từ r biến đối ngẫu xuống chỉ còn n biến trọng số."},{"k":"C","t":"Dữ liệu huấn luyện xi chỉ xuất hiện dưới dạng tích vô hướng <xi, xj>, mở ra cửa ngõ áp dụng Kernel Trick."},{"k":"D","t":"Bài toán đối ngẫu cho phép tìm ra nghiệm tối ưu trực tiếp bằng phép nghịch đảo ma trận O(1)."}],"answer":["A","C"]}]},{"id":8,"title":"Phán đoán Mẫu mới","summary":["Sau khi giải bài toán đối ngẫu thu được bộ hệ số α*, các tham số tối ưu w* và b* của siêu phẳng được khôi phục hoàn toàn thông qua các điều kiện KKT. Vectơ pháp tuyến w* được tính bằng công thức w* = Σ αi * yi * xi (chỉ cần tính tổng trên tập các Support Vectors do αj = 0 với các điểm ngoài lề). Bias b* được xác định bằng cách chọn một Support Vector xk (có αk > 0) và tính b* = yk - <w*, xk>.","Cơ chế phân loại một mẫu dữ liệu mới z dựa trên hàm phán đoán f(z) = sign(<w*, z> + b*), tương đương f(z) = sign(Σ αi * yi * <xi, z> + b*) với i thuộc tập Support Vectors. Việc phán đoán nhãn hoàn toàn không phụ thuộc vào toàn bộ tập dữ liệu gốc mà chỉ cần thực hiện phép tính tích vô hướng giữa mẫu z và một số ít các Support Vectors. Điều này giúp tốc độ phân loại đạt hiệu năng cực kỳ nhanh chóng trong thực thi."],"questions":[{"id":15,"text":"Sau khi giải bài toán đối ngẫu thu được bộ hệ số α*, các tham số tối ưu w*, b* và hàm phán đoán nhãn cho mẫu mới z được xác định như thế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Vectơ trọng số tối ưu w* được tính bằng tổng w* = Σ αi * yi * xi áp dụng riêng cho tập Support Vectors (SV)."},{"k":"B","t":"Bias b* được tính toán bằng trung bình cộng của tất cả các giá trị αi trong tập dữ liệu huấn luyện."},{"k":"C","t":"Hàm phán đoán nhãn cho mẫu z phụ thuộc vào tọa độ của tất cả các điểm dữ liệu trong tập học ban đầu."},{"k":"D","t":"Quy tắc phân loại mẫu z dựa vào dấu của hàm f(z) = sign(Σ αi * yi * <xi, z> + b*) với xi thuộc tập SV."}],"answer":["A","D"]},{"id":16,"text":"Tính chất \"thưa\" (sparsity) của mô hình SVM thể hiện ở điểm nào trong quá trình phân loại mẫu dữ liệu mới?","multiple":false,"options":[{"k":"A","t":"Kết quả phán đoán chỉ phụ thuộc vào tích vô hướng với một tập con nhỏ các Support Vectors (αi > 0)."},{"k":"B","t":"Vectơ trọng số w* có tất cả các thành phần tọa độ bị triệt tiêu về giá trị bằng 0."},{"k":"C","t":"Ma trận dữ liệu đầu vào xi phải chứa đa số các khoảng trắng hoặc giá trị không (0)."},{"k":"D","t":"Mô hình loại bỏ hoàn toàn thành phần bias b* để đơn giản hóa phép tính tích vô hướng."}],"answer":["A"]}]},{"id":9,"title":"Soft-Margin SVM","summary":["Trong thực tế áp dụng, giả thuyết phân tách tuyến tính tuyệt đối thường không thỏa mãn do dữ liệu chứa nhiễu, lỗi gán nhãn, hoặc hai lớp nằm chồng lấn lên nhau. Khi đó, các ràng buộc Hard-Margin không thể thỏa mãn đồng thời khiến bài toán tối ưu bị vô nghiệm. Để khắc phục, mô hình Soft-Margin SVM được đề xuất bằng cách bổ sung các biến nới lỏng (slack variables) ξi ≥ 0, cho phép các điểm dữ liệu vi phạm lề một khoảng bằng ξi.","Hàm mục tiêu mới của Soft-Margin SVM cân bằng giữa việc cực đại hóa lề và tối thiểu hóa tổng sai số vi phạm: tối thiểu hóa (1/2) * ||w||² + C * Σ ξi dưới ràng buộc yi * (<w, xi> + b) ≥ 1 - ξi và ξi ≥ 0. Hằng số C > 0 đóng vai trò là tham số phạt (penalty constant); C càng lớn thì mức phạt đối với lỗi vi phạm càng cao. Bài toán này hoàn toàn tương đương với việc tối thiểu hóa hàm mất mát Hinge Loss max(0, 1 - yi * f(xi)) kết hợp thành phần hiệu chỉnh Ridge."],"questions":[{"id":17,"text":"Khi dữ liệu huấn luyện chứa nhiễu hoặc chồng lấn không thể phân tách tuyến tính tuyệt đối, mô hình Soft-Margin SVM giải quyết bằng cơ chế nào? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Bắt buộc thuật toán phải lặp vô hạn cho đến khi tìm được siêu phẳng phân tách hoàn toàn các điểm nhiễu."},{"k":"B","t":"Bổ sung các biến nới lỏng (slack variables) ξi ≥ 0 cho phép một số mẫu vi phạm dải lề."},{"k":"C","t":"Đưa thành phần phạt chi phí C * Σ ξi vào hàm mục tiêu tối thiểu hóa (1/2)*<w, w> + C * Σ ξi."},{"k":"D","t":"Loại bỏ hoàn bộ các điểm dữ liệu vi phạm ra khỏi tập học trước khi tiến hành tối ưu hóa."}],"answer":["B","C"]},{"id":18,"text":"Bài toán tối ưu Soft-Margin SVM dạng gốc với hằng số phạt C > 0 tương đương với bài toán tối thiểu hóa hàm mất mát trơn nào trong học máy?","multiple":false,"options":[{"k":"A","t":"Tối thiểu hóa hàm mất mát Lỗi bình phương (Square Loss) kết hợp chuẩn L1."},{"k":"B","t":"Tối thiểu hóa hàm mất mát En-trô-pi chéo (Cross-Entropy Loss) kết hợp chuẩn L2."},{"k":"C","t":"Tối thiểu hóa hàm mất mát Hinge Loss max(0, 1 - yi * f(xi)) kết hợp đại lượng hiệu chỉnh Ridge."},{"k":"D","t":"Tối thiểu hóa hàm mất mát Tuyệt đối (Absolute Loss) kết hợp chuẩn Lasso."}],"answer":["C"]}]},{"id":10,"title":"Ràng buộc Hộp (Box Constraints)","summary":["Khi thiết lập hàm Lagrange cho Soft-Margin SVM, hai tập hệ số nhân αi ≥ 0 và μi ≥ 0 được sử dụng tương ứng cho ràng buộc lề nới lỏng và ràng buộc ξi ≥ 0. Lấy đạo hàm riêng theo ξi cho phương trình C - αi - μi = 0, từ đó suy ra αi ≤ C. Kết quả là bài toán đối ngẫu giữ nguyên hàm mục tiêu LD(α) như trường hợp Hard-Margin, nhưng tập ràng buộc được bổ sung ràng buộc hộp (box constraint): 0 ≤ αi ≤ C.","Ý nghĩa kỹ thuật của ràng buộc hộp 0 ≤ αi ≤ C là phân loại vị trí của mọi mẫu huấn luyện dựa trên giá trị αi. Nếu αi = 0, mẫu nằm an toàn ngoài lề (không có lỗi ξi = 0). Nếu 0 < αi < C, mẫu nằm đúng trên siêu phẳng lề biên (Support Vector chuẩn, ξi = 0) và được dùng để tính bias b*. Nếu αi = C, mẫu nằm bên trong vùng lề hoặc bị phân loại sai (nhiễu/lỗi với ξi > 0). Việc điều chỉnh C bằng tập kiểm chứng (validation set) giúp kiểm soát linh hoạt hiện tượng quá khớp."],"questions":[{"id":19,"text":"Khi thiết lập hàm Lagrange và giải bài toán đối ngẫu cho Soft-Margin SVM, sự xuất hiện của các điều kiện KKT mở rộng dẫn đến ràng buộc hộp (box constraint) và sự phân loại điểm dữ liệu ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Ràng buộc biến đối ngẫu được bổ sung chặn trên tạo thành ràng buộc hộp 0 ≤ αi ≤ C."},{"k":"B","t":"Các điểm dữ liệu nằm an toàn ngoài dải lề (không có lỗi ξi = 0) sẽ tương ứng với giá trị αi = C."},{"k":"C","t":"Các điểm nằm đúng trên đường lề (Support Vector chuẩn với ξi = 0) có giá trị biến đối ngẫu 0 < αi < C."},{"k":"D","t":"Các điểm dữ liệu bị nhiễu hoặc phân loại sai (ξi > 0) sẽ có giá trị biến đối ngẫu αi = 0."}],"answer":["A","C"]},{"id":20,"text":"Siêu tham số phạt C trong Soft-Margin SVM đóng vai trò kỹ thuật gì và ảnh hưởng như thế nào đến mô hình? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Giá trị C kiểm soát mức độ đánh đổi giữa khoảng rộng của lề và tổng chi phí vi phạm lỗi."},{"k":"B","t":"Nếu chọn C rất nhỏ, mô hình sẽ phạt cực kỳ nặng các điểm vi phạm và dễ dẫn đến hiện tượng quá khớp (overfitting)."},{"k":"C","t":"Nếu chọn C quá lớn, mô hình đặt mức phạt cao lên các lỗi, cố gắng phân loại đúng tập học và có thể gây quá khớp."},{"k":"D","t":"Siêu tham số C có thể tự động tính toán được từ đạo hàm hàm Lagrange mà không cần dùng tập kiểm chứng (validation set)."}],"answer":["A","C"]}]},{"id":11,"title":"Ánh xạ Không gian Đặc trưng","summary":["Khi tập dữ liệu gốc không thể phân tách tuyến tính bằng bất kỳ siêu phẳng nào trong không gian đầu vào (Input Space) X, việc áp dụng mô hình tuyến tính trực tiếp sẽ cho độ chính xác rất thấp. Ý tưởng của Non-linear SVM là sử dụng một ánh xạ phi tuyến φ: X → F để chuyển đổi dữ liệu từ không gian đầu vào X sang một không gian đặc trưng mới (Feature Space) F có số chiều cao hơn.","Mục đích của việc tăng số chiều là đưa tập dữ liệu về trạng thái phân tách tuyến tính được trong không gian mới F. Sau khi ánh xạ tập huấn luyện thành {(φ(x1), y1), ..., (φ(xr), yr)}, một siêu phẳng tuyến tính tiêu chuẩn sẽ được dựng lên trong không gian đặc trưng F. Ranh giới quyết định tuyến tính trong không gian F khi chiếu ngược về không gian đầu vào X sẽ tạo thành một đường biên phân tách phi tuyến uốn lượn phức tạp."],"questions":[{"id":21,"text":"Đối với tập dữ liệu phi tuyến không thể phân tách trong không gian đầu vào X, ý tưởng nâng chiều dữ liệu và hạn chế \"lời nguyền số chiều\" (curse of dimensionality) được mô tả ra sao? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Sử dụng ánh xạ phi tuyến φ: X → F để đưa dữ liệu sang không gian đặc trưng F có số chiều cao hơn."},{"k":"B","t":"Việc tăng số chiều không gian giúp chuyển tập dữ liệu phi tuyến về trạng thái phân tách tuyến tính được."},{"k":"C","t":"Lời nguyền số chiều giúp dữ liệu trong không gian mới trở nên dày đặc, làm giảm số lượng dữ liệu cần thiết."},{"k":"D","t":"Ánh xạ φ bắt buộc phải được biểu diễn dưới dạng các hàm đại số tuyến tính có số chiều hữu hạn dưới 10."}],"answer":["A","B"]},{"id":22,"text":"Khi dựng một siêu phẳng phân tách tuyến tính trong không gian đặc trưng F nhiều chiều, hình ảnh của ranh giới quyết định đó khi chiếu ngược về không gian đầu vào X ban đầu sẽ có dạng gì?","multiple":false,"options":[{"k":"A","t":"Bắt buộc phải là một đường thẳng hoặc mặt phẳng tuyến tính song song với các trục tọa độ."},{"k":"B","t":"Là một đường biên hoặc mặt ranh giới phân tách phi tuyến uốn lượn phức tạp."},{"k":"C","t":"Biến thành một tập hợp các điểm rời rạc không liên tục trong không gian đầu vào."},{"k":"D","t":"Tự động thu gọn thành một điểm tâm duy nhất phân phân cụm dữ liệu."}],"answer":["B"]}]},{"id":12,"title":"Kỹ thuật Kernel (Kernel Trick)","summary":["Mặc dù chiếu dữ liệu lên không gian chiều cao giúp phân tách tuyến tính, việc tính toán trực tiếp tọa độ ánh xạ φ(x) gặp phải \"lời nguyền số chiều\" (curse of dimensionality) khiến không gian trở nên quá thưa thớt và tốn chi phí tính toán bùng nổ. Tuy nhiên, bài toán đối ngẫu LD(α) và hàm phán đoán f(z) chỉ yêu cầu duy nhất kết quả phép tính tích vô hướng <φ(xi), φ(xj)> trong không gian mới.","Kỹ thuật Kernel (Kernel Trick) giải quyết rào cản tính toán bằng cách thay thế trực tiếp tích vô hướng <φ(xi), φ(xj)> bằng một hàm nhân K(xi, xj) = <φ(xi), φ(xj)>. Nhờ đó, mô hình tính toán được giá trị tích vô hướng ở không gian chiều cao ngay tại không gian đầu vào mà không cần biết hay biểu diễn tường minh biểu thức ánh xạ φ. Định lý Mercer đưa ra điều kiện cần và đủ để một hàm K(x, z) hợp lệ làm một hàm nhân Kernel."],"questions":[{"id":23,"text":"Bản chất kỹ thuật của Kỹ thuật Kernel (Kernel Trick) và vai trò của Định lý Mercer trong Non-linear SVM là gì? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Kỹ thuật Kernel yêu cầu phải tính toán tường minh tọa độ ánh xạ φ(x) trước khi tính tích vô hướng."},{"k":"B","t":"Kỹ thuật Kernel thay thế tích vô hướng <φ(x), φ(z)> bằng hàm nhân K(x, z) = <φ(x), φ(z)> thực hiện ở không gian gốc."},{"k":"C","t":"Định lý Mercer đưa ra các điều kiện toán học để một hàm K(x, z) hợp lệ làm một hàm nhân Kernel."},{"k":"D","t":"Hàm nhân Kernel chỉ hoạt động được khi không gian đặc trưng F có số chiều nhỏ hơn không gian đầu vào X."}],"answer":["B","C"]},{"id":24,"text":"Tại sao bài toán đối ngẫu (Dual Form) lại được coi là \"cánh cửa vàng\" cho phép SVM áp dụng Kỹ thuật Kernel một cách dễ dàng?","multiple":false,"options":[{"k":"A","t":"Vì bài toán đối ngẫu giúp loại bỏ hoàn toàn các biến đối ngẫu αi ra khỏi hàm phán đoán."},{"k":"B","t":"Vì bài toán đối ngẫu không yêu cầu sử dụng các thuật toán lặp để tìm điểm cực trị lồi."},{"k":"C","t":"Vì bài toán đối ngẫu cho phép tính toán trực tiếp vectơ pháp tuyến w* mà không cần đến Support Vectors."},{"k":"D","t":"Vì trong bài toán đối ngẫu và hàm phán đoán, dữ liệu chỉ xuất hiện dưới dạng tích vô hướng <xi, xj>."}],"answer":["D"]}]},{"id":13,"title":"Các Hàm Kernel & Đa lớp","summary":["Các hàm Kernel thông dụng được áp dụng phổ biến trong thực tế bao gồm: Polynomial Kernel K(x, z) = (<x, z> + θ)^d, Gaussian RBF Kernel K(x, z) = exp(-||x - z||² / (2σ²)), và Sigmoid Kernel K(x, z) = tanh(β * <x, z> - λ). Để giải quyết các bài toán phân loại đa lớp (> 2 lớp), SVM kết hợp các phương pháp quy đổi về chuỗi bài toán nhị phân như One-vs-Rest (OvR) hoặc One-vs-One (OvO).","Về mặt thực thi phần mềm, các thư viện mã nguồn mở tối ưu như LibSVM, LibLinear, SVMlight hay module Scikit-learn trong Python cung cấp các công cụ mạnh mẽ để huấn luyện mô hình SVM. Nhờ sự kết hợp giữa Kernel Trick và đặc tính thưa của các Support Vectors, SVM duy trì tốc độ xử lý nhanh và độ chính xác cao. Tuy nhiên, nhược điểm lớn nhất là hàm phán đoán sau khi dùng Kernel phi tuyến trở nên cực kỳ phức tạp và rất khó giải thích ý nghĩa logic đối với người dùng.","B. Bài tập tham khảo"],"questions":[{"id":25,"text":"Xét các hàm nhân Kernel phổ biến và kỹ thuật mở rộng SVM cho bài toán phân loại đa lớp (> 2 lớp). Những phát biểu nào sau đây là đúng? (Chọn 2 đáp án đúng)","multiple":true,"options":[{"k":"A","t":"Gaussian RBF Kernel có dạng K(x, z) = exp(-||x - z||² / (2σ²)) với tham số σ > 0."},{"k":"B","t":"Kỹ thuật One-vs-Rest (OvR) và One-vs-One (OvO) giúp quy đổi bài toán đa lớp về chuỗi các bài toán phân loại nhị phân."},{"k":"C","t":"Polynomial Kernel K(x, z) = (<x, z> + θ)^d yêu cầu bậc d phải là một số thực âm."},{"k":"D","t":"Sigmoid Kernel phân loại đa lớp trực tiếp bằng cách tính tổng xác suất Cross-Entropy trên tất cả các lớp."}],"answer":["A","B"]},{"id":26,"text":"Mặc dù sở hữu độ chính xác cao và khả năng tổng quát hóa tốt, hạn chế kỹ thuật lớn nhất của mô hình Non-linear SVM khi áp dụng các hàm Kernel phi tuyến phức tạp là gì?","multiple":false,"options":[{"k":"A","t":"Mô hình bị suy giảm độ chính xác nghiêm trọng khi gặp dữ liệu có số chiều rất lớn."},{"k":"B","t":"Yêu cầu toàn bộ tập dữ liệu huấn luyện phải được lưu trữ trong bộ nhớ để thực hiện phán đoán."},{"k":"C","t":"Hàm phán đoán trở nên phức tạp và mang tính chất \"hộp đen\", rất khó giải thích ý nghĩa logic đối với người dùng."},{"k":"D","t":"Mô hình hoàn toàn không thể kết hợp với các kỹ thuật tối ưu hóa quy hoạch bậc hai."}],"answer":["C"]}]}]}]};
